// A five-year import can occupy at most every hourly bucket between the
// one-day raw frontier and day 91 (including the UTC day's final partial hour),
// then every complete 3h, 6h, and daily bucket in the negotiated traffic tiers.
// This is a shape proof, not a runtime cap.
const FIVE_YEAR_IMPORT_MAX_ROLLUP_ROWS: i64 =
    ((91 - TRAFFIC_COUNTER_RAW_RETENTION_DAYS) as i64 * 24 + 23)
        + ((181 - 91) * 8)
        + ((366 - 181) * 4)
        + (5 * 365 - 366);

async fn drain_job_output_terminal_workflow(state: &crate::state::AppState) {
    crate::repository_job_outputs::drain_job_output_projections_for_test(&state.repo)
        .await
        .unwrap();
    crate::job_dispatcher::drain_job_terminal_workflow_for_test(state)
        .await
        .unwrap();
}

#[tokio::test]
async fn postgres_file_transfer_handoff_job_discovery_is_index_bounded() {
    let Some(db) = PgReliabilityTestDb::maybe_new().await else {
        return;
    };
    let session_id = Uuid::parse_str("f1000000-0000-4000-8000-000000000001").unwrap();
    let target_job_id = Uuid::parse_str("f2000000-0000-4000-8000-000000000001").unwrap();
    sqlx::query(
        r#"
        INSERT INTO jobs (
            id,command_type,status,target_count,payload_hash,
            operation,request_fingerprint,completed_at
        )
        SELECT
            md5('handoff-unrelated-shell-' || item)::uuid,
            'shell_argv','completed',0,
            md5('handoff-unrelated-shell-payload-' || item),
            NULL,
            'handoff-unrelated-shell-request-' || item,
            now() - interval '30 days'
        FROM generate_series(1,30000) item
        "#,
    )
    .execute(&db.pool)
    .await
    .unwrap();
    sqlx::query(
        r#"
        INSERT INTO jobs (
            id,command_type,status,target_count,payload_hash,
            operation,request_fingerprint,completed_at
        )
        SELECT
            md5('handoff-unrelated-download-' || item)::uuid,
            'file_transfer_download_chunk','completed',0,
            md5('handoff-unrelated-download-payload-' || item),
            jsonb_build_object(
                'type','file_transfer_download_chunk',
                'session_id',(md5('handoff-unrelated-session-' || item)::uuid)::text,
                'offset',0,
                'max_bytes',65536,
                'resume_token_hash','fixture'
            ),
            'handoff-unrelated-download-request-' || item,
            now() - interval '30 days'
        FROM generate_series(1,10000) item
        "#,
    )
    .execute(&db.pool)
    .await
    .unwrap();
    sqlx::query(
        r#"
        INSERT INTO jobs (
            id,command_type,status,target_count,payload_hash,
            operation,request_fingerprint,completed_at
        ) VALUES (
            $1,'file_transfer_download_chunk','completed',0,'handoff-target-payload',
            jsonb_build_object(
                'type','file_transfer_download_chunk',
                'session_id',$2::uuid::text,
                'offset',0,
                'max_bytes',65536,
                'resume_token_hash','fixture'
            ),
            'handoff-target-request',now()
        )
        "#,
    )
    .bind(target_job_id)
    .bind(session_id)
    .execute(&db.pool)
    .await
    .unwrap();
    sqlx::query("ANALYZE jobs").execute(&db.pool).await.unwrap();

    let index_definition: String = sqlx::query_scalar(
        r#"
        SELECT indexdef
        FROM pg_indexes
        WHERE schemaname='public'
          AND indexname='jobs_file_transfer_download_resource_idx'
        "#,
    )
    .fetch_one(&db.pool)
    .await
    .unwrap();
    assert!(
        index_definition.contains("(resource_id, id)"),
        "{index_definition}"
    );
    assert!(
        index_definition.contains("resource_kind = 'file_transfer_session'::text"),
        "{index_definition}"
    );
    assert_eq!(
        sqlx::query_scalar::<_, i64>(
            r#"
            SELECT count(*)
            FROM jobs
            WHERE resource_kind='file_transfer_session'
              AND resource_id=$1
              AND command_type='file_transfer_download_chunk'
            "#,
        )
        .bind(session_id)
        .fetch_one(&db.pool)
        .await
        .unwrap(),
        1
    );

    let plan: Value = sqlx::query_scalar(
        r#"
        EXPLAIN (ANALYZE,BUFFERS,FORMAT JSON)
        WITH evidence_requests AS MATERIALIZED (
            SELECT
                0::bigint AS request_index,
                'handoff-plan-client'::text AS client_id,
                $1::uuid AS session_id,
                FALSE AS final_artifact_available
        ), chunk_jobs AS MATERIALIZED (
            SELECT request.request_index,request.client_id,job.id AS job_id
            FROM jobs job
            JOIN evidence_requests request
              ON NOT request.final_artifact_available
             AND job.resource_id=request.session_id
            WHERE job.resource_kind='file_transfer_session'
              AND job.command_type='file_transfer_download_chunk'
        )
        SELECT * FROM chunk_jobs
        "#,
    )
    .bind(session_id)
    .fetch_one(&db.pool)
    .await
    .unwrap();
    let plan_root = &plan[0]["Plan"];
    let plan_text = plan.to_string();
    assert!(
        plan_text.contains("jobs_file_transfer_download_resource_idx"),
        "handoff discovery did not use its normalized resource index: {plan_text}"
    );
    assert!(
        !explain_relation_uses_sequential_scan(plan_root, "jobs"),
        "handoff discovery scanned unrelated job history: {plan_text}"
    );
    let mut index_conditions = Vec::new();
    collect_explain_index_conditions(
        plan_root,
        "jobs_file_transfer_download_resource_idx",
        &mut index_conditions,
    );
    assert!(
        index_conditions
            .iter()
            .any(|condition| condition.contains("resource_id")),
        "handoff index did not own the requested session: {plan_text}"
    );
    let relation_sizes: (i64, i64) = sqlx::query_as(
        r#"
        SELECT
            pg_relation_size('jobs'),
            pg_relation_size('jobs_file_transfer_download_resource_idx')
        "#,
    )
    .fetch_one(&db.pool)
    .await
    .unwrap();
    assert!(relation_sizes.1 > 0 && relation_sizes.1 < relation_sizes.0);
    eprintln!(
        "file-transfer handoff partial index bytes: jobs={}, index={}",
        relation_sizes.0, relation_sizes.1
    );

    sqlx::query(
        r#"
        WITH inserted_client AS (
            INSERT INTO clients (id,display_name,public_key,status)
            VALUES (
                'handoff-plan-client',
                'handoff-plan-client',
                decode(repeat('11',32),'hex'),
                'online'
            )
            RETURNING id
        ), updated_job AS (
            UPDATE jobs
            SET target_count=1
            FROM inserted_client
            WHERE jobs.id=$1
            RETURNING jobs.id
        ), inserted_target AS (
            INSERT INTO job_targets (job_id,client_id,status,completed_at)
            SELECT id,'handoff-plan-client','completed',now()
            FROM updated_job
            RETURNING job_id
        ), inserted_status AS (
            INSERT INTO job_outputs (job_id,client_id,seq,stream,data,storage,done)
            SELECT
            job_id,
            'handoff-plan-client',
            0,
            'status',
            convert_to(
                jsonb_build_object(
                    'type','file_transfer_download_chunk',
                    'session_id',$2::uuid::text,
                    'extra',jsonb_build_object(
                        'offset',0,
                        'chunk_size_bytes',8388608,
                        'chunk_sha256_hex',repeat('a',64)
                    )
                )::text,
                'UTF8'
            ),
            'inline',
            false
            FROM inserted_target
            RETURNING job_id
        )
        INSERT INTO job_outputs (job_id,client_id,seq,stream,data,storage,done)
        SELECT
            inserted_status.job_id,
            'handoff-plan-client',
            part,
            'stdout',
            convert_to(repeat('x',65536),'UTF8'),
            'inline',
            part=128
        FROM inserted_status
        CROSS JOIN generate_series(1,128) part
        "#,
    )
    .bind(target_job_id)
    .bind(session_id)
    .execute(&db.pool)
    .await
    .unwrap();
    let batch_rows =
        sqlx::query(crate::repository_file_transfers::FILE_TRANSFER_HANDOFF_EVIDENCE_SQL)
            .bind(vec![0_i64])
            .bind(vec!["handoff-plan-client".to_string()])
            .bind(vec![session_id])
            .bind(vec!["b".repeat(64)])
            .bind(vec![8_388_608_i64])
            .bind(vec!["file-transfers/missing".to_string()])
            .fetch_all(&db.pool)
            .await
            .unwrap();
    assert_eq!(
        batch_rows.len(),
        1,
        "one result row must represent one chunk job"
    );
    assert_eq!(
        batch_rows[0].try_get::<Uuid, _>("output_job_id").unwrap(),
        target_job_id
    );
    let status_outputs = batch_rows[0]
        .try_get::<Vec<Vec<u8>>, _>("status_outputs")
        .unwrap();
    let stdout_sizes = batch_rows[0]
        .try_get::<Vec<i64>, _>("stdout_sizes")
        .unwrap();
    let stdout_available = batch_rows[0]
        .try_get::<Vec<bool>, _>("stdout_available")
        .unwrap();
    assert_eq!(status_outputs.len(), 1);
    assert_eq!(stdout_sizes, vec![65_536; 128]);
    assert_eq!(stdout_available, vec![true; 128]);

    db.cleanup().await;
}

#[tokio::test]
async fn postgres_exact_job_target_status_batch_route_is_pairwise_ordered_and_fail_closed() {
    let Some(db) = PgReliabilityTestDb::maybe_new().await else {
        return;
    };
    let (_operator, headers) = postgres_operator_session(&db.repo, "job-target-batch-admin").await;
    let first_job = Uuid::new_v4();
    let second_job = Uuid::new_v4();
    let first_incarnation = Uuid::new_v4();
    sqlx::query(
        r#"
        INSERT INTO jobs (
            id, command_type, status, target_count, payload_hash, request_fingerprint
        ) VALUES
            ($1, 'shell_argv', 'running', 2, 'pairwise-payload-1', $3),
            ($2, 'shell_argv', 'running', 1, 'pairwise-payload-2', $4)
        "#,
    )
    .bind(first_job)
    .bind(second_job)
    .bind(format!("pairwise-request-{first_job}"))
    .bind(format!("pairwise-request-{second_job}"))
    .execute(&db.pool)
    .await
    .unwrap();
    sqlx::query(
        r#"
        INSERT INTO job_targets (
            job_id, client_id, status, message, exit_code,
            started_at, completed_at, process_incarnation_id
        ) VALUES
            ($1, 'pair-a', 'running', 'first running', NULL, now(), NULL, $3),
            ($1, 'pair-b', 'completed', 'first complete', 0, now(), now(), NULL),
            ($2, 'pair-a', 'failed', 'second failed', 17, now(), now(), NULL)
        "#,
    )
    .bind(first_job)
    .bind(second_job)
    .bind(first_incarnation)
    .execute(&db.pool)
    .await
    .unwrap();
    let router = crate::routes::build_router(postgres_app_state(&db));
    let authorization = headers.get(AUTHORIZATION).unwrap().clone();
    let request = |items: Value| {
        Request::builder()
            .method("POST")
            .uri("/api/v1/job-targets/statuses")
            .header(AUTHORIZATION, authorization.clone())
            .header(CONTENT_TYPE, "application/json")
            .body(Body::from(json!({"items": items}).to_string()))
            .unwrap()
    };
    let response = router
        .clone()
        .oneshot(request(json!([
            {"job_id": second_job, "client_id": "pair-a"},
            {"job_id": first_job, "client_id": "pair-b"},
            {"job_id": first_job, "client_id": "pair-a"}
        ])))
        .await
        .unwrap();
    assert_eq!(response.status(), StatusCode::OK);
    let response: Value =
        serde_json::from_slice(&to_bytes(response.into_body(), usize::MAX).await.unwrap()).unwrap();
    let targets = response.as_array().unwrap();
    assert_eq!(targets.len(), 3);
    assert_eq!(targets[0]["job_id"], second_job.to_string());
    assert_eq!(targets[0]["client_id"], "pair-a");
    assert_eq!(targets[0]["status"], "failed");
    assert_eq!(targets[0]["exit_code"], 17);
    assert_eq!(targets[1]["job_id"], first_job.to_string());
    assert_eq!(targets[1]["client_id"], "pair-b");
    assert_eq!(targets[1]["status"], "completed");
    assert_eq!(targets[2]["job_id"], first_job.to_string());
    assert_eq!(targets[2]["client_id"], "pair-a");
    assert_eq!(
        targets[2]["process_incarnation_id"],
        first_incarnation.to_string()
    );

    let missing = router
        .oneshot(request(json!([
            {"job_id": first_job, "client_id": "pair-a"},
            {"job_id": second_job, "client_id": "pair-b"}
        ])))
        .await
        .unwrap();
    assert_eq!(missing.status(), StatusCode::NOT_FOUND);
    let missing: Value =
        serde_json::from_slice(&to_bytes(missing.into_body(), usize::MAX).await.unwrap()).unwrap();
    assert_eq!(missing["error"], "job_target_not_found");

    db.cleanup().await;
}

#[tokio::test]
async fn postgres_policy_evidence_pending_owner_is_explicit_and_indexed() {
    let Some(db) = PgReliabilityTestDb::maybe_new().await else {
        return;
    };
    let column: (Option<String>, String) = sqlx::query_as(
        r#"
        SELECT column_default,is_nullable
        FROM information_schema.columns
        WHERE table_schema='public'
          AND table_name='alert_policy_evidence'
          AND column_name='evaluation_pending'
        "#,
    )
    .fetch_one(&db.pool)
    .await
    .unwrap();
    assert_eq!(column, (None, "NO".to_string()));
    assert_eq!(
        sqlx::query_scalar::<_, i64>(
            r#"
            SELECT count(*)
            FROM policy_rules rule
            JOIN policy_groups group_row ON group_row.id=rule.group_id
            WHERE rule.enabled AND group_row.enabled
              AND rule.evidence_source='telemetry.combined'
            "#,
        )
        .fetch_one(&db.pool)
        .await
        .unwrap(),
        0,
        "FALSE evidence is terminal only when no current enabled definition owns it"
    );
    sqlx::query(
        r#"
        INSERT INTO alert_policy_evidence (
            id,source_kind,source_event_id,fact_kind,natural_key,
            confirmation_bucket_key,subject_client_id,target_kind,target_id,
            source_status,completeness,subject_snapshot,payload,observed_at,
            state_started_at,schedule_lineage,evaluation_pending
        )
        SELECT
            md5('healthy-retained-' || item)::uuid,
            'telemetry.combined','healthy-retained-' || item,'metric',
            'healthy-retained-' || item,'healthy-retained-' || item,NULL,
            'client','healthy-retained-' || item,'observed',
            'complete','{}'::jsonb,'{"cpu":{"utilization_ratio":0.1}}'::jsonb,
            clock_timestamp() - interval '1 day',
            clock_timestamp() - interval '1 day',ARRAY[]::uuid[],FALSE
        FROM generate_series(1,10000) item
        "#,
    )
    .execute(&db.pool)
    .await
    .unwrap();
    sqlx::query("ANALYZE alert_policy_evidence")
        .execute(&db.pool)
        .await
        .unwrap();
    assert_eq!(
        sqlx::query_scalar::<_, i64>(
            "SELECT count(*) FROM alert_policy_evidence WHERE source_event_id LIKE 'healthy-retained-%'",
        )
        .fetch_one(&db.pool)
        .await
        .unwrap(),
        10_000
    );
    assert_eq!(
        sqlx::query_scalar::<_, i64>(
            "SELECT count(*) FROM alert_policy_evidence WHERE evaluation_pending",
        )
        .fetch_one(&db.pool)
        .await
        .unwrap(),
        0
    );
    let plan = sqlx::query_scalar::<_, String>(
        r#"
        EXPLAIN (ANALYZE,BUFFERS,COSTS OFF)
        SELECT id,evidence_seq,subject_client_id
        FROM alert_policy_evidence
        WHERE evaluation_pending
        ORDER BY evidence_seq
        LIMIT 500
        "#,
    )
    .fetch_all(&db.pool)
    .await
    .unwrap()
    .join("\n");
    assert!(plan.contains("alert_policy_evidence_pending_idx"), "{plan}");
    let relation_sizes: (i64, i64) = sqlx::query_as(
        r#"
        SELECT pg_relation_size('alert_policy_evidence'),
               pg_relation_size('alert_policy_evidence_pending_idx')
        "#,
    )
    .fetch_one(&db.pool)
    .await
    .unwrap();
    assert!(relation_sizes.1 < relation_sizes.0, "{relation_sizes:?}");

    db.cleanup().await;
}

#[tokio::test]
async fn postgres_policy_pending_batch_locks_only_changed_evidence() {
    let Some(db) = PgReliabilityTestDb::maybe_new().await else {
        return;
    };
    let unchanged_id = Uuid::new_v4();
    let changed_id = Uuid::new_v4();
    sqlx::query(
        r#"
        INSERT INTO alert_policy_evidence (
            id,source_kind,source_event_id,fact_kind,natural_key,
            confirmation_bucket_key,subject_client_id,target_kind,target_id,
            source_status,completeness,subject_snapshot,payload,observed_at,
            state_started_at,schedule_lineage,evaluation_pending
        )
        SELECT
            item.id,'backup.failure',item.id::text,'occurrence',item.id::text,
            item.id::text,NULL,'backup_request',item.id::text,
            'execution_failed','complete','{}'::jsonb,
            '{"status":"execution_failed"}'::jsonb,clock_timestamp(),
            NULL,ARRAY[]::uuid[],item.evaluation_pending
        FROM unnest($1::uuid[],$2::boolean[])
             AS item(id,evaluation_pending)
        "#,
    )
    .bind(vec![unchanged_id, changed_id])
    .bind(vec![false, true])
    .execute(&db.pool)
    .await
    .unwrap();

    let mut owner = db.pool.begin().await.unwrap();
    crate::repository_policy_lifecycle::recompute_policy_evidences_pending_in_tx(
        &mut owner,
        &[unchanged_id, changed_id],
    )
    .await
    .unwrap();

    let mut unchanged_probe = db.pool.begin().await.unwrap();
    assert_eq!(
        sqlx::query_scalar::<_, Uuid>(
            "SELECT id FROM alert_policy_evidence WHERE id=$1 FOR UPDATE NOWAIT",
        )
        .bind(unchanged_id)
        .fetch_one(&mut *unchanged_probe)
        .await
        .unwrap(),
        unchanged_id,
        "an unchanged pending bit must not widen the definition transaction's lock set"
    );
    unchanged_probe.rollback().await.unwrap();

    let mut changed_probe = db.pool.begin().await.unwrap();
    assert!(
        sqlx::query_scalar::<_, Uuid>(
            "SELECT id FROM alert_policy_evidence WHERE id=$1 FOR UPDATE NOWAIT",
        )
        .bind(changed_id)
        .fetch_one(&mut *changed_probe)
        .await
        .is_err(),
        "the row whose pending bit changed must remain owned until commit"
    );
    changed_probe.rollback().await.unwrap();

    owner.commit().await.unwrap();
    assert_eq!(
        sqlx::query_scalar::<_, i64>(
            "SELECT count(*) FROM alert_policy_evidence WHERE id=ANY($1::uuid[]) AND evaluation_pending",
        )
        .bind(vec![unchanged_id, changed_id])
        .fetch_one(&db.pool)
        .await
        .unwrap(),
        0
    );

    db.cleanup().await;
}

#[tokio::test]
async fn postgres_pending_evidence_drain_continues_beyond_one_page() {
    let Some(db) = PgReliabilityTestDb::maybe_new().await else {
        return;
    };
    sqlx::query("UPDATE policy_groups SET enabled=FALSE")
        .execute(&db.pool)
        .await
        .unwrap();
    sqlx::query(
        r#"
        INSERT INTO alert_policy_evidence (
            id,source_kind,source_event_id,fact_kind,natural_key,
            confirmation_bucket_key,subject_client_id,target_kind,target_id,
            source_status,completeness,subject_snapshot,payload,observed_at,
            state_started_at,causation_id,schedule_lineage,evaluation_pending
        )
        SELECT
            md5('pending-page-' || item)::uuid,
            'backup.failure','pending-page-' || item,'occurrence',
            'pending-page-' || item,'pending-page-' || item,NULL,
            'backup_request','pending-page-' || item,'execution_failed',
            'complete','{}'::jsonb,'{"status":"execution_failed"}'::jsonb,
            clock_timestamp(),NULL,NULL,ARRAY[]::uuid[],TRUE
        FROM generate_series(1,501) item
        "#,
    )
    .execute(&db.pool)
    .await
    .unwrap();

    db.repo.drain_policy_rule_backlog().await.unwrap();
    assert_eq!(
        sqlx::query_scalar::<_, i64>(
            "SELECT count(*) FROM alert_policy_evidence WHERE evaluation_pending",
        )
        .fetch_one(&db.pool)
        .await
        .unwrap(),
        0,
        "a page boundary is a yield point, not a throughput cap"
    );

    db.cleanup().await;
}

#[tokio::test]
async fn postgres_locked_pending_evidence_does_not_convoy_the_candidate_page() {
    let Some(db) = PgReliabilityTestDb::maybe_new().await else {
        return;
    };
    let client_id = "pending-evidence-no-convoy";
    insert_client(&db.pool, client_id, Some(Uuid::new_v4())).await;
    let rule_id = insert_typed_policy_rule_fixture(
        &db.pool,
        client_id,
        "metric",
        "telemetry.combined",
        "natural_key",
        "cpu.utilization_ratio >= 2",
        None,
        None,
        None,
        "resource",
    )
    .await;
    let scope_revision =
        sqlx::query_scalar::<_, i64>("SELECT policy_scope_revision FROM clients WHERE id=$1")
            .bind(client_id)
            .fetch_one(&db.pool)
            .await
            .unwrap();

    let mut evidence_ids = Vec::new();
    for ordinal in 1_i64..=2 {
        let (evidence_id, evidence_seq) = sqlx::query_as::<_, (Uuid, i64)>(
            r#"
            INSERT INTO alert_policy_evidence (
                id,source_kind,source_event_id,fact_kind,natural_key,
                confirmation_bucket_key,subject_client_id,target_kind,target_id,
                source_status,completeness,subject_snapshot,payload,observed_at,
                state_started_at,causation_id,schedule_lineage,evaluation_pending
            ) VALUES (
                gen_random_uuid(),'telemetry.combined',$1,'metric',$2,$2,$3,
                'client',$3,'complete','complete',
                jsonb_build_object(
                    'scope_complete',TRUE,'scope_revision',$4,'client_id',$3,
                    'display_name',$3,'status','online','tags','[]'::jsonb,
                    'vps_rules','{}'::jsonb
                ),
                '{"cpu":{"utilization_ratio":0.5}}'::jsonb,
                statement_timestamp() + $5 * interval '1 millisecond',
                statement_timestamp() + $5 * interval '1 millisecond',
                NULL,ARRAY[]::uuid[],TRUE
            )
            RETURNING id,evidence_seq
            "#,
        )
        .bind(format!("pending-no-convoy-{ordinal}"))
        .bind(format!("pending-no-convoy-bucket-{ordinal}"))
        .bind(client_id)
        .bind(scope_revision)
        .bind(ordinal)
        .fetch_one(&db.pool)
        .await
        .unwrap();
        sqlx::query(
            r#"
            INSERT INTO alert_policy_evidence_targets (
                evidence_id,evidence_seq,policy_rule_id,rule_version
            ) VALUES ($1,$2,$3,1)
            "#,
        )
        .bind(evidence_id)
        .bind(evidence_seq)
        .bind(rule_id)
        .execute(&db.pool)
        .await
        .unwrap();
        evidence_ids.push(evidence_id);
    }

    let mut current_owner = db.pool.begin().await.unwrap();
    sqlx::query("SELECT id FROM alert_policy_evidence WHERE id=$1 FOR UPDATE")
        .bind(evidence_ids[0])
        .execute(&mut *current_owner)
        .await
        .unwrap();

    let page = tokio::time::timeout(
        Duration::from_secs(2),
        crate::repository_policy_lifecycle::evaluate_pending_policy_evidence_page(&db.pool, 100),
    )
    .await
    .expect("one owned evidence row must not block the next pending evidence")
    .unwrap();
    assert_eq!(
        page,
        crate::repository_policy_lifecycle::PolicyMaintenancePage {
            examined: 2,
            changed: 1,
            still_due: true,
        },
        "the skipped durable owner must request an immediate follow-up despite a short page"
    );
    let pending = sqlx::query_as::<_, (Uuid, bool)>(
        r#"
        SELECT id,evaluation_pending
        FROM alert_policy_evidence
        WHERE id=ANY($1)
        ORDER BY evidence_seq
        "#,
    )
    .bind(&evidence_ids)
    .fetch_all(&db.pool)
    .await
    .unwrap();
    assert_eq!(
        pending,
        vec![(evidence_ids[0], true), (evidence_ids[1], false)]
    );

    current_owner.rollback().await.unwrap();
    assert_eq!(
        crate::repository_policy_lifecycle::evaluate_pending_policy_evidence(&db.pool, 2)
            .await
            .unwrap(),
        1
    );
    assert_eq!(
        sqlx::query_scalar::<_, i64>(
            "SELECT count(*) FROM alert_policy_evidence WHERE id=ANY($1) AND evaluation_pending",
        )
        .bind(&evidence_ids)
        .fetch_one(&db.pool)
        .await
        .unwrap(),
        0
    );

    db.cleanup().await;
}

#[tokio::test]
async fn postgres_pending_evidence_terminalizes_bad_metric_arithmetic_and_continues() {
    let Some(db) = PgReliabilityTestDb::maybe_new().await else {
        return;
    };
    let client_id = "pending-metric-arithmetic";
    insert_client(&db.pool, client_id, Some(Uuid::new_v4())).await;
    let rule_id = insert_typed_policy_rule_fixture(
        &db.pool,
        client_id,
        "metric",
        "telemetry.combined",
        "natural_key",
        "cpu.utilization_ratio / memory.available_ratio >= 2",
        None,
        None,
        None,
        "resource",
    )
    .await;

    sqlx::query(
        r#"
        INSERT INTO alert_policy_evidence (
            id,source_kind,source_event_id,fact_kind,natural_key,
            confirmation_bucket_key,subject_client_id,target_kind,target_id,
            source_status,completeness,subject_snapshot,payload,observed_at,
            state_started_at,causation_id,schedule_lineage,evaluation_pending
        )
        SELECT
            gen_random_uuid(),'telemetry.combined',candidate.event_id,'metric',
            $1,$1,$1,'client',$1,'complete','complete',
            jsonb_build_object(
                'scope_complete',TRUE,'scope_revision',1,'client_id',$1,
                'display_name',$1,'status','online','tags','[]'::jsonb,
                'vps_rules','{}'::jsonb
            ),
            candidate.payload,
            statement_timestamp() + candidate.ordinal * interval '1 millisecond',
            statement_timestamp() + candidate.ordinal * interval '1 millisecond',
            NULL,ARRAY[]::uuid[],TRUE
        FROM (VALUES
            (1,'pending-metric-arithmetic-bad',
                '{"cpu":{"utilization_ratio":0.9},"memory":{"available_ratio":0.0}}'::jsonb),
            (2,'pending-metric-arithmetic-good',
                '{"cpu":{"utilization_ratio":0.9},"memory":{"available_ratio":1.0}}'::jsonb)
        ) AS candidate(ordinal,event_id,payload)
        ORDER BY candidate.ordinal
        "#,
    )
    .bind(client_id)
    .execute(&db.pool)
    .await
    .unwrap();
    assert_eq!(
        sqlx::query(
            r#"
            INSERT INTO alert_policy_evidence_targets (
                evidence_id,evidence_seq,policy_rule_id,rule_version
            )
            SELECT evidence.id,evidence.evidence_seq,rule.id,rule.rule_version
            FROM alert_policy_evidence evidence
            JOIN policy_rules rule ON rule.id=$1
            WHERE evidence.source_event_id IN (
                'pending-metric-arithmetic-bad',
                'pending-metric-arithmetic-good'
            )
            "#,
        )
        .bind(rule_id)
        .execute(&db.pool)
        .await
        .unwrap()
        .rows_affected(),
        2,
        "both pending facts require the exact immutable rule generation"
    );

    assert_eq!(
        crate::repository_policy_lifecycle::evaluate_pending_policy_evidence(&db.pool, 100)
            .await
            .unwrap(),
        2,
        "a deterministic poison fact is terminal work, not a global retry barrier"
    );
    let receipts = sqlx::query_as::<_, (String, bool, String, Option<String>)>(
        r#"
        SELECT evidence.source_event_id,evidence.evaluation_pending,
               receipt.result,receipt.detail
        FROM alert_policy_evidence evidence
        JOIN alert_policy_evidence_receipts receipt
          ON receipt.policy_rule_id=$1
         AND receipt.rule_version=1
         AND receipt.evidence_seq=evidence.evidence_seq
        WHERE evidence.source_event_id IN (
            'pending-metric-arithmetic-bad',
            'pending-metric-arithmetic-good'
        )
        ORDER BY evidence.evidence_seq
        "#,
    )
    .bind(rule_id)
    .fetch_all(&db.pool)
    .await
    .unwrap();
    assert_eq!(receipts.len(), 2);
    assert_eq!(receipts[0].0, "pending-metric-arithmetic-bad");
    assert!(!receipts[0].1);
    assert_eq!(receipts[0].2, "error");
    assert!(receipts[0]
        .3
        .as_deref()
        .is_some_and(|detail| detail.contains("condition division by zero")));
    assert_eq!(
        receipts[1],
        (
            "pending-metric-arithmetic-good".to_string(),
            false,
            "not_matched".to_string(),
            Some("pending_evaluation".to_string()),
        )
    );
    assert_eq!(
        sqlx::query_scalar::<_, i64>(
            r#"
            SELECT count(*)
            FROM audit_logs
            WHERE action='fleet.alert_policy_evidence_skipped'
              AND target=$1
              AND metadata @> '{
                    "result":"skipped",
                    "origin_kind":"control_plane",
                    "component":"alert-policy-evaluator"
                  }'::jsonb
              AND metadata->>'reason' LIKE
                    'policy_expression_evaluation_failed:%division by zero%'
            "#,
        )
        .bind(format!("fleet_alert_policy_rule:{rule_id}"))
        .fetch_one(&db.pool)
        .await
        .unwrap(),
        1
    );

    db.cleanup().await;
}

#[tokio::test]
async fn postgres_telemetry_tunnel_listing_uses_the_evidence_acceptance_timestamp() {
    let Some(db) = PgReliabilityTestDb::maybe_new().await else {
        return;
    };
    let left_client_id = "tunnel-list-left";
    let right_client_id = "tunnel-list-right";
    for (client_id, key_byte) in [(left_client_id, 101_u8), (right_client_id, 102_u8)] {
        sqlx::query(
            r#"
            INSERT INTO clients (id, display_name, public_key, status)
            VALUES ($1, $1, $2, 'online')
            "#,
        )
        .bind(client_id)
        .bind(vec![key_byte; 32])
        .execute(&db.pool)
        .await
        .unwrap();
    }

    let plan_id = Uuid::new_v4();
    let mut input = postgres_alert_test_tunnel_input();
    input.name = "p".repeat(128);
    input.interface_name = "gre-list".to_string();
    input.left_client_id = left_client_id.to_string();
    input.right_client_id = right_client_id.to_string();
    let plan = plan_tunnel(&input).unwrap();
    sqlx::query(
        r#"
        INSERT INTO tunnel_plans (
            id, name, kind, enabled, left_client_id, right_client_id,
            input, plan, ospf_status, left_ospf_status, right_ospf_status
        ) VALUES (
            $1, $2, 'gre', true, $3, $4, $5, $6,
            'disabled', 'disabled', 'disabled'
        )
        "#,
    )
    .bind(plan_id)
    .bind(&input.name)
    .bind(left_client_id)
    .bind(right_client_id)
    .bind(SqlJson(&input))
    .bind(SqlJson(&plan))
    .execute(&db.pool)
    .await
    .unwrap();

    let observed_unix = 1_700_000_000_u64;
    let accepted_unix = observed_unix + 60;
    sqlx::query(
        r#"
        INSERT INTO telemetry_tunnels (
            client_id, observed_at, interface, kind, ownership_mode,
            mutation_policy, source, telemetry_plan_id, telemetry_plan_name,
            telemetry_plan_runtime_manager, telemetry_endpoint_side,
            telemetry_peer_client_id, traffic_status, updated_at
        ) VALUES (
            $1, to_timestamp($2::double precision), $3, 'gre',
            'custom_adapter', 'managed_desired', 'telemetry', $4, $5,
            'custom_adapter', 'left', $6, 'ok',
            to_timestamp($7::double precision)
        )
        "#,
    )
    .bind(left_client_id)
    .bind(observed_unix as f64)
    .bind(&input.interface_name)
    .bind(plan_id)
    .bind(&input.name)
    .bind(right_client_id)
    .bind(accepted_unix as f64)
    .execute(&db.pool)
    .await
    .unwrap();

    let tunnels = db
        .repo
        .list_telemetry_tunnels(10, Some(left_client_id), Some(&input.interface_name))
        .await
        .unwrap();
    assert_eq!(tunnels.len(), 1);
    assert_eq!(tunnels[0].client_id, left_client_id);
    assert_eq!(tunnels[0].plan_name.as_deref(), Some(input.name.as_str()));
    assert_eq!(
        tunnels[0].plan_runtime_manager.as_deref(),
        Some("custom_adapter")
    );
    assert_eq!(tunnels[0].ownership_mode, "custom_adapter");
    assert_eq!(tunnels[0].mutation_policy, "managed_desired");
    assert_eq!(
        crate::util::parse_timestamp_unix(&tunnels[0].observed_at),
        Some(observed_unix)
    );
    assert_eq!(
        crate::util::parse_timestamp_unix(&tunnels[0].accepted_at),
        Some(accepted_unix)
    );
    let invalid_name =
        sqlx::query("UPDATE telemetry_tunnels SET telemetry_plan_name=$2 WHERE client_id=$1")
            .bind(left_client_id)
            .bind("p".repeat(129))
            .execute(&db.pool)
            .await
            .unwrap_err();
    assert!(invalid_name
        .to_string()
        .contains("telemetry_tunnels_plan_name_check"));
    db.cleanup().await;
}

