#[tokio::test]
async fn postgres_recorded_telemetry_publishes_only_after_projection_commit() {
    let Some(db) = PgReliabilityTestDb::maybe_new().await else {
        return;
    };
    let client_id = "telemetry-webhook-wake-edge";
    let gateway_id = "telemetry-webhook-wake-gateway";
    let process_incarnation_id = Uuid::new_v4();
    let gateway_session_id = Uuid::new_v4();
    insert_client(&db.pool, client_id, Some(process_incarnation_id)).await;
    start_test_gateway_session(&db.repo, gateway_id, client_id, gateway_session_id).await;

    let mut listener = sqlx::postgres::PgListener::connect_with(&db.pool)
        .await
        .unwrap();
    listener
        .listen("vpsman_telemetry_projection")
        .await
        .unwrap();
    let event = |telemetry_seq| GatewayTelemetryIngest {
        gateway_id: gateway_id.to_string(),
        gateway_session_id,
        process_incarnation_id,
        telemetry_seq,
        remote_ip: None,
        telemetry: TelemetryEnvelope {
            client_id: client_id.to_string(),
            metrics: AgentMetrics {
                observed_unix: 70_000 + telemetry_seq,
                hostname: client_id.to_string(),
                ..Default::default()
            },
        },
    };

    assert_eq!(
        db.repo.record_telemetry_outcome(&event(1)).await.unwrap(),
        crate::repository_ingest::TelemetryRecordOutcome::Recorded
    );
    assert!(
        tokio::time::timeout(Duration::from_millis(100), listener.recv())
            .await
            .is_err(),
        "canonical acceptance must not publish unprojected telemetry"
    );
    assert_eq!(db.repo.project_pending_telemetry(1).await.unwrap(), 1);
    let first = tokio::time::timeout(Duration::from_secs(2), listener.recv())
        .await
        .expect("first projection commit did not publish")
        .unwrap();
    let first: Value = serde_json::from_str(first.payload()).unwrap();
    assert_eq!(first["client_id"], client_id);
    assert_eq!(first["projected_seq"], 1);

    assert_eq!(
        db.repo.record_telemetry_outcome(&event(2)).await.unwrap(),
        crate::repository_ingest::TelemetryRecordOutcome::Recorded
    );
    assert_eq!(db.repo.project_pending_telemetry(1).await.unwrap(), 1);
    let pending = tokio::time::timeout(Duration::from_secs(2), listener.recv())
        .await
        .expect("second projection commit did not publish")
        .unwrap();
    let pending: Value = serde_json::from_str(pending.payload()).unwrap();
    assert_eq!(pending["client_id"], client_id);
    assert_eq!(pending["projected_seq"], 2);

    assert_eq!(
        db.repo.record_telemetry_outcome(&event(3)).await.unwrap(),
        crate::repository_ingest::TelemetryRecordOutcome::Recorded
    );
    assert_eq!(db.repo.project_pending_telemetry(1).await.unwrap(), 1);
    let resumed = tokio::time::timeout(Duration::from_secs(2), listener.recv())
        .await
        .expect("third projection commit did not publish")
        .unwrap();
    let resumed: Value = serde_json::from_str(resumed.payload()).unwrap();
    assert_eq!(resumed["client_id"], client_id);
    assert_eq!(resumed["projected_seq"], 3);

    drop(listener);
    db.cleanup().await;
}

#[tokio::test]
async fn postgres_pending_scope_revision_materialization_is_idempotent() {
    let Some(db) = PgReliabilityTestDb::maybe_new().await else {
        return;
    };
    let client_id = "scope-revision-materialization";
    insert_client(&db.pool, client_id, Some(Uuid::new_v4())).await;

    let mut source = db.pool.begin().await.unwrap();
    sqlx::query("SELECT id FROM clients WHERE id=$1 FOR UPDATE")
        .bind(client_id)
        .fetch_one(&mut *source)
        .await
        .unwrap();
    sqlx::query("UPDATE clients SET status='offline' WHERE id=$1")
        .bind(client_id)
        .execute(&mut *source)
        .await
        .unwrap();
    crate::repository_operational_alerts::reconcile_postgres_agent_alert_transition_in_tx(
        &mut source,
        client_id,
        "offline",
    )
    .await
    .unwrap();
    source.commit().await.unwrap();

    // Bump only selector/presentation metadata. The raw source boundary stays
    // immutable and one deterministic scope fact represents this revision.
    sqlx::query("UPDATE clients SET display_name='renamed scope client' WHERE id=$1")
        .bind(client_id)
        .execute(&db.pool)
        .await
        .unwrap();

    // Dashboard/event FKs take KEY SHARE on the client identity. Scope materialization
    // owns only non-key client state, so that unrelated reference must not
    // block exact revision materialization.
    let mut foreign_key_reference = db.pool.begin().await.unwrap();
    sqlx::query(
        r#"
        INSERT INTO telemetry_dashboard_block_events (
            client_id, domain, event_kind,
            source_bucket_secs, block_start_unix
        ) VALUES ($1, 'resource', 'full_block', 60, 0)
        "#,
    )
    .bind(client_id)
    .execute(&mut *foreign_key_reference)
    .await
    .unwrap();
    assert!(
        tokio::time::timeout(
            Duration::from_secs(5),
            crate::repository_policy_lifecycle::materialize_pending_policy_scope_revisions(
                &db.pool, 200,
            ),
        )
        .await
        .expect("scope materialization waited on an unrelated FK KEY SHARE reference")
        .unwrap()
            > 0
    );
    foreign_key_reference.rollback().await.unwrap();
    let scope_count = sqlx::query_scalar::<_, i64>(
        "SELECT count(*) FROM alert_policy_evidence WHERE source_event_id LIKE 'scope:%' AND subject_client_id=$1",
    )
    .bind(client_id)
    .fetch_one(&db.pool)
    .await
    .unwrap();
    assert_eq!(
        crate::repository_policy_lifecycle::materialize_pending_policy_scope_revisions(
            &db.pool, 200
        )
        .await
        .unwrap(),
        0,
        "an already-emitted scope revision must not keep startup materialization live"
    );
    assert_eq!(
        sqlx::query_scalar::<_, i64>(
            "SELECT count(*) FROM alert_policy_evidence WHERE source_event_id LIKE 'scope:%' AND subject_client_id=$1",
        )
        .bind(client_id)
        .fetch_one(&db.pool)
        .await
        .unwrap(),
        scope_count
    );

    // A real non-key client mutation still owns the revision boundary. The
    // consumer skips that exact owner instead of blocking an API replica, then
    // materializes the revision after the producer commits it.
    sqlx::query("UPDATE clients SET display_name='queued scope revision' WHERE id=$1")
        .bind(client_id)
        .execute(&db.pool)
        .await
        .unwrap();
    let mut client_mutation = db.pool.begin().await.unwrap();
    sqlx::query("UPDATE clients SET display_name='held scope revision' WHERE id=$1")
        .bind(client_id)
        .execute(&mut *client_mutation)
        .await
        .unwrap();
    assert_eq!(
        tokio::time::timeout(
            Duration::from_secs(5),
            crate::repository_policy_lifecycle::materialize_pending_policy_scope_revisions(
                &db.pool, 200,
            ),
        )
        .await
        .expect("scope materialization blocked on an independently owned client")
        .unwrap(),
        0,
        "the consumer must skip an exact client owner rather than wait on it"
    );
    client_mutation.commit().await.unwrap();
    assert_eq!(
        tokio::time::timeout(
            Duration::from_secs(5),
            crate::repository_policy_lifecycle::materialize_pending_policy_scope_revisions(
                &db.pool, 200,
            ),
        )
        .await
        .expect("scope materialization did not resume after the client mutation committed")
        .unwrap(),
        1
    );
    let committed_revision: i64 =
        sqlx::query_scalar("SELECT policy_scope_revision FROM clients WHERE id=$1")
            .bind(client_id)
            .fetch_one(&db.pool)
            .await
            .unwrap();
    assert!(
        sqlx::query_scalar::<_, bool>(
            r#"
            SELECT EXISTS (
                SELECT 1
                FROM alert_policy_evidence
                WHERE subject_client_id=$1
                  AND source_event_id LIKE $2
            )
            "#,
        )
        .bind(client_id)
        .bind(format!("scope:{committed_revision}:%"))
        .fetch_one(&db.pool)
        .await
        .unwrap(),
        "scope materialization did not materialize the committed client revision"
    );
    assert_eq!(
        crate::repository_policy_lifecycle::materialize_pending_policy_scope_revisions(
            &db.pool, 200
        )
        .await
        .unwrap(),
        0,
        "the serialized revision must leave no pending work behind"
    );

    db.cleanup().await;
}

#[tokio::test]
async fn postgres_policy_current_evidence_and_scope_queue_stay_bounded() {
    let Some(db) = PgReliabilityTestDb::maybe_new().await else {
        return;
    };
    sqlx::query(
        "UPDATE policy_groups SET enabled=FALSE WHERE lower(selector_expression) LIKE '%last_seen%'",
    )
    .execute(&db.pool)
    .await
    .unwrap();
    let client_id = "bounded-policy-current";
    insert_client(&db.pool, client_id, Some(Uuid::new_v4())).await;
    let base = Utc::now() - chrono::Duration::minutes(10);
    let (first_id, _) =
        insert_raw_current_metric_fact(&db.pool, client_id, "bounded-first", base, 1).await;
    let (out_of_order_id, _) = insert_raw_current_metric_fact(
        &db.pool,
        client_id,
        "bounded-out-of-order",
        base - chrono::Duration::seconds(1),
        1,
    )
    .await;
    assert_eq!(
        sqlx::query_scalar::<_, Uuid>(
            "SELECT evidence_id FROM alert_policy_current_evidence WHERE subject_client_id=$1 AND source_kind='telemetry.combined'",
        )
        .bind(client_id)
        .fetch_one(&db.pool)
        .await
        .unwrap(),
        first_id,
        "a later sequence with an older source time must not replace current"
    );
    let (tie_id, _) =
        insert_raw_current_metric_fact(&db.pool, client_id, "bounded-tie", base, 1).await;
    assert_eq!(
        sqlx::query_scalar::<_, Uuid>(
            "SELECT evidence_id FROM alert_policy_current_evidence WHERE subject_client_id=$1 AND source_kind='telemetry.combined'",
        )
        .bind(client_id)
        .fetch_one(&db.pool)
        .await
        .unwrap(),
        tie_id,
        "evidence sequence is the deterministic equal-time tiebreaker"
    );
    assert!(sqlx::query("DELETE FROM alert_policy_evidence WHERE id=$1")
        .bind(tie_id)
        .execute(&db.pool)
        .await
        .is_err());

    sqlx::query(
        r#"
        INSERT INTO alert_policy_evidence (
            id,source_kind,source_event_id,fact_kind,natural_key,
            confirmation_bucket_key,subject_client_id,target_kind,target_id,
            source_status,completeness,subject_snapshot,payload,observed_at,
            state_started_at,evaluation_pending
        ) VALUES (
            $1,'agent.status','bounded-agent-present','state',$2,$2,$3,
            'agent',$3,'online','complete',$4,$5,$6,$6,FALSE
        )
        "#,
    )
    .bind(Uuid::new_v4())
    .bind(format!("{client_id}:connectivity"))
    .bind(client_id)
    .bind(SqlJson(json!({
        "scope_complete": true,
        "scope_revision": 1,
        "client_id": client_id,
    })))
    .bind(SqlJson(json!({
        "status": "online",
        "source_status": "online",
        "source_present": true,
    })))
    .bind(base)
    .execute(&db.pool)
    .await
    .unwrap();
    let mut exit = db.pool.begin().await.unwrap();
    assert_eq!(
        crate::repository_policy_lifecycle::record_policy_source_scope_exits_in_tx(
            &mut exit,
            &["agent.status"],
            &[client_id.to_string()],
            &BTreeSet::new(),
        )
        .await
        .unwrap(),
        1
    );
    assert_eq!(
        crate::repository_policy_lifecycle::record_policy_source_scope_exits_in_tx(
            &mut exit,
            &["agent.status"],
            &[client_id.to_string()],
            &BTreeSet::new(),
        )
        .await
        .unwrap(),
        0,
        "the current exit fact makes an exact retry a bounded no-op"
    );
    exit.commit().await.unwrap();
    assert!(sqlx::query_scalar::<_, bool>(
        r#"
            SELECT evidence.payload->>'source_present'='false'
            FROM alert_policy_current_evidence current_fact
            JOIN alert_policy_evidence evidence ON evidence.id=current_fact.evidence_id
            WHERE current_fact.subject_client_id=$1
              AND current_fact.source_kind='agent.status'
            "#,
    )
    .bind(client_id)
    .fetch_one(&db.pool)
    .await
    .unwrap());

    for offset in 1_i64..=3 {
        sqlx::query(
            "UPDATE clients SET last_seen_at=clock_timestamp()+make_interval(secs=>$2) WHERE id=$1",
        )
        .bind(client_id)
        .bind(offset as f64)
        .execute(&db.pool)
        .await
        .unwrap();
    }
    assert_eq!(
        sqlx::query_scalar::<_, i64>("SELECT policy_scope_revision FROM clients WHERE id=$1",)
            .bind(client_id)
            .fetch_one(&db.pool)
            .await
            .unwrap(),
        1,
        "last_seen is not a scope dimension until a selector uses it"
    );
    assert_eq!(
        sqlx::query_scalar::<_, i64>(
            "SELECT count(*) FROM alert_policy_scope_dirty_clients WHERE client_id=$1",
        )
        .bind(client_id)
        .fetch_one(&db.pool)
        .await
        .unwrap(),
        0,
        "ordinary telemetry must not churn policy scope without a last_seen selector"
    );

    sqlx::query(
        r#"
        INSERT INTO policy_groups (id,name,enabled,selector_expression)
        VALUES ($1,$2,TRUE,'VPS.LAST_SEEN_AT > 0')
        "#,
    )
    .bind(Uuid::new_v4())
    .bind(format!("last-seen-scope-{client_id}"))
    .execute(&db.pool)
    .await
    .unwrap();
    assert_eq!(
        sqlx::query_scalar::<_, i64>(
            "SELECT target_revision FROM alert_policy_scope_dirty_clients WHERE client_id=$1",
        )
        .bind(client_id)
        .fetch_one(&db.pool)
        .await
        .unwrap(),
        1,
        "enabling a last_seen selector queues the offline client's current boundary"
    );
    assert!(
        sqlx::query_scalar::<_, bool>(
            "SELECT requires_revision_advance FROM alert_policy_scope_dirty_clients WHERE client_id=$1",
        )
        .bind(client_id)
        .fetch_one(&db.pool)
        .await
        .unwrap(),
        "activation must request a new boundary even when no heartbeat changed the revision"
    );
    for offset in 4_i64..=6 {
        sqlx::query(
            "UPDATE clients SET last_seen_at=clock_timestamp()+make_interval(secs=>$2) WHERE id=$1",
        )
        .bind(client_id)
        .bind(offset as f64)
        .execute(&db.pool)
        .await
        .unwrap();
    }
    let revision =
        sqlx::query_scalar::<_, i64>("SELECT policy_scope_revision FROM clients WHERE id=$1")
            .bind(client_id)
            .fetch_one(&db.pool)
            .await
            .unwrap();
    assert_eq!(revision, 4);
    assert_eq!(
        sqlx::query_scalar::<_, i64>(
            "SELECT target_revision FROM alert_policy_scope_dirty_clients WHERE client_id=$1",
        )
        .bind(client_id)
        .fetch_one(&db.pool)
        .await
        .unwrap(),
        revision,
        "many arrivals coalesce to one exact latest revision"
    );
    assert_eq!(
        crate::repository_policy_lifecycle::materialize_pending_policy_scope_revisions(
            &db.pool, 200
        )
        .await
        .unwrap(),
        1
    );
    let revision =
        sqlx::query_scalar::<_, i64>("SELECT policy_scope_revision FROM clients WHERE id=$1")
            .bind(client_id)
            .fetch_one(&db.pool)
            .await
            .unwrap();
    assert_eq!(revision, 5, "the activation boundary advances exactly once");
    assert_eq!(
        crate::repository_policy_lifecycle::materialize_pending_policy_scope_revisions(
            &db.pool, 200
        )
        .await
        .unwrap(),
        0,
        "a restart observes an empty durable queue after atomic materialization"
    );
    assert_eq!(
        sqlx::query_scalar::<_, Uuid>(
            "SELECT evidence_id FROM alert_policy_current_evidence WHERE subject_client_id=$1 AND source_kind='telemetry.combined'",
        )
        .bind(client_id)
        .fetch_one(&db.pool)
        .await
        .unwrap(),
        tie_id,
        "scope clones must not replace the source-owned current fact"
    );
    assert!(
        sqlx::query_scalar::<_, String>(
            r#"
            SELECT evidence.source_event_id
            FROM alert_policy_effective_current_evidence current_fact
            JOIN alert_policy_evidence evidence ON evidence.id=current_fact.evidence_id
            WHERE current_fact.subject_client_id=$1
              AND current_fact.source_kind='telemetry.combined'
            "#,
        )
        .bind(client_id)
        .fetch_one(&db.pool)
        .await
        .unwrap()
        .starts_with("scope:5:"),
        "preview/baseline current must advance to the current-scope clone"
    );

    let (newest_id, _) = insert_raw_current_metric_fact(
        &db.pool,
        client_id,
        "bounded-newest",
        base + chrono::Duration::seconds(1),
        revision,
    )
    .await;
    assert_eq!(
        sqlx::query("DELETE FROM alert_policy_evidence WHERE id=$1")
            .bind(tie_id)
            .execute(&db.pool)
            .await
            .unwrap()
            .rows_affected(),
        1,
        "retention may delete the former baseline after a newer source fact wins"
    );
    assert_eq!(
        sqlx::query_scalar::<_, Uuid>(
            "SELECT evidence_id FROM alert_policy_current_evidence WHERE subject_client_id=$1 AND source_kind='telemetry.combined'",
        )
        .bind(client_id)
        .fetch_one(&db.pool)
        .await
        .unwrap(),
        newest_id
    );
    assert!(sqlx::query_scalar::<_, bool>(
        "SELECT EXISTS (SELECT 1 FROM alert_policy_evidence WHERE id=$1)",
    )
    .bind(out_of_order_id)
    .fetch_one(&db.pool)
    .await
    .unwrap());
    assert!(sqlx::query_scalar::<_, bool>(
        "SELECT EXISTS (SELECT 1 FROM alert_policy_evidence_prune_candidates WHERE evidence_id=$1)",
    )
    .bind(out_of_order_id)
    .fetch_one(&db.pool)
    .await
    .unwrap(),
    "ingest must durably queue superseded evidence for asynchronous retention without deleting it"
    );

    let bounded_indexes = sqlx::query_as::<_, (String, String)>(
        r#"
        SELECT indexname,indexdef
        FROM pg_indexes
        WHERE schemaname='public'
          AND indexname=ANY($1::text[])
        "#,
    )
    .bind(vec![
        "alert_policy_current_evidence_pkey",
        "alert_policy_evidence_source_latest_idx",
        "telemetry_projection_heads_accepted_order_idx",
    ])
    .fetch_all(&db.pool)
    .await
    .unwrap()
    .into_iter()
    .collect::<BTreeMap<_, _>>();
    assert!(
        bounded_indexes["alert_policy_current_evidence_pkey"]
            .contains("(subject_client_id, source_kind, natural_key)"),
        "{}",
        bounded_indexes["alert_policy_current_evidence_pkey"]
    );
    assert!(
        bounded_indexes["alert_policy_evidence_source_latest_idx"]
            .contains("(source_kind, natural_key, observed_at DESC, evidence_seq DESC)"),
        "{}",
        bounded_indexes["alert_policy_evidence_source_latest_idx"]
    );
    assert!(
        bounded_indexes["telemetry_projection_heads_accepted_order_idx"]
            .contains("(accepted_at, client_id)"),
        "{}",
        bounded_indexes["telemetry_projection_heads_accepted_order_idx"]
    );
    assert!(!bounded_indexes["telemetry_projection_heads_accepted_order_idx"].contains(" WHERE "));

    db.cleanup().await;
}

#[tokio::test]
async fn postgres_stale_source_publish_requeues_concurrent_scope_revision() {
    let Some(db) = PgReliabilityTestDb::maybe_new().await else {
        return;
    };
    let client_id = "scope-source-interleaving";
    insert_client(&db.pool, client_id, Some(Uuid::new_v4())).await;
    let observed_at = Utc::now() - chrono::Duration::minutes(1);
    insert_raw_current_metric_fact(&db.pool, client_id, "scope-race-baseline", observed_at, 1)
        .await;

    let mut scope = db.pool.begin().await.unwrap();
    sqlx::query("UPDATE clients SET display_name=$2 WHERE id=$1")
        .bind(client_id)
        .bind("scope race revision two")
        .execute(&mut *scope)
        .await
        .unwrap();
    crate::repository_policy_lifecycle::record_claimed_policy_scope_revision_evidence_in_tx(
        &mut scope, client_id,
    )
    .await
    .unwrap();
    let first_revision_two_clone = sqlx::query_scalar::<_, String>(
        r#"
        SELECT source_event_id
        FROM alert_policy_evidence
        WHERE subject_client_id=$1
          AND source_kind='telemetry.combined'
          AND source_event_id LIKE 'scope:2:%'
        "#,
    )
    .bind(client_id)
    .fetch_one(&mut *scope)
    .await
    .unwrap();
    assert_eq!(
        sqlx::query_scalar::<_, i64>(
            "SELECT count(*) FROM alert_policy_scope_dirty_clients WHERE client_id=$1",
        )
        .bind(client_id)
        .fetch_one(&mut *scope)
        .await
        .unwrap(),
        0,
        "the uncommitted scope transaction materialized and cleared revision two"
    );

    let source_pool = db.pool.clone();
    let source_client_id = client_id.to_string();
    let source_id = Uuid::new_v4();
    let source = tokio::spawn(async move {
        let mut tx = source_pool.begin().await.unwrap();
        sqlx::query("SET LOCAL application_name='vpsman_scope_source_race'")
            .execute(&mut *tx)
            .await
            .unwrap();
        sqlx::query(
            r#"
            INSERT INTO alert_policy_evidence (
                id,source_kind,source_event_id,fact_kind,natural_key,
                confirmation_bucket_key,subject_client_id,target_kind,target_id,
                source_status,completeness,subject_snapshot,payload,observed_at,
                state_started_at,evaluation_pending
            ) VALUES (
                $1,'telemetry.combined','scope-race-stale-r1','metric',$2,$2,$2,
                'client',$2,'complete','complete',$3,'{}'::jsonb,$4,$4,FALSE
            )
            "#,
        )
        .bind(source_id)
        .bind(&source_client_id)
        .bind(SqlJson(json!({
            "scope_complete": true,
            "scope_revision": 1,
            "client_id": source_client_id,
        })))
        .bind(observed_at + chrono::Duration::seconds(1))
        .execute(&mut *tx)
        .await
        .unwrap();
        tx.commit().await.unwrap();
    });

    let mut blocked = false;
    for _ in 0..50 {
        blocked = sqlx::query_scalar::<_, bool>(
            r#"
            SELECT EXISTS (
                SELECT 1 FROM pg_stat_activity
                WHERE application_name='vpsman_scope_source_race'
                  AND wait_event_type='Lock'
            )
            "#,
        )
        .fetch_one(&db.pool)
        .await
        .unwrap();
        if blocked {
            break;
        }
        tokio::time::sleep(Duration::from_millis(20)).await;
    }
    assert!(
        blocked,
        "the stale source did not wait on the scope-owned client row"
    );
    scope.commit().await.unwrap();
    source.await.unwrap();

    assert_eq!(
        sqlx::query_as::<_, (Uuid, i64, i64)>(
            r#"
            SELECT effective_fact.evidence_id,dirty.target_revision,
                   client.policy_scope_revision
            FROM alert_policy_effective_current_evidence effective_fact
            JOIN clients client ON client.id=effective_fact.subject_client_id
            JOIN alert_policy_scope_dirty_clients dirty ON dirty.client_id=client.id
            WHERE effective_fact.subject_client_id=$1
            "#,
        )
        .bind(client_id)
        .fetch_one(&db.pool)
        .await
        .unwrap(),
        (source_id, 2, 2),
        "the newer source fact remains effective-latest with revision two durably requeued"
    );
    let source_seq =
        sqlx::query_scalar::<_, i64>("SELECT evidence_seq FROM alert_policy_evidence WHERE id=$1")
            .bind(source_id)
            .fetch_one(&db.pool)
            .await
            .unwrap();
    assert_eq!(
        crate::repository_policy_lifecycle::materialize_pending_policy_scope_revisions(
            &db.pool, 200
        )
        .await
        .unwrap(),
        1
    );
    let second_revision_two_clone = sqlx::query_scalar::<_, String>(
        r#"
        SELECT source_event_id
        FROM alert_policy_evidence
        WHERE subject_client_id=$1
          AND source_kind='telemetry.combined'
          AND source_event_id LIKE 'scope:2:%'
          AND source_event_id LIKE $2
        ORDER BY evidence_seq DESC
        LIMIT 1
        "#,
    )
    .bind(client_id)
    .bind(format!("scope:2:{source_seq}:%"))
    .fetch_one(&db.pool)
    .await
    .unwrap();
    assert_ne!(
        second_revision_two_clone, first_revision_two_clone,
        "E1 and newer stale E2 require distinct evaluations at the same scope revision"
    );
    assert!(
        second_revision_two_clone.starts_with(&format!("scope:2:{source_seq}:")),
        "the second clone must be bound to E2's authoritative evidence version"
    );
    assert_eq!(
        sqlx::query_scalar::<_, i64>(
            "SELECT count(*) FROM alert_policy_scope_dirty_clients WHERE client_id=$1",
        )
        .bind(client_id)
        .fetch_one(&db.pool)
        .await
        .unwrap(),
        0
    );

    db.cleanup().await;
}

#[tokio::test]
async fn postgres_enabling_last_seen_policy_never_seeds_from_stale_state_snapshot() {
    let Some(db) = PgReliabilityTestDb::maybe_new().await else {
        return;
    };
    let client_id = "last-seen-policy-arm";
    insert_client(&db.pool, client_id, Some(Uuid::new_v4())).await;
    let old_seen = Utc::now() - chrono::Duration::hours(2);
    let cutoff = Utc::now() - chrono::Duration::hours(1);
    let live_seen = Utc::now();
    sqlx::query("UPDATE clients SET last_seen_at=$2 WHERE id=$1")
        .bind(client_id)
        .bind(old_seen)
        .execute(&db.pool)
        .await
        .unwrap();
    record_test_policy_fact(
        &db.pool,
        crate::repository_policy_lifecycle::PolicyEvidenceFact {
            source_kind: "agent.status".to_string(),
            source_event_id: "last-seen-old-offline-state".to_string(),
            fact_kind: AlertPolicyRuleKind::State,
            natural_key: client_id.to_string(),
            confirmation_bucket_key: client_id.to_string(),
            subject_client_id: Some(client_id.to_string()),
            target_kind: "client".to_string(),
            target_id: client_id.to_string(),
            source_status: "offline".to_string(),
            complete: true,
            subject_snapshot: json!({}),
            payload: json!({
                "status": "offline",
                "source_status": "offline",
                "source_present": true,
            }),
            observed_at: old_seen,
            state_started_at: Some(old_seen),
            causation_id: None,
            schedule_lineage: Vec::new(),
        },
    )
    .await;
    let old_evidence_seq = sqlx::query_scalar::<_, i64>(
        "SELECT evidence_seq FROM alert_policy_evidence WHERE source_kind='agent.status' AND source_event_id='last-seen-old-offline-state'",
    )
    .fetch_one(&db.pool)
    .await
    .unwrap();
    for seen in [live_seen, live_seen + chrono::Duration::seconds(1)] {
        sqlx::query("UPDATE clients SET last_seen_at=$2 WHERE id=$1")
            .bind(client_id)
            .bind(seen)
            .execute(&db.pool)
            .await
            .unwrap();
    }
    assert_eq!(
        sqlx::query_as::<_, (i64, i64)>(
            r#"
            SELECT client.policy_scope_revision,
                   (evidence.subject_snapshot->>'scope_revision')::bigint
            FROM clients client
            JOIN alert_policy_current_evidence current_fact
              ON current_fact.subject_client_id=client.id
             AND current_fact.source_kind='agent.status'
            JOIN alert_policy_evidence evidence ON evidence.id=current_fact.evidence_id
            WHERE client.id=$1
            "#,
        )
        .bind(client_id)
        .fetch_one(&db.pool)
        .await
        .unwrap(),
        (1, 1),
        "heartbeats do not invalidate unrelated selectors before last_seen is active"
    );
    assert_eq!(
        sqlx::query_scalar::<_, i64>(
            "SELECT count(*) FROM alert_policy_scope_dirty_clients WHERE client_id=$1",
        )
        .bind(client_id)
        .fetch_one(&db.pool)
        .await
        .unwrap(),
        0
    );
    assert_eq!(
        sqlx::query_scalar::<_, i64>(
            "SELECT count(*) FROM alert_policy_evidence WHERE subject_client_id=$1 AND source_event_id LIKE 'scope:%'",
        )
        .bind(client_id)
        .fetch_one(&db.pool)
        .await
        .unwrap(),
        0,
        "pre-enable heartbeats neither advance revisions nor write scope facts"
    );

    let operator = postgres_network_operator(&db.repo).await;
    let policy = db
        .repo
        .upsert_fleet_alert_policy(
            &CreateFleetAlertPolicyRequest {
                id: None,
                name: "last seen definition fence".to_string(),
                enabled: true,
                selector_expression: format!(
                    "id:{client_id} && last_seen < {}",
                    cutoff.to_rfc3339()
                ),
                rules: vec![PolicyRuleRequest {
                    id: None,
                    name: "offline while previously stale".to_string(),
                    enabled: true,
                    rule_kind: AlertPolicyRuleKind::State,
                    evidence_source: "agent.status".to_string(),
                    correlation_mode: AlertPolicyCorrelationMode::NaturalKey,
                    traffic_selector: None,
                    trigger_condition_expression: "evidence.status = offline".to_string(),
                    trigger_meta_condition: None,
                    resolve_condition_expression: Some("evidence.status = online".to_string()),
                    resolve_meta_condition: None,
                    severity: "warning".to_string(),
                    category: "agent_status".to_string(),
                    title_template: "Agent offline".to_string(),
                    detail_template: "Agent is offline".to_string(),
                }],
                notes: None,
                confirmed: true,
                preview_hash: None,
            },
            &operator,
        )
        .await
        .unwrap();
    let rule_id = policy.rules[0].id;
    assert_eq!(
        sqlx::query_as::<_, (String, Option<String>)>(
            r#"
            SELECT result,detail
            FROM alert_policy_evidence_receipts
            WHERE policy_rule_id=$1 AND evidence_seq=$2
            "#,
        )
        .bind(rule_id)
        .bind(old_evidence_seq)
        .fetch_one(&db.pool)
        .await
        .unwrap(),
        (
            "unknown".to_string(),
            Some("armed_baseline_scope_revision_stale".to_string())
        ),
        "the definition fence must classify the pre-heartbeat state as stale, never matched"
    );
    assert_eq!(
        sqlx::query_scalar::<_, i64>(
            "SELECT target_revision FROM alert_policy_scope_dirty_clients WHERE client_id=$1",
        )
        .bind(client_id)
        .fetch_one(&db.pool)
        .await
        .unwrap(),
        1,
        "the real policy mutation durably schedules the offline-client rebase"
    );
    assert!(sqlx::query_scalar::<_, bool>(
        "SELECT requires_revision_advance FROM alert_policy_scope_dirty_clients WHERE client_id=$1",
    )
    .bind(client_id)
    .fetch_one(&db.pool)
    .await
    .unwrap());
    assert_eq!(
        sqlx::query_scalar::<_, i64>(
            "SELECT count(*) FROM alert_episodes WHERE policy_rule_id=$1",
        )
        .bind(rule_id)
        .fetch_one(&db.pool)
        .await
        .unwrap(),
        0
    );

    assert_eq!(
        crate::repository_policy_lifecycle::materialize_pending_policy_scope_revisions(
            &db.pool, 200
        )
        .await
        .unwrap(),
        1
    );
    assert_eq!(
        sqlx::query_scalar::<_, String>(
            r#"
            SELECT receipt.result
            FROM alert_policy_evidence_receipts receipt
            JOIN alert_policy_evidence evidence ON evidence.id=receipt.evidence_id
            WHERE receipt.policy_rule_id=$1
              AND evidence.source_event_id LIKE 'scope:2:%'
            "#,
        )
        .bind(rule_id)
        .fetch_one(&db.pool)
        .await
        .unwrap(),
        "out_of_scope",
        "only the live post-heartbeat snapshot may establish selector truth"
    );
    assert_eq!(
        sqlx::query_scalar::<_, i64>(
            "SELECT count(*) FROM alert_episodes WHERE policy_rule_id=$1",
        )
        .bind(rule_id)
        .fetch_one(&db.pool)
        .await
        .unwrap(),
        0
    );

    db.cleanup().await;
}

