async fn insert_raw_current_metric_fact(
    pool: &PgPool,
    client_id: &str,
    event_id: &str,
    observed_at: chrono::DateTime<Utc>,
    scope_revision: i64,
) -> (Uuid, i64) {
    let evidence_id = Uuid::new_v4();
    let evidence_seq = sqlx::query_scalar::<_, i64>(
        r#"
        INSERT INTO alert_policy_evidence (
            id,source_kind,source_event_id,fact_kind,natural_key,
            confirmation_bucket_key,subject_client_id,target_kind,target_id,
            source_status,completeness,subject_snapshot,payload,observed_at,
            state_started_at,evaluation_pending
        ) VALUES (
            $1,'telemetry.combined',$2,'metric',$3,$3,$3,'client',$3,
            'complete','complete',$4,'{}'::jsonb,$5,$5,FALSE
        )
        RETURNING evidence_seq
        "#,
    )
    .bind(evidence_id)
    .bind(event_id)
    .bind(client_id)
    .bind(SqlJson(json!({
        "scope_complete": true,
        "scope_revision": scope_revision,
        "client_id": client_id,
    })))
    .bind(observed_at)
    .fetch_one(pool)
    .await
    .unwrap();
    (evidence_id, evidence_seq)
}

async fn insert_unprocessed_backup_failure_evidence(
    pool: &PgPool,
    client_id: &str,
    source_event_id: &str,
) -> i64 {
    let (evidence_seq, target_count) = sqlx::query_as::<_, (i64, i64)>(
        r#"
        WITH inserted AS (
            INSERT INTO alert_policy_evidence (
                id,source_kind,source_event_id,fact_kind,natural_key,
                confirmation_bucket_key,subject_client_id,target_kind,target_id,
                source_status,completeness,subject_snapshot,payload,observed_at,
                causation_id,schedule_lineage,evaluation_pending
            ) VALUES (
                $1,'backup.failure',$2,'occurrence',$2,$2,$3,
                'backup_request',$2,'execution_failed','complete',$4,$5,
                clock_timestamp(),$6,ARRAY[$6]::uuid[],TRUE
            )
            RETURNING id,evidence_seq
        ), stamped AS (
            INSERT INTO alert_policy_evidence_targets (
                evidence_id,evidence_seq,policy_rule_id,rule_version
            )
            SELECT inserted.id,inserted.evidence_seq,rule.id,rule.rule_version
            FROM inserted
            JOIN policy_rules rule ON rule.evidence_source='backup.failure'
            JOIN policy_groups policy ON policy.id=rule.group_id
            WHERE rule.enabled AND policy.enabled
            RETURNING 1
        )
        SELECT inserted.evidence_seq,(SELECT count(*) FROM stamped)
        FROM inserted
        "#,
    )
    .bind(Uuid::new_v4())
    .bind(source_event_id)
    .bind(client_id)
    .bind(SqlJson(json!({
        "scope_complete":true,
        "scope_revision":1,
        "client_id":client_id,
        "display_name":client_id,
        "status":"online",
        "tags":[],
        "vps_rules":{},
    })))
    .bind(SqlJson(json!({
        "status":"execution_failed",
        "backup_request_id":source_event_id,
        "client_id":client_id,
    })))
    .bind(Uuid::new_v4())
    .fetch_one(pool)
    .await
    .unwrap();
    assert!(target_count > 0, "pending fixture has no immutable owner");
    evidence_seq
}
