#[tokio::test]
async fn postgres_manual_delivery_dispatches_fence_revisions_and_dedupe_concurrently() {
    let Some(db) = PgReliabilityTestDb::maybe_new().await else {
        return;
    };
    let operator = postgres_network_operator(&db.repo).await;

    let channel_id = Uuid::new_v4();
    let channel_request = |target: &str| CreateFleetAlertNotificationChannelRequest {
        id: Some(channel_id),
        name: "dispatch-owner-channel".to_string(),
        scope_kind: "global".to_string(),
        scope_value: None,
        min_severity: Some("warning".to_string()),
        categories: Some(vec!["agent_status".to_string()]),
        operator_states: Some(vec!["open".to_string()]),
        delivery_kind: "webhook".to_string(),
        target: target.to_string(),
        cooldown_secs: Some(60),
        enabled: Some(true),
        notes: None,
        confirmed: true,
    };
    let original_channel = db
        .repo
        .upsert_fleet_alert_notification_channel(
            &channel_request("https://www.cloudflare.com/dispatch-owner-original"),
            &operator,
        )
        .await
        .unwrap();
    let notification_candidate =
        |channel: &crate::model_alert_notifications::FleetAlertNotificationChannelView| {
            FleetAlertNotificationCandidate {
                channel_id: channel.id,
                channel_revision_hash:
                    crate::repository_alert_notifications::fleet_alert_notification_channel_revision_hash(
                        channel,
                    ),
                channel_name: channel.name.clone(),
                alert_id: "agent_status:dispatch-owner".to_string(),
                alert_severity: "critical".to_string(),
                alert_category: "agent_status".to_string(),
                status: "queued".to_string(),
                delivery_kind: channel.delivery_kind.clone(),
                target: channel.target.clone(),
                dedupe_key: "dispatch-owner-channel-dedupe".to_string(),
                payload: json!({"schema": "test"}),
                cooldown_until_unix: crate::unix_now() as i64 + 60,
            }
        };
    let stale_notification = notification_candidate(&original_channel);
    let current_channel = db
        .repo
        .upsert_fleet_alert_notification_channel(
            &channel_request("https://www.cloudflare.com/dispatch-owner-current"),
            &operator,
        )
        .await
        .unwrap();
    assert!(db
        .repo
        .record_fleet_alert_notification_deliveries(&[stale_notification], &operator)
        .await
        .unwrap()
        .is_empty());
    let current_notification = notification_candidate(&current_channel);
    let (left, right) = tokio::join!(
        db.repo.record_fleet_alert_notification_deliveries(
            std::slice::from_ref(&current_notification),
            &operator,
        ),
        db.repo.record_fleet_alert_notification_deliveries(
            std::slice::from_ref(&current_notification),
            &operator,
        ),
    );
    assert_eq!(left.unwrap().len() + right.unwrap().len(), 1);

    let rule_id = Uuid::new_v4();
    let rule_request = |target: &str| CreateWebhookRuleRequest {
        id: Some(rule_id),
        name: "dispatch-owner-rule".to_string(),
        enabled: true,
        expression: "interval.1min".to_string(),
        target: target.to_string(),
        body_template: String::new(),
        signing_secret: None,
        clear_signing_secret: false,
        cooldown_secs: Some(60),
        notes: None,
        confirmed: true,
    };
    let original_rule = db
        .repo
        .upsert_webhook_rule(
            &rule_request("https://www.cloudflare.com/dispatch-rule-original"),
            &operator,
        )
        .await
        .unwrap();
    let webhook_candidate =
        |rule: &crate::model_webhook_rules::WebhookRuleView| WebhookRuleDeliveryCandidate {
            rule_id: rule.id,
            rule_name: rule.name.clone(),
            event_kind: "manual.test".to_string(),
            event_id: "dispatch-owner-event".to_string(),
            target: rule.target.clone(),
            dedupe_key: "dispatch-owner-rule-dedupe".to_string(),
            payload: json!({"schema": "test"}),
            matched_vps: Vec::new(),
            message: "test".to_string(),
            rule_revision_hash: crate::repository_webhook_rules::webhook_rule_revision_hash(rule)
                .unwrap(),
            signing_secret: rule.signing_secret.clone(),
            cooldown_until_unix: crate::unix_now() as i64 + 60,
            actor_id: Some(operator.operator.id),
        };
    let stale_webhook = webhook_candidate(&original_rule);
    let current_rule = db
        .repo
        .upsert_webhook_rule(
            &rule_request("https://www.cloudflare.com/dispatch-rule-current"),
            &operator,
        )
        .await
        .unwrap();
    assert!(db
        .repo
        .record_webhook_rule_deliveries(&[stale_webhook])
        .await
        .unwrap()
        .is_empty());
    let current_webhook = webhook_candidate(&current_rule);
    let (left, right) = tokio::join!(
        db.repo
            .record_webhook_rule_deliveries(std::slice::from_ref(&current_webhook)),
        db.repo
            .record_webhook_rule_deliveries(std::slice::from_ref(&current_webhook)),
    );
    assert_eq!(left.unwrap().len() + right.unwrap().len(), 1);

    db.cleanup().await;
}

#[tokio::test]
async fn postgres_alert_configuration_bulk_mutations_are_ordered_and_atomic() {
    let Some(db) = PgReliabilityTestDb::maybe_new().await else {
        return;
    };
    let operator = postgres_network_operator(&db.repo).await;

    let mut channels = Vec::new();
    for suffix in ["one", "two"] {
        channels.push(
            db.repo
                .upsert_fleet_alert_notification_channel(
                    &CreateFleetAlertNotificationChannelRequest {
                        id: Some(Uuid::new_v4()),
                        name: format!("bulk-channel-{suffix}"),
                        scope_kind: "global".to_string(),
                        scope_value: None,
                        min_severity: Some("warning".to_string()),
                        categories: Some(vec!["agent_status".to_string()]),
                        operator_states: Some(vec!["open".to_string()]),
                        delivery_kind: "webhook".to_string(),
                        target: format!("https://www.cloudflare.com/bulk-channel-{suffix}"),
                        cooldown_secs: Some(60),
                        enabled: Some(true),
                        notes: None,
                        confirmed: true,
                    },
                    &operator,
                )
                .await
                .unwrap(),
        );
    }
    let channel_disable = FleetAlertNotificationChannelBulkRequest {
        action: FleetAlertNotificationChannelBulkAction::Disable,
        confirmed: true,
        items: channels
            .iter()
            .rev()
            .map(|channel| FleetAlertNotificationChannelBulkItem {
                id: channel.id,
                reviewed_name: channel.name.clone(),
                expected_updated_at: channel.updated_at.clone(),
            })
            .collect(),
    };
    let channel_outcome = db
        .repo
        .bulk_mutate_fleet_alert_notification_channels(&channel_disable, &operator)
        .await
        .unwrap();
    assert_eq!(
        channel_outcome
            .outcomes
            .iter()
            .map(|outcome| outcome.id)
            .collect::<Vec<_>>(),
        channel_disable
            .items
            .iter()
            .map(|item| item.id)
            .collect::<Vec<_>>()
    );
    for (outcome, reviewed) in channel_outcome.outcomes.iter().zip(&channel_disable.items) {
        let record = outcome
            .record
            .as_ref()
            .expect("a committed channel state change must return its exact record");
        assert_eq!(record.id, reviewed.id);
        assert_eq!(record.name, reviewed.reviewed_name);
        assert!(!record.enabled);
        assert_ne!(record.updated_at, reviewed.expected_updated_at);
    }
    let current_channels = db
        .repo
        .list_fleet_alert_notification_channels(100, None, None, None, None)
        .await
        .unwrap()
        .into_iter()
        .filter(|channel| channels.iter().any(|created| created.id == channel.id))
        .map(|channel| (channel.id, channel))
        .collect::<HashMap<_, _>>();
    assert!(current_channels.values().all(|channel| !channel.enabled));
    let stale_channel_enable = FleetAlertNotificationChannelBulkRequest {
        action: FleetAlertNotificationChannelBulkAction::Enable,
        confirmed: true,
        items: channel_disable
            .items
            .iter()
            .enumerate()
            .map(|(index, item)| FleetAlertNotificationChannelBulkItem {
                id: item.id,
                reviewed_name: item.reviewed_name.clone(),
                expected_updated_at: if index == 0 {
                    current_channels[&item.id].updated_at.clone()
                } else {
                    item.expected_updated_at.clone()
                },
            })
            .collect(),
    };
    assert!(db
        .repo
        .bulk_mutate_fleet_alert_notification_channels(&stale_channel_enable, &operator)
        .await
        .unwrap_err()
        .to_string()
        .contains("fleet_alert_notification_channel_bulk_review_stale"));
    assert_eq!(
        sqlx::query_scalar::<_, i64>(
            "SELECT count(*) FROM fleet_alert_notification_channels WHERE id=ANY($1::uuid[]) AND enabled",
        )
        .bind(channels.iter().map(|channel| channel.id).collect::<Vec<_>>())
        .fetch_one(&db.pool)
        .await
        .unwrap(),
        0,
        "one stale channel must roll back the complete reviewed batch"
    );

    let mut webhook_rules = Vec::new();
    for suffix in ["one", "two"] {
        webhook_rules.push(
            db.repo
                .upsert_webhook_rule(
                    &CreateWebhookRuleRequest {
                        id: Some(Uuid::new_v4()),
                        name: format!("bulk-webhook-{suffix}"),
                        enabled: true,
                        expression: if suffix == "two" {
                            "interval.1min && vps.rules:traffic.reset_day >= 1".to_string()
                        } else {
                            "interval.1min".to_string()
                        },
                        target: format!("https://www.cloudflare.com/bulk-webhook-{suffix}"),
                        body_template: "{event.kind}".to_string(),
                        signing_secret: Some(format!("secret-{suffix}")),
                        clear_signing_secret: false,
                        cooldown_secs: Some(60),
                        notes: None,
                        confirmed: true,
                    },
                    &operator,
                )
                .await
                .unwrap(),
        );
    }
    let webhook_disable = WebhookRuleBulkRequest {
        action: WebhookRuleBulkAction::Disable,
        confirmed: true,
        items: webhook_rules
            .iter()
            .rev()
            .map(|rule| WebhookRuleBulkItem {
                id: rule.id,
                reviewed_name: rule.name.clone(),
                expected_updated_at: rule.updated_at.clone(),
            })
            .collect(),
    };
    let scope_error = db
        .repo
        .bulk_mutate_webhook_rules(&webhook_disable, &operator, false)
        .await
        .unwrap_err();
    assert!(scope_error
        .to_string()
        .contains("vps_rule_selector_scope_required"));
    assert_eq!(
        sqlx::query_scalar::<_, i64>(
            "SELECT count(*) FROM webhook_rules WHERE id=ANY($1::uuid[]) AND enabled",
        )
        .bind(webhook_rules.iter().map(|rule| rule.id).collect::<Vec<_>>())
        .fetch_one(&db.pool)
        .await
        .unwrap(),
        2,
        "a missing VPS-rule read scope must reject the complete reviewed batch"
    );
    let webhook_outcome = db
        .repo
        .bulk_mutate_webhook_rules(&webhook_disable, &operator, true)
        .await
        .unwrap();
    assert_eq!(
        webhook_outcome
            .outcomes
            .iter()
            .map(|outcome| outcome.id)
            .collect::<Vec<_>>(),
        webhook_disable
            .items
            .iter()
            .map(|item| item.id)
            .collect::<Vec<_>>()
    );
    for (outcome, reviewed) in webhook_outcome.outcomes.iter().zip(&webhook_disable.items) {
        let record = outcome
            .record
            .as_ref()
            .expect("a committed webhook state change must return its exact record");
        assert_eq!(record.id, reviewed.id);
        assert_eq!(record.name, reviewed.reviewed_name);
        assert!(!record.enabled);
        assert!(record.signing_secret_set);
        assert_ne!(record.updated_at, reviewed.expected_updated_at);
    }
    let serialized_webhooks = serde_json::to_value(&webhook_outcome).unwrap();
    for outcome in serialized_webhooks["outcomes"].as_array().unwrap() {
        let record = outcome["record"].as_object().unwrap();
        assert!(
            !record.contains_key("signing_secret"),
            "exact mutation responses must never serialize webhook secrets"
        );
        assert_eq!(record.get("signing_secret_set"), Some(&json!(true)));
    }
    let current_webhooks = db
        .repo
        .list_webhook_rules(100, None)
        .await
        .unwrap()
        .into_iter()
        .filter(|rule| webhook_rules.iter().any(|created| created.id == rule.id))
        .map(|rule| (rule.id, rule))
        .collect::<HashMap<_, _>>();
    assert!(current_webhooks.values().all(|rule| !rule.enabled));
    assert!(current_webhooks
        .values()
        .all(|rule| rule.signing_secret_set));
    let stale_webhook_enable = WebhookRuleBulkRequest {
        action: WebhookRuleBulkAction::Enable,
        confirmed: true,
        items: webhook_disable
            .items
            .iter()
            .enumerate()
            .map(|(index, item)| WebhookRuleBulkItem {
                id: item.id,
                reviewed_name: item.reviewed_name.clone(),
                expected_updated_at: if index == 0 {
                    current_webhooks[&item.id].updated_at.clone()
                } else {
                    item.expected_updated_at.clone()
                },
            })
            .collect(),
    };
    assert!(db
        .repo
        .bulk_mutate_webhook_rules(&stale_webhook_enable, &operator, true)
        .await
        .unwrap_err()
        .to_string()
        .contains("webhook_rule_bulk_review_stale"));
    assert_eq!(
        sqlx::query_scalar::<_, i64>(
            "SELECT count(*) FROM webhook_rules WHERE id=ANY($1::uuid[]) AND enabled",
        )
        .bind(webhook_rules.iter().map(|rule| rule.id).collect::<Vec<_>>())
        .fetch_one(&db.pool)
        .await
        .unwrap(),
        0,
        "one stale webhook must roll back the complete reviewed batch"
    );

    let channel_delete = FleetAlertNotificationChannelBulkRequest {
        action: FleetAlertNotificationChannelBulkAction::Delete,
        confirmed: true,
        items: channel_disable
            .items
            .iter()
            .map(|item| FleetAlertNotificationChannelBulkItem {
                id: item.id,
                reviewed_name: item.reviewed_name.clone(),
                expected_updated_at: current_channels[&item.id].updated_at.clone(),
            })
            .collect(),
    };
    assert!(db
        .repo
        .bulk_mutate_fleet_alert_notification_channels(&channel_delete, &operator)
        .await
        .unwrap()
        .outcomes
        .iter()
        .all(|outcome| outcome.result == "deleted"));
    let webhook_delete = WebhookRuleBulkRequest {
        action: WebhookRuleBulkAction::Delete,
        confirmed: true,
        items: webhook_disable
            .items
            .iter()
            .map(|item| WebhookRuleBulkItem {
                id: item.id,
                reviewed_name: item.reviewed_name.clone(),
                expected_updated_at: current_webhooks[&item.id].updated_at.clone(),
            })
            .collect(),
    };
    assert!(db
        .repo
        .bulk_mutate_webhook_rules(&webhook_delete, &operator, true)
        .await
        .unwrap()
        .outcomes
        .iter()
        .all(|outcome| outcome.result == "deleted"));
    assert_eq!(
        sqlx::query_scalar::<_, i64>(
            "SELECT (SELECT count(*) FROM fleet_alert_notification_channels WHERE id=ANY($1::uuid[])) + (SELECT count(*) FROM webhook_rules WHERE id=ANY($2::uuid[]))",
        )
        .bind(channels.iter().map(|channel| channel.id).collect::<Vec<_>>())
        .bind(webhook_rules.iter().map(|rule| rule.id).collect::<Vec<_>>())
        .fetch_one(&db.pool)
        .await
        .unwrap(),
        0
    );

    insert_client(&db.pool, "bulk-policy-summary-client", None).await;
    let mut policies = Vec::new();
    for suffix in ["one", "two"] {
        policies.push(
            db.repo
                .upsert_fleet_alert_policy(
                    &CreateFleetAlertPolicyRequest {
                        id: None,
                        name: format!("bulk-policy-{suffix}"),
                        enabled: false,
                        selector_expression: "*".to_string(),
                        rules: vec![postgres_backup_failure_rule_request(None, "warning")],
                        notes: None,
                        confirmed: true,
                        preview_hash: None,
                    },
                    &operator,
                )
                .await
                .unwrap(),
        );
    }
    let policy_enable = FleetAlertPolicyBulkRequest {
        action: FleetAlertPolicyBulkAction::Enable,
        confirmed: true,
        items: policies
            .iter()
            .rev()
            .map(|policy| FleetAlertPolicyBulkItem {
                id: policy.id,
                reviewed_name: policy.name.clone(),
                expected_updated_at: policy.updated_at.clone(),
            })
            .collect(),
    };
    let policy_outcome = db
        .repo
        .bulk_mutate_fleet_alert_policies(&policy_enable, &operator, true)
        .await
        .unwrap();
    assert_eq!(
        policy_outcome
            .outcomes
            .iter()
            .map(|outcome| outcome.id)
            .collect::<Vec<_>>(),
        policy_enable
            .items
            .iter()
            .map(|item| item.id)
            .collect::<Vec<_>>()
    );
    for (outcome, reviewed) in policy_outcome.outcomes.iter().zip(&policy_enable.items) {
        let record = outcome
            .record
            .as_ref()
            .expect("a committed policy state change must return its exact policy and rules");
        assert_eq!(record.id, reviewed.id);
        assert_eq!(record.name, reviewed.reviewed_name);
        assert!(record.enabled);
        assert_ne!(record.updated_at, reviewed.expected_updated_at);
        assert_eq!(record.rules.len(), 1);
        let previous = policies
            .iter()
            .find(|policy| policy.id == record.id)
            .unwrap();
        assert_eq!(
            record.rules[0].rule_version,
            previous.rules[0].rule_version + 1
        );
    }
    let mut current_policies = HashMap::new();
    for policy in &policies {
        let current = db
            .repo
            .get_fleet_alert_policy(policy.id, true)
            .await
            .unwrap();
        assert!(current.enabled);
        assert_eq!(
            current.rules[0].rule_version,
            policy.rules[0].rule_version + 1
        );
        let returned = policy_outcome
            .outcomes
            .iter()
            .find(|outcome| outcome.id == current.id)
            .and_then(|outcome| outcome.record.as_ref())
            .unwrap();
        assert_eq!(returned.matched_vps_count, current.matched_vps_count);
        assert_eq!(returned.matched_vps_count, 1);
        assert_eq!(returned.active_info_count, current.active_info_count);
        assert_eq!(returned.active_warning_count, current.active_warning_count);
        assert_eq!(
            returned.active_critical_count,
            current.active_critical_count
        );
        assert_eq!(returned.incomplete_vps_count, current.incomplete_vps_count);
        assert_eq!(returned.last_evaluated_at, current.last_evaluated_at);
        current_policies.insert(current.id, current);
    }
    let stale_policy_disable = FleetAlertPolicyBulkRequest {
        action: FleetAlertPolicyBulkAction::Disable,
        confirmed: true,
        items: policy_enable
            .items
            .iter()
            .enumerate()
            .map(|(index, item)| FleetAlertPolicyBulkItem {
                id: item.id,
                reviewed_name: item.reviewed_name.clone(),
                expected_updated_at: if index == 0 {
                    current_policies[&item.id].updated_at.clone()
                } else {
                    item.expected_updated_at.clone()
                },
            })
            .collect(),
    };
    assert!(db
        .repo
        .bulk_mutate_fleet_alert_policies(&stale_policy_disable, &operator, true)
        .await
        .unwrap_err()
        .to_string()
        .contains("fleet_alert_policy_bulk_review_stale"));
    assert_eq!(
        sqlx::query_scalar::<_, i64>(
            "SELECT count(*) FROM policy_groups WHERE id=ANY($1::uuid[]) AND enabled",
        )
        .bind(policies.iter().map(|policy| policy.id).collect::<Vec<_>>())
        .fetch_one(&db.pool)
        .await
        .unwrap(),
        2,
        "one stale policy must roll back the complete reviewed lifecycle batch"
    );

    let policy_delete = FleetAlertPolicyBulkRequest {
        action: FleetAlertPolicyBulkAction::Delete,
        confirmed: true,
        items: policy_enable
            .items
            .iter()
            .map(|item| FleetAlertPolicyBulkItem {
                id: item.id,
                reviewed_name: item.reviewed_name.clone(),
                expected_updated_at: current_policies[&item.id].updated_at.clone(),
            })
            .collect(),
    };
    let deleted = db
        .repo
        .bulk_mutate_fleet_alert_policies(&policy_delete, &operator, true)
        .await
        .unwrap();
    assert!(deleted
        .outcomes
        .iter()
        .all(|outcome| outcome.result == "deleted"));
    assert_eq!(
        sqlx::query_scalar::<_, i64>(
            "SELECT count(*) FROM policy_groups WHERE id=ANY($1::uuid[])",
        )
        .bind(policies.iter().map(|policy| policy.id).collect::<Vec<_>>())
        .fetch_one(&db.pool)
        .await
        .unwrap(),
        0
    );

    db.cleanup().await;
}

#[tokio::test]
async fn postgres_webhook_rule_state_change_leaves_delivery_terminalization_to_worker() {
    fn request(
        rule_id: Uuid,
        enabled: bool,
        signing_secret: Option<&str>,
        clear_signing_secret: bool,
        target_suffix: &str,
    ) -> CreateWebhookRuleRequest {
        CreateWebhookRuleRequest {
            id: Some(rule_id),
            name: "signed-lifecycle-rule".to_string(),
            enabled,
            expression: "interval.1min".to_string(),
            target: format!("https://www.cloudflare.com/{target_suffix}"),
            body_template: "{event.kind}".to_string(),
            signing_secret: signing_secret.map(str::to_string),
            clear_signing_secret,
            cooldown_secs: Some(60),
            notes: None,
            confirmed: true,
        }
    }

    fn delivery(
        rule: &crate::model_webhook_rules::WebhookRuleView,
        operator_id: Uuid,
        event_id: &str,
        signing_secret: Option<&str>,
    ) -> WebhookRuleDeliveryCandidate {
        WebhookRuleDeliveryCandidate {
            rule_id: rule.id,
            rule_name: "signed-lifecycle-rule".to_string(),
            event_kind: "manual.test".to_string(),
            event_id: event_id.to_string(),
            target: "https://www.cloudflare.com/signed-lifecycle".to_string(),
            dedupe_key: format!("signed-lifecycle:{event_id}"),
            payload: json!({"event_id": event_id}),
            matched_vps: Vec::new(),
            message: "lifecycle test".to_string(),
            rule_revision_hash: crate::repository_webhook_rules::webhook_rule_revision_hash(rule)
                .unwrap(),
            signing_secret: signing_secret.map(str::to_string),
            cooldown_until_unix: 0,
            actor_id: Some(operator_id),
        }
    }

    let Some(db) = PgReliabilityTestDb::maybe_new().await else {
        return;
    };
    let operator = postgres_network_operator(&db.repo).await;
    let rule_id = Uuid::new_v4();
    let created = db
        .repo
        .upsert_webhook_rule(
            &request(rule_id, true, Some("alpha-secret"), false, "create"),
            &operator,
        )
        .await
        .unwrap();
    assert!(created.signing_secret_set);
    assert_eq!(created.signing_secret.as_deref(), Some("alpha-secret"));
    assert!(serde_json::to_value(&created)
        .unwrap()
        .get("signing_secret")
        .is_none());

    let preserved = db
        .repo
        .upsert_webhook_rule(&request(rule_id, true, None, false, "preserve"), &operator)
        .await
        .unwrap();
    assert_eq!(preserved.signing_secret.as_deref(), Some("alpha-secret"));
    let rotated = db
        .repo
        .upsert_webhook_rule(
            &request(rule_id, true, Some("beta-secret"), false, "rotate"),
            &operator,
        )
        .await
        .unwrap();
    assert_eq!(rotated.signing_secret.as_deref(), Some("beta-secret"));

    let retryable = [
        delivery(
            &rotated,
            operator.operator.id,
            "signed-lifecycle-1",
            Some("beta-secret"),
        ),
        delivery(
            &rotated,
            operator.operator.id,
            "signed-lifecycle-2",
            Some("beta-secret"),
        ),
    ];
    assert_eq!(
        db.repo
            .record_webhook_rule_deliveries(&retryable)
            .await
            .unwrap()
            .len(),
        2
    );
    sqlx::query(
        r#"
        UPDATE webhook_rule_deliveries
        SET status='failed', error='retryable', next_attempt_at=now()
        WHERE event_id='signed-lifecycle-2'
        "#,
    )
    .execute(&db.pool)
    .await
    .unwrap();

    let disabled = db
        .repo
        .upsert_webhook_rule(&request(rule_id, false, None, false, "disabled"), &operator)
        .await
        .unwrap();
    assert!(!disabled.enabled);
    assert_eq!(disabled.signing_secret.as_deref(), Some("beta-secret"));
    assert_eq!(
        sqlx::query_scalar::<_, i64>(
            r#"
            SELECT count(*)
            FROM webhook_rule_deliveries
            WHERE rule_id=$1
              AND status IN ('queued','failed')
            "#,
        )
        .bind(rule_id)
        .fetch_one(&db.pool)
        .await
        .unwrap(),
        2
    );

    let cleared = db
        .repo
        .upsert_webhook_rule(&request(rule_id, true, None, true, "cleared"), &operator)
        .await
        .unwrap();
    assert!(!cleared.signing_secret_set);
    assert_eq!(cleared.signing_secret, None);
    assert_eq!(
        db.repo
            .record_webhook_rule_deliveries(&[delivery(
                &cleared,
                operator.operator.id,
                "signed-lifecycle-3",
                None,
            )])
            .await
            .unwrap()
            .len(),
        1
    );
    db.repo
        .delete_webhook_rule(rule_id, "signed-lifecycle-rule", &operator)
        .await
        .unwrap();
    assert_eq!(
        sqlx::query_scalar::<_, i64>("SELECT count(*) FROM webhook_rules WHERE id=$1")
            .bind(rule_id)
            .fetch_one(&db.pool)
            .await
            .unwrap(),
        0
    );
    assert_eq!(
        sqlx::query_scalar::<_, i64>(
            "SELECT count(*) FROM webhook_rule_deliveries WHERE rule_id=$1",
        )
        .bind(rule_id)
        .fetch_one(&db.pool)
        .await
        .unwrap(),
        3
    );
    assert_eq!(
        sqlx::query_scalar::<_, i64>(
            r#"
            SELECT count(*)
            FROM webhook_rule_deliveries
            WHERE rule_id=$1
              AND status IN ('queued','failed')
            "#,
        )
        .bind(rule_id)
        .fetch_one(&db.pool)
        .await
        .unwrap(),
        3
    );
    assert!(!sqlx::query_scalar::<_, bool>(
        r#"
        SELECT EXISTS (
            SELECT 1
            FROM audit_logs
            WHERE target=$1
              AND (
                metadata::text LIKE '%alpha-secret%'
                OR metadata::text LIKE '%beta-secret%'
              )
        )
        "#,
    )
    .bind(format!("webhook_rule:{rule_id}"))
    .fetch_one(&db.pool)
    .await
    .unwrap());

    db.cleanup().await;
}

async fn assert_system_dashboard_target_projection_matches_exact(db: &PgReliabilityTestDb) {
    let expected = sqlx::query(
        r#"
        SELECT
            target_metrics.queued,
            target_metrics.dispatching,
            target_metrics.running,
            target_metrics.deadline_expired_active,
            target_metrics.control_timeout_last_24h,
            target_metrics.agent_timeout_last_24h,
            target_metrics.agent_lost_last_24h,
            target_metrics.canceled_last_24h,
            target_metrics.total_dispatch_attempts,
            target_metrics.retried_targets,
            target_metrics.cancel_requested,
            target_metrics.cancel_sent,
            target_metrics.cancel_acked,
            target_metrics.cancel_awaiting_ack,
            job_metrics.active_jobs,
            job_metrics.queued_jobs,
            job_metrics.running_jobs
        FROM (
            SELECT
                count(*) FILTER (
                    WHERE completed_at IS NULL AND status = 'queued'
                )::bigint AS queued,
                count(*) FILTER (
                    WHERE completed_at IS NULL AND status = 'dispatching'
                )::bigint AS dispatching,
                count(*) FILTER (
                    WHERE completed_at IS NULL AND status = 'running'
                )::bigint AS running,
                count(*) FILTER (
                    WHERE completed_at IS NULL
                      AND status IN ('dispatching', 'running')
                      AND deadline_at IS NOT NULL
                      AND deadline_at <= now()
                )::bigint AS deadline_expired_active,
                count(*) FILTER (
                    WHERE status = 'control_timeout'
                      AND COALESCE(completed_at, result_received_at, started_at)
                            >= now() - interval '24 hours'
                )::bigint AS control_timeout_last_24h,
                count(*) FILTER (
                    WHERE status = 'agent_timeout'
                      AND COALESCE(completed_at, result_received_at, started_at)
                            >= now() - interval '24 hours'
                )::bigint AS agent_timeout_last_24h,
                count(*) FILTER (
                    WHERE status = 'agent_lost'
                      AND COALESCE(completed_at, result_received_at, started_at)
                            >= now() - interval '24 hours'
                )::bigint AS agent_lost_last_24h,
                count(*) FILTER (
                    WHERE status = 'canceled'
                      AND COALESCE(
                            completed_at,
                            cancel_acked_at,
                            cancel_sent_at,
                            cancel_requested_at,
                            started_at
                          ) >= now() - interval '24 hours'
                )::bigint AS canceled_last_24h,
                COALESCE(sum(dispatch_attempts), 0)::bigint
                    AS total_dispatch_attempts,
                count(*) FILTER (WHERE dispatch_attempts > 1)::bigint
                    AS retried_targets,
                count(*) FILTER (WHERE cancel_requested_at IS NOT NULL)::bigint
                    AS cancel_requested,
                count(*) FILTER (WHERE cancel_sent_at IS NOT NULL)::bigint
                    AS cancel_sent,
                count(*) FILTER (WHERE cancel_acked_at IS NOT NULL)::bigint
                    AS cancel_acked,
                count(*) FILTER (
                    WHERE cancel_sent_at IS NOT NULL
                      AND cancel_acked_at IS NULL
                      AND completed_at IS NULL
                )::bigint AS cancel_awaiting_ack
            FROM job_targets
        ) target_metrics
        CROSS JOIN (
            SELECT
                count(*) FILTER (WHERE completed_at IS NULL)::bigint
                    AS active_jobs,
                count(*) FILTER (
                    WHERE completed_at IS NULL AND status = 'queued'
                )::bigint AS queued_jobs,
                count(*) FILTER (
                    WHERE completed_at IS NULL AND status = 'running'
                )::bigint AS running_jobs
            FROM jobs
        ) job_metrics
        "#,
    )
    .fetch_one(&db.pool)
    .await
    .unwrap();
    let actual = db.repo.system_dashboard_snapshot().await.unwrap();
    let expected_i64 = |column| expected.try_get::<i64, _>(column).unwrap();
    let comparisons = [
        (
            "active_jobs",
            actual.dispatch.active_jobs,
            expected_i64("active_jobs"),
        ),
        (
            "queued_jobs",
            actual.dispatch.queued_jobs,
            expected_i64("queued_jobs"),
        ),
        (
            "running_jobs",
            actual.dispatch.running_jobs,
            expected_i64("running_jobs"),
        ),
        (
            "total_dispatch_attempts",
            actual.dispatch.total_dispatch_attempts,
            expected_i64("total_dispatch_attempts"),
        ),
        (
            "retried_targets",
            actual.dispatch.retried_targets,
            expected_i64("retried_targets"),
        ),
        ("queued", actual.targets.queued, expected_i64("queued")),
        (
            "dispatching",
            actual.targets.dispatching,
            expected_i64("dispatching"),
        ),
        ("running", actual.targets.running, expected_i64("running")),
        (
            "deadline_expired_active",
            actual.targets.deadline_expired_active,
            expected_i64("deadline_expired_active"),
        ),
        (
            "control_timeout_last_24h",
            actual.targets.control_timeout_last_24h,
            expected_i64("control_timeout_last_24h"),
        ),
        (
            "agent_timeout_last_24h",
            actual.targets.agent_timeout_last_24h,
            expected_i64("agent_timeout_last_24h"),
        ),
        (
            "agent_lost_last_24h",
            actual.targets.agent_lost_last_24h,
            expected_i64("agent_lost_last_24h"),
        ),
        (
            "canceled_last_24h",
            actual.targets.canceled_last_24h,
            expected_i64("canceled_last_24h"),
        ),
        (
            "cancel_requested",
            actual.cancellations.requested,
            expected_i64("cancel_requested"),
        ),
        (
            "cancel_sent",
            actual.cancellations.sent,
            expected_i64("cancel_sent"),
        ),
        (
            "cancel_acked",
            actual.cancellations.acked,
            expected_i64("cancel_acked"),
        ),
        (
            "cancel_awaiting_ack",
            actual.cancellations.awaiting_ack,
            expected_i64("cancel_awaiting_ack"),
        ),
    ];
    for (metric, actual, expected) in comparisons {
        assert_eq!(
            actual, expected,
            "system dashboard metric {metric} diverged"
        );
    }
    assert_eq!(
        actual.dispatch.queue_depth,
        expected_i64("queued") + expected_i64("dispatching")
    );
    assert_eq!(
        actual.targets.active,
        expected_i64("dispatching") + expected_i64("running")
    );
    type TargetOwnerMetrics = (String, i64, i64, i64, i64, i64, i64, i64, i64, i64);
    let expected_by_owner = sqlx::query_as::<_, TargetOwnerMetrics>(
        r#"
        SELECT *
        FROM (
            SELECT
                client_id,
                count(*) FILTER (
                    WHERE completed_at IS NULL AND status = 'queued'
                )::bigint AS target_queued,
                count(*) FILTER (
                    WHERE completed_at IS NULL AND status = 'dispatching'
                )::bigint AS target_dispatching,
                count(*) FILTER (
                    WHERE completed_at IS NULL AND status = 'running'
                )::bigint AS target_running,
                COALESCE(sum(dispatch_attempts), 0)::bigint
                    AS total_dispatch_attempts,
                count(*) FILTER (WHERE dispatch_attempts > 1)::bigint
                    AS retried_targets,
                count(*) FILTER (WHERE cancel_requested_at IS NOT NULL)::bigint
                    AS cancel_requested,
                count(*) FILTER (WHERE cancel_sent_at IS NOT NULL)::bigint
                    AS cancel_sent,
                count(*) FILTER (WHERE cancel_acked_at IS NOT NULL)::bigint
                    AS cancel_acked,
                count(*) FILTER (
                    WHERE cancel_sent_at IS NOT NULL
                      AND cancel_acked_at IS NULL
                      AND completed_at IS NULL
                )::bigint AS cancel_awaiting_ack
            FROM job_targets
            GROUP BY client_id
        ) metrics
        WHERE target_queued <> 0
           OR target_dispatching <> 0
           OR target_running <> 0
           OR total_dispatch_attempts <> 0
           OR retried_targets <> 0
           OR cancel_requested <> 0
           OR cancel_sent <> 0
           OR cancel_acked <> 0
           OR cancel_awaiting_ack <> 0
        ORDER BY client_id
        "#,
    )
    .fetch_all(&db.pool)
    .await
    .unwrap();
    let projected_by_owner = sqlx::query_as::<_, TargetOwnerMetrics>(
        r#"
        SELECT
            client_id,
            target_queued,
            target_dispatching,
            target_running,
            total_dispatch_attempts,
            retried_targets,
            cancel_requested,
            cancel_sent,
            cancel_acked,
            cancel_awaiting_ack
        FROM system_dashboard_target_metrics
        ORDER BY client_id
        "#,
    )
    .fetch_all(&db.pool)
    .await
    .unwrap();
    assert_eq!(projected_by_owner, expected_by_owner);
}

#[tokio::test]
async fn postgres_system_dashboard_target_projection_preserves_mutation_and_cascade_semantics() {
    let Some(db) = PgReliabilityTestDb::maybe_new().await else {
        return;
    };
    assert_system_dashboard_target_projection_matches_exact(&db).await;

    sqlx::query(
        r#"
        INSERT INTO jobs (
            id, command_type, status, target_count, payload_hash,
            request_fingerprint, completed_at
        ) VALUES
            ('10000000-0000-4000-8000-000000000001', 'shell_argv',
             'queued', 2, 'payload-1', 'request-1', NULL),
            ('10000000-0000-4000-8000-000000000002', 'shell_argv',
             'running', 2, 'payload-2', 'request-2', NULL),
            ('10000000-0000-4000-8000-000000000003', 'shell_argv',
             'completed', 3, 'payload-3', 'request-3', now()),
            ('10000000-0000-4000-8000-000000000004', 'shell_argv',
             'completed', 1, 'payload-4', 'request-4', now())
        "#,
    )
    .execute(&db.pool)
    .await
    .unwrap();
    sqlx::query(
        r#"
        INSERT INTO job_targets (
            job_id, client_id, status, started_at, completed_at,
            dispatch_attempts, deadline_at, cancel_requested_at,
            cancel_sent_at, cancel_acked_at, result_received_at
        ) VALUES
            ('10000000-0000-4000-8000-000000000001', 'current-queued',
             'queued', NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL),
            ('10000000-0000-4000-8000-000000000001', 'current-dispatching',
             'dispatching', now() - interval '1 hour', NULL, 1,
             now() - interval '1 minute', now() - interval '3 minutes',
             now() - interval '2 minutes', NULL, NULL),
            ('10000000-0000-4000-8000-000000000002', 'current-running',
             'running', now() - interval '2 hours', NULL, 2,
             now() + interval '1 hour', now() - interval '4 minutes',
             now() - interval '3 minutes', now() - interval '2 minutes', NULL),
            ('10000000-0000-4000-8000-000000000002', 'recent-control',
             'control_timeout', now() - interval '3 hours',
             now() - interval '1 hour', 3, NULL, NULL, NULL, NULL,
             now() - interval '2 hours'),
            ('10000000-0000-4000-8000-000000000003', 'recent-agent-timeout',
             'agent_timeout', now() - interval '3 hours', NULL, 1, NULL,
             NULL, NULL, NULL, now() - interval '2 hours'),
            ('10000000-0000-4000-8000-000000000003', 'recent-agent-lost',
             'agent_lost', now() - interval '3 hours', NULL, 1, NULL,
             NULL, NULL, NULL, NULL),
            ('10000000-0000-4000-8000-000000000003', 'recent-canceled',
             'canceled', now() - interval '3 hours', NULL, 1, NULL,
             now() - interval '2 hours', NULL, NULL, NULL),
            ('10000000-0000-4000-8000-000000000004', 'old-control',
             'control_timeout', now() - interval '49 hours',
             now() - interval '48 hours', 0, NULL, NULL, NULL, NULL,
             now() - interval '48 hours')
        "#,
    )
    .execute(&db.pool)
    .await
    .unwrap();
    assert_system_dashboard_target_projection_matches_exact(&db).await;

    let nonnegative_error = sqlx::query(
        "UPDATE system_dashboard_target_metrics SET target_queued = -1 \
         WHERE client_id = 'current-queued'",
    )
    .execute(&db.pool)
    .await
    .expect_err("a negative target metric must violate the owner invariant");
    match nonnegative_error {
        sqlx::Error::Database(error) => assert_eq!(
            error.constraint(),
            Some("system_dashboard_target_metrics_nonnegative_check")
        ),
        error => panic!("unexpected nonnegative invariant error: {error}"),
    }
    assert_system_dashboard_target_projection_matches_exact(&db).await;

    sqlx::query(
        r#"
        UPDATE jobs
        SET status = CASE id
                WHEN '10000000-0000-4000-8000-000000000001'::uuid
                    THEN 'running'
                ELSE 'completed'
            END,
            completed_at = CASE id
                WHEN '10000000-0000-4000-8000-000000000001'::uuid
                    THEN NULL
                ELSE now()
            END
        WHERE id IN (
            '10000000-0000-4000-8000-000000000001'::uuid,
            '10000000-0000-4000-8000-000000000002'::uuid
        )
        "#,
    )
    .execute(&db.pool)
    .await
    .unwrap();
    sqlx::query(
        r#"
        UPDATE job_targets
        SET status = CASE client_id
                WHEN 'current-queued' THEN 'running'
                WHEN 'current-dispatching' THEN 'canceled'
                ELSE 'completed'
            END,
            started_at = COALESCE(started_at, now()),
            completed_at = CASE client_id
                WHEN 'current-queued' THEN NULL
                ELSE now()
            END,
            dispatch_attempts = dispatch_attempts + 1,
            cancel_acked_at = CASE client_id
                WHEN 'current-dispatching' THEN now()
                ELSE cancel_acked_at
            END
        WHERE client_id IN (
            'current-queued', 'current-dispatching', 'current-running'
        )
        "#,
    )
    .execute(&db.pool)
    .await
    .unwrap();
    assert_system_dashboard_target_projection_matches_exact(&db).await;

    sqlx::query("UPDATE job_targets SET message = 'unrelated' WHERE message IS NULL")
        .execute(&db.pool)
        .await
        .unwrap();
    assert_system_dashboard_target_projection_matches_exact(&db).await;

    sqlx::query("DELETE FROM job_targets WHERE job_id = $1 AND client_id = 'old-control'")
        .bind(Uuid::parse_str("10000000-0000-4000-8000-000000000004").unwrap())
        .execute(&db.pool)
        .await
        .unwrap();
    assert_system_dashboard_target_projection_matches_exact(&db).await;

    sqlx::query("DELETE FROM jobs WHERE id = $1")
        .bind(Uuid::parse_str("10000000-0000-4000-8000-000000000003").unwrap())
        .execute(&db.pool)
        .await
        .unwrap();
    assert_eq!(
        sqlx::query_scalar::<_, i64>(
            r#"
            SELECT count(*)
            FROM system_dashboard_target_metrics
            WHERE client_id IN (
                'recent-agent-timeout', 'recent-agent-lost', 'recent-canceled'
            )
            "#,
        )
        .fetch_one(&db.pool)
        .await
        .unwrap(),
        0,
        "a cascade that removes every contribution must remove its empty owners"
    );
    assert_system_dashboard_target_projection_matches_exact(&db).await;
    db.cleanup().await;
}

#[tokio::test]
async fn postgres_system_dashboard_target_projection_is_cold_bounded_and_lock_scoped() {
    let Some(db) = PgReliabilityTestDb::maybe_new().await else {
        return;
    };
    let lexical_clients = vec!["bulk-owner_a".to_string(), "bulk-owner-A".to_string()];
    assert_eq!(
        crate::repository_jobs::canonical_target_write_order(&lexical_clients),
        vec!["bulk-owner-A", "bulk-owner_a"]
    );
    let job_id = Uuid::parse_str("20000000-0000-4000-8000-000000000001").unwrap();
    sqlx::query(
        r#"
        INSERT INTO jobs (
            id, command_type, status, target_count, payload_hash,
            request_fingerprint
        ) VALUES ($1, 'shell_argv', 'queued', 2, 'payload', 'request')
        "#,
    )
    .bind(job_id)
    .execute(&db.pool)
    .await
    .unwrap();
    sqlx::query(
        r#"
        INSERT INTO job_targets (
            job_id, client_id, status, dispatch_attempts, deadline_at
        ) VALUES
            ($1, 'concurrent-a', 'queued', 1, now() - interval '1 minute'),
            ($1, 'concurrent-b', 'queued', 1, now() + interval '1 hour')
        "#,
    )
    .bind(job_id)
    .execute(&db.pool)
    .await
    .unwrap();

    let mut unrelated = db.pool.begin().await.unwrap();
    sqlx::query(
        "UPDATE job_targets SET message = 'does-not-affect-counters' \
         WHERE job_id = $1 AND client_id = 'concurrent-a'",
    )
    .bind(job_id)
    .execute(&mut *unrelated)
    .await
    .unwrap();
    sqlx::query(
        "SELECT client_id FROM system_dashboard_target_metrics \
         WHERE client_id = 'concurrent-a' FOR UPDATE NOWAIT",
    )
    .fetch_one(&db.pool)
    .await
    .expect("a zero-delta target update locked its client metric owner");
    unrelated.rollback().await.unwrap();

    let barrier = Arc::new(Barrier::new(2));
    let transition = |client_id: &'static str, status: &'static str| {
        let pool = db.pool.clone();
        let barrier = barrier.clone();
        async move {
            let mut tx = pool.begin().await.unwrap();
            barrier.wait().await;
            sqlx::query(
                "UPDATE job_targets SET status = $3, started_at = now() \
                 WHERE job_id = $1 AND client_id = $2",
            )
            .bind(job_id)
            .bind(client_id)
            .bind(status)
            .execute(&mut *tx)
            .await
            .unwrap();
            tx.commit().await.unwrap();
        }
    };
    tokio::time::timeout(Duration::from_secs(5), async {
        tokio::join!(
            transition("concurrent-a", "dispatching"),
            transition("concurrent-b", "running")
        );
    })
    .await
    .expect("independent target transitions failed to serialize promptly");
    assert_system_dashboard_target_projection_matches_exact(&db).await;

    let left_job_id = Uuid::parse_str("20000000-0000-4000-8000-000000000002").unwrap();
    let right_job_id = Uuid::parse_str("20000000-0000-4000-8000-000000000003").unwrap();
    sqlx::query(
        r#"
        INSERT INTO jobs (
            id, command_type, status, target_count, payload_hash,
            request_fingerprint
        ) VALUES
            ($1, 'shell_argv', 'queued', 2, 'payload-left', 'request-left'),
            ($2, 'shell_argv', 'queued', 2, 'payload-right', 'request-right')
        "#,
    )
    .bind(left_job_id)
    .bind(right_job_id)
    .execute(&db.pool)
    .await
    .unwrap();
    let bulk_barrier = Arc::new(Barrier::new(2));
    let insert_bulk = |bulk_job_id: Uuid, reverse: bool| {
        let pool = db.pool.clone();
        let bulk_barrier = bulk_barrier.clone();
        async move {
            bulk_barrier.wait().await;
            let clients = if reverse {
                vec!["bulk-owner_a".to_string(), "bulk-owner-A".to_string()]
            } else {
                vec!["bulk-owner-A".to_string(), "bulk-owner_a".to_string()]
            };
            sqlx::query(
                r#"
                INSERT INTO job_targets (job_id, client_id, status)
                SELECT $1, client_id, 'queued'
                FROM unnest($2::text[]) WITH ORDINALITY AS input(client_id, ordinal)
                ORDER BY ordinal
                "#,
            )
            .bind(bulk_job_id)
            .bind(&clients)
            .execute(&pool)
            .await
            .unwrap();
        }
    };
    tokio::time::timeout(Duration::from_secs(5), async {
        tokio::join!(
            insert_bulk(left_job_id, false),
            insert_bulk(right_job_id, true)
        );
    })
    .await
    .expect("opposite input order deadlocked canonical per-client metric owners");
    assert_system_dashboard_target_projection_matches_exact(&db).await;

    let deadline_z_job_id = Uuid::parse_str("20000000-0000-4000-8000-000000000004").unwrap();
    let deadline_a_job_id = Uuid::parse_str("20000000-0000-4000-8000-000000000005").unwrap();
    let setwise_a_job_id = Uuid::parse_str("20000000-0000-4000-8000-000000000006").unwrap();
    let setwise_z_job_id = Uuid::parse_str("20000000-0000-4000-8000-000000000007").unwrap();
    sqlx::query(
        r#"
        INSERT INTO jobs (
            id, command_type, status, target_count, payload_hash,
            operation, request_fingerprint, max_timeout_secs
        ) VALUES
            ($1, 'shell_argv', 'running', 1, 'deadline-z-payload',
             $5, 'deadline-z-request', 1),
            ($2, 'shell_argv', 'running', 1, 'deadline-a-payload',
             $5, 'deadline-a-request', 1),
            ($3, 'shell_argv', 'running', 1, 'setwise-a-payload',
             $5, 'setwise-a-request', 1),
            ($4, 'shell_argv', 'running', 1, 'setwise-z-payload',
             $5, 'setwise-z-request', 1)
        "#,
    )
    .bind(deadline_z_job_id)
    .bind(deadline_a_job_id)
    .bind(setwise_a_job_id)
    .bind(setwise_z_job_id)
    .bind(SqlJson(JobCommand::Shell {
        argv: vec!["true".to_string()],
        pty: false,
    }))
    .execute(&db.pool)
    .await
    .unwrap();
    sqlx::query(
        r#"
        INSERT INTO job_targets (
            job_id, client_id, status, started_at, dispatch_attempts,
            deadline_at
        ) VALUES
            ($1, 'deadline-owner-Z', 'running', now() - interval '3 hours',
             1, now() - interval '2 hours'),
            ($2, 'deadline-owner-A', 'running', now() - interval '2 hours',
             1, now() - interval '1 hour'),
            ($3, 'deadline-owner-A', 'running', now() - interval '1 hour',
             1, now() + interval '1 hour'),
            ($4, 'deadline-owner-Z', 'running', now() - interval '1 hour',
             1, now() + interval '1 hour')
        "#,
    )
    .bind(deadline_z_job_id)
    .bind(deadline_a_job_id)
    .bind(setwise_a_job_id)
    .bind(setwise_z_job_id)
    .execute(&db.pool)
    .await
    .unwrap();
    let deadline_barrier = Arc::new(Barrier::new(2));
    let deadline_repo = db.repo.clone();
    let deadline_start = deadline_barrier.clone();
    let expire_deadlines = async move {
        deadline_start.wait().await;
        deadline_repo
            .expire_control_timeout_targets(2)
            .await
            .unwrap()
    };
    let setwise_pool = db.pool.clone();
    let setwise_start = deadline_barrier.clone();
    let update_same_owners = async move {
        setwise_start.wait().await;
        sqlx::query(
            r#"
            UPDATE job_targets
            SET dispatch_attempts = dispatch_attempts + 1
            WHERE job_id IN ($1, $2)
            "#,
        )
        .bind(setwise_a_job_id)
        .bind(setwise_z_job_id)
        .execute(&setwise_pool)
        .await
        .unwrap();
    };
    let (expired, ()) = tokio::time::timeout(Duration::from_secs(10), async {
        tokio::join!(expire_deadlines, update_same_owners)
    })
    .await
    .expect("reverse-deadline reconciliation deadlocked a set-wise owner update");
    assert_eq!(
        expired
            .iter()
            .map(|target| target.client_id.as_str())
            .collect::<Vec<_>>(),
        vec!["deadline-owner-Z", "deadline-owner-A"],
        "canonical owner prelocking must not reorder deadline results"
    );
    assert_system_dashboard_target_projection_matches_exact(&db).await;

    sqlx::query(
        r#"
        INSERT INTO jobs (
            id, command_type, status, target_count, payload_hash,
            request_fingerprint, completed_at
        )
        SELECT
            md5('system-dashboard-filler-job-' || value::text)::uuid,
            'shell_argv',
            'completed',
            1,
            md5('system-dashboard-filler-payload-' || value::text),
            'system-dashboard-filler-request-' || value::text,
            now() - interval '90 days'
        FROM generate_series(1, 40000) AS value
        "#,
    )
    .execute(&db.pool)
    .await
    .unwrap();
    let retained_history_insert_started = Instant::now();
    sqlx::query(
        r#"
        INSERT INTO job_targets (
            job_id, client_id, status, started_at, completed_at,
            dispatch_attempts
        )
        SELECT
            md5('system-dashboard-filler-job-' || value::text)::uuid,
            'system-dashboard-filler-client-' || (((value - 1) % 120) + 1)::text,
            CASE value % 4
                WHEN 0 THEN 'control_timeout'
                WHEN 1 THEN 'agent_timeout'
                WHEN 2 THEN 'agent_lost'
                ELSE 'canceled'
            END,
            now() - interval '91 days',
            now() - interval '90 days',
            1
        FROM generate_series(1, 40000) AS value
        "#,
    )
    .execute(&db.pool)
    .await
    .unwrap();
    let retained_history_insert_elapsed = retained_history_insert_started.elapsed();
    let active_fleet_job_id = Uuid::parse_str("20000000-0000-4000-8000-000000000008").unwrap();
    sqlx::query(
        r#"
        INSERT INTO jobs (
            id, command_type, status, target_count, payload_hash,
            request_fingerprint
        ) VALUES ($1, 'shell_argv', 'running', 120,
                  'active-fleet-payload', 'active-fleet-request')
        "#,
    )
    .bind(active_fleet_job_id)
    .execute(&db.pool)
    .await
    .unwrap();
    let active_fleet_insert_started = Instant::now();
    sqlx::query(
        r#"
        INSERT INTO job_targets (
            job_id, client_id, status, started_at, dispatch_attempts,
            deadline_at
        )
        SELECT
            $1,
            'system-dashboard-filler-client-' || value::text,
            CASE value % 2 WHEN 0 THEN 'dispatching' ELSE 'running' END,
            now() - interval '1 hour',
            1,
            now() + interval '90 days'
        FROM generate_series(1, 120) AS value
        "#,
    )
    .bind(active_fleet_job_id)
    .execute(&db.pool)
    .await
    .unwrap();
    let active_fleet_insert_elapsed = active_fleet_insert_started.elapsed();
    eprintln!(
        "system-dashboard target owner receipts: 40000 rows/120 owners={retained_history_insert_elapsed:?}, 120 active owners={active_fleet_insert_elapsed:?}"
    );
    sqlx::query("ANALYZE jobs, job_targets, system_dashboard_target_metrics")
        .execute(&db.pool)
        .await
        .unwrap();
    let explain_sql =
        format!("EXPLAIN (ANALYZE, BUFFERS, FORMAT JSON) {SYSTEM_DASHBOARD_SNAPSHOT_SQL}");
    let plan: Value = sqlx::query_scalar(&explain_sql)
        .fetch_one(&db.pool)
        .await
        .unwrap();
    let plan_root = &plan[0]["Plan"];
    assert!(
        !explain_relation_uses_sequential_scan(plan_root, "job_targets"),
        "system dashboard regressed to a historical target scan: {plan}"
    );
    assert!(
        !explain_relation_uses_sequential_scan(plan_root, "jobs"),
        "system dashboard regressed to a historical job scan: {plan}"
    );
    let plan_text = plan.to_string();
    assert!(
        explain_relation_examined_rows(plan_root, "job_targets") <= 130.0,
        "system dashboard exceeded its 128 active and two recent-terminal target rows: {plan}"
    );
    assert!(
        plan_text.contains("job_targets_recent_effective_terminal_idx"),
        "recent terminal count did not use its expression index: {plan}"
    );
    assert!(
        plan_text.contains("jobs_active_status_idx"),
        "active job counts did not use their partial index: {plan}"
    );
    assert!(
        plan_text.contains("\"Relation Name\":\"system_dashboard_target_metrics\""),
        "target metrics did not read the compact per-client projection: {plan}"
    );
    assert_eq!(
        sqlx::query_scalar::<_, i64>("SELECT count(*) FROM system_dashboard_target_metrics")
            .fetch_one(&db.pool)
            .await
            .unwrap(),
        126
    );
    assert_system_dashboard_target_projection_matches_exact(&db).await;
    db.cleanup().await;
}

struct PgReliabilityTestDb {
    repo: Repository,
    pool: PgPool,
    admin_pool: PgPool,
    db_name: String,
}

#[tokio::test]
async fn postgres_runtime_config_override_cas_is_atomic_and_supports_reset() {
    let Some(db) = PgReliabilityTestDb::maybe_new().await else {
        return;
    };
    for client_id in ["runtime-cas-a", "runtime-cas-b"] {
        insert_client(&db.pool, client_id, None).await;
    }
    let operator = postgres_network_operator(&db.repo).await;
    let absent_revision = runtime_config_override_revision(None);
    db.repo
        .replace_runtime_config_overrides_cas(
            &[
                RuntimeConfigOverrideReplacement {
                    client_id: "runtime-cas-a".to_string(),
                    expected_revision: absent_revision.clone(),
                    toml: Some("telemetry_interval_secs = 41\n".to_string()),
                },
                RuntimeConfigOverrideReplacement {
                    client_id: "runtime-cas-b".to_string(),
                    expected_revision: absent_revision.clone(),
                    toml: Some("telemetry_interval_secs = 42\n".to_string()),
                },
            ],
            "postgres-cas-seed",
            &operator,
        )
        .await
        .unwrap();
    let current = db.repo.list_runtime_config_overrides(None).await.unwrap();
    let current_a = current
        .iter()
        .find(|record| record.client_id == "runtime-cas-a")
        .unwrap();
    let current_b = current
        .iter()
        .find(|record| record.client_id == "runtime-cas-b")
        .unwrap();
    let revision_a = runtime_config_override_revision(Some(current_a));
    let revision_b = runtime_config_override_revision(Some(current_b));
    let retry_pool = PgPoolOptions::new()
        .max_connections(2)
        .connect_with((*db.pool.connect_options()).clone())
        .await
        .unwrap();
    let retry_repo = Repository::Postgres(retry_pool.clone());

    let stale = db
        .repo
        .replace_runtime_config_overrides_cas(
            &[
                RuntimeConfigOverrideReplacement {
                    client_id: "runtime-cas-a".to_string(),
                    expected_revision: revision_a.clone(),
                    toml: Some("telemetry_interval_secs = 51\n".to_string()),
                },
                RuntimeConfigOverrideReplacement {
                    client_id: "runtime-cas-b".to_string(),
                    expected_revision: absent_revision,
                    toml: Some("telemetry_interval_secs = 52\n".to_string()),
                },
            ],
            "postgres-cas-stale",
            &operator,
        )
        .await
        .unwrap_err();
    assert!(stale.to_string().contains("review_stale"));
    let unchanged = retry_repo
        .list_runtime_config_overrides(None)
        .await
        .unwrap();
    assert_eq!(
        unchanged
            .iter()
            .find(|record| record.client_id == "runtime-cas-a")
            .unwrap()
            .toml,
        "telemetry_interval_secs = 41\n"
    );

    retry_repo
        .replace_runtime_config_overrides_cas(
            &[
                RuntimeConfigOverrideReplacement {
                    client_id: "runtime-cas-a".to_string(),
                    expected_revision: revision_a,
                    toml: None,
                },
                RuntimeConfigOverrideReplacement {
                    client_id: "runtime-cas-b".to_string(),
                    expected_revision: revision_b,
                    toml: None,
                },
            ],
            "postgres-cas-reset",
            &operator,
        )
        .await
        .unwrap();
    assert!(db
        .repo
        .list_runtime_config_overrides(None)
        .await
        .unwrap()
        .is_empty());
    drop(retry_repo);
    retry_pool.close().await;
    db.cleanup().await;
}

#[tokio::test]
async fn postgres_runtime_config_guard_keeps_tunnel_source_stable_through_repreview_and_commit() {
    let Some(db) = PgReliabilityTestDb::maybe_new().await else {
        return;
    };
    for client_id in ["runtime-guard-pg-left", "runtime-guard-pg-right"] {
        insert_client(&db.pool, client_id, None).await;
    }
    db.repo
        .initialize_system_configuration_presets()
        .await
        .unwrap();
    let operator = postgres_network_operator(&db.repo).await;
    let mut input = postgres_alert_test_tunnel_input();
    input.name = "runtime-guard-pg".to_string();
    input.interface_name = "guardpg0".to_string();
    input.runtime_control = Default::default();
    input.left_mtu = vpsman_common::default_tunnel_mtu(TunnelKind::Gre);
    input.right_mtu = vpsman_common::default_tunnel_mtu(TunnelKind::Gre);
    input.left_client_id = "runtime-guard-pg-left".to_string();
    input.right_client_id = "runtime-guard-pg-right".to_string();
    input.address_pool_cidr = "10.92.0.0/30".to_string();
    input.ipv4_tunnel = Some(TunnelAddressPair {
        left: "10.92.0.0".to_string(),
        right: "10.92.0.1".to_string(),
        prefix_len: 31,
    });
    let planned = plan_tunnel(&input).unwrap();
    let persisted = db
        .repo
        .record_tunnel_plan(&input, &planned, true, &operator)
        .await
        .unwrap();
    let state = postgres_app_state(&db);
    let candidate = RuntimeConfigOverrideCandidate::Structured {
        value: serde_json::json!({"telemetry_interval_secs": 49}),
    };
    let reviewed = preview_runtime_config_override(&state, "runtime-guard-pg-left", &candidate)
        .await
        .unwrap();

    let guard = db
        .repo
        .lock_runtime_config_desired_state(&["runtime-guard-pg-left".to_string()])
        .await
        .unwrap();
    let writer_repo = db.repo.clone();
    let writer_input = input.clone();
    let writer_plan = planned.clone();
    let writer_operator = operator.clone();
    let (started_tx, started_rx) = oneshot::channel();
    let (finished_tx, mut finished_rx) = oneshot::channel();
    tokio::spawn(async move {
        let _ = started_tx.send(());
        let result = writer_repo
            .update_tunnel_plan(
                persisted.id,
                persisted.revision,
                &writer_input,
                &writer_plan,
                false,
                &writer_operator,
            )
            .await;
        let _ = finished_tx.send(result);
    });
    started_rx.await.unwrap();
    assert!(
        tokio::time::timeout(Duration::from_millis(150), &mut finished_rx)
            .await
            .is_err()
    );

    let locked_preview =
        preview_runtime_config_override(&state, "runtime-guard-pg-left", &candidate)
            .await
            .unwrap();
    assert_eq!(locked_preview.preview_hash, reviewed.preview_hash);
    db.repo
        .replace_runtime_config_overrides_cas_locked(
            guard,
            &[RuntimeConfigOverrideReplacement {
                client_id: "runtime-guard-pg-left".to_string(),
                expected_revision: locked_preview.override_revision,
                toml: locked_preview.canonical_toml,
            }],
            "postgres-guard-commit",
            &operator,
        )
        .await
        .unwrap();

    let updated = tokio::time::timeout(Duration::from_secs(2), finished_rx)
        .await
        .expect("tunnel writer should resume after override commit")
        .expect("tunnel writer result channel should stay open")
        .expect("tunnel writer should succeed");
    assert!(!updated.enabled);
    assert_eq!(
        db.repo
            .list_runtime_config_overrides(Some("runtime-guard-pg-left"))
            .await
            .unwrap()
            .len(),
        1
    );
    db.cleanup().await;
}

#[tokio::test]
async fn postgres_runtime_config_guard_uses_one_connection_and_no_fleet_lock() {
    let Some(db) = PgReliabilityTestDb::maybe_new().await else {
        return;
    };
    let single_pool = PgPoolOptions::new()
        .max_connections(1)
        .connect_with((*db.pool.connect_options()).clone())
        .await
        .unwrap();
    let single_repo = Repository::Postgres(single_pool.clone());
    insert_client(&db.pool, "runtime-guard-single", None).await;
    let guard = tokio::time::timeout(
        Duration::from_secs(1),
        single_repo.lock_runtime_config_desired_state(&["runtime-guard-single".to_string()]),
    )
    .await
    .expect("exact guard must not need a spare pool connection")
    .unwrap();
    drop(guard);

    drop(single_repo);
    single_pool.close().await;
    db.cleanup().await;
}

#[tokio::test]
async fn postgres_runtime_config_guards_for_distinct_clients_do_not_block_each_other() {
    let Some(db) = PgReliabilityTestDb::maybe_new().await else {
        return;
    };
    insert_client(&db.pool, "runtime-guard-a", None).await;
    insert_client(&db.pool, "runtime-guard-b", None).await;
    let first = db
        .repo
        .lock_runtime_config_desired_state(&["runtime-guard-a".to_string()])
        .await
        .unwrap();
    let second = tokio::time::timeout(
        Duration::from_secs(1),
        db.repo
            .lock_runtime_config_desired_state(&["runtime-guard-b".to_string()]),
    )
    .await
    .expect("unrelated VPS ownership must not wait")
    .unwrap();

    drop(second);
    drop(first);
    db.cleanup().await;
}

#[tokio::test]
async fn postgres_audit_schema_rejects_non_object_metadata() {
    let Some(db) = PgReliabilityTestDb::maybe_new().await else {
        return;
    };

    let error = sqlx::query(
        r#"
        INSERT INTO audit_logs (id, actor_id, action, target, command_hash, metadata)
        VALUES ($1, NULL, 'test.invalid_metadata', 'test:audit', NULL, $2)
        "#,
    )
    .bind(Uuid::new_v4())
    .bind(serde_json::json!(["result", "origin_kind", "component"]))
    .execute(&db.pool)
    .await
    .unwrap_err();

    assert!(error.to_string().contains("audit_logs_canonical_metadata"));
    db.cleanup().await;
}

#[tokio::test]
async fn postgres_tunnel_evidence_clear_is_scoped_counted_and_audited_atomically() {
    let Some(db) = PgReliabilityTestDb::maybe_new().await else {
        return;
    };
    for client_id in ["evidence-clear-left", "evidence-clear-right"] {
        insert_client(&db.pool, client_id, None).await;
    }
    let operator = postgres_network_operator(&db.repo).await;
    let mut selected_input = postgres_alert_test_tunnel_input();
    selected_input.name = "evidence-clear-selected".to_string();
    selected_input.interface_name = "tunclr0".to_string();
    selected_input.runtime_control = Default::default();
    selected_input.left_mtu = vpsman_common::default_tunnel_mtu(TunnelKind::Gre);
    selected_input.right_mtu = vpsman_common::default_tunnel_mtu(TunnelKind::Gre);
    selected_input.left_client_id = "evidence-clear-left".to_string();
    selected_input.right_client_id = "evidence-clear-right".to_string();
    selected_input.address_pool_cidr = "10.73.0.0/30".to_string();
    selected_input.ipv4_tunnel = Some(TunnelAddressPair {
        left: "10.73.0.0".to_string(),
        right: "10.73.0.1".to_string(),
        prefix_len: 31,
    });
    let selected = db
        .repo
        .record_tunnel_plan(
            &selected_input,
            &plan_tunnel(&selected_input).unwrap(),
            true,
            &operator,
        )
        .await
        .unwrap();
    let mut retained_input = selected_input.clone();
    retained_input.name = "evidence-clear-retained".to_string();
    retained_input.interface_name = "tunclr1".to_string();
    retained_input.address_pool_cidr = "10.73.0.4/30".to_string();
    retained_input.ipv4_tunnel = Some(TunnelAddressPair {
        left: "10.73.0.4".to_string(),
        right: "10.73.0.5".to_string(),
        prefix_len: 31,
    });
    let retained = db
        .repo
        .record_tunnel_plan(
            &retained_input,
            &plan_tunnel(&retained_input).unwrap(),
            true,
            &operator,
        )
        .await
        .unwrap();
    for kind in [
        "network_status",
        "tunnel_reachability",
        "network_speed_test",
    ] {
        sqlx::query(
            r#"
            INSERT INTO network_observations (
                id, client_id, kind, source, plan_id, topology_identity_hash,
                plan_name, interface_name, peer_client_id
            ) VALUES ($1, $2, $3, 'manual', $4, $5, $6, $7, $8)
            "#,
        )
        .bind(Uuid::new_v4())
        .bind(&selected.left_client_id)
        .bind(kind)
        .bind(selected.id)
        .bind(crate::repository_network_observations::topology_identity_hash_for_plan(&selected))
        .bind(&selected.name)
        .bind(&selected.plan.interface_name)
        .bind(&selected.right_client_id)
        .execute(&db.pool)
        .await
        .unwrap();
    }
    for (plan, target) in [(&selected, "10.73.0.1"), (&retained, "10.73.0.5")] {
        record_test_automatic_tunnel_reachability(
            &db.repo,
            &db.pool,
            &plan.left_client_id,
            &[TunnelReachabilityObservation {
                id: Uuid::new_v4(),
                source: TunnelReachabilitySource::Automatic,
                plan_id: plan.id,
                topology_identity_hash:
                    crate::repository_network_observations::topology_identity_hash_for_plan(plan),
                endpoint_side: TunnelEndpointSide::Left,
                peer_client_id: plan.right_client_id.clone(),
                interface_name: plan.plan.interface_name.clone(),
                address_family: TunnelAddressFamily::Ipv4,
                target: target.to_string(),
                measured_unix: crate::unix_now(),
                stale_after_secs: 180,
                transmitted: 3,
                received: 3,
                latency_min_ms: Some(1.0),
                latency_avg_ms: Some(2.0),
                latency_max_ms: Some(3.0),
                latency_mdev_ms: Some(0.1),
                packet_loss_ratio: 0.0,
                healthy: true,
                reason: None,
            }],
        )
        .await;
    }

    let results = db
        .repo
        .clear_tunnel_plan_evidence(&[(selected.id, selected.revision)], &operator)
        .await
        .unwrap();
    assert_eq!(results.len(), 1);
    assert_eq!(results[0].plan_id, selected.id);
    assert_eq!(results[0].name, selected.name);
    assert_eq!(results[0].reviewed_revision, selected.revision);
    assert_eq!(results[0].cleared_observation_count, 4);
    let counts = sqlx::query_as::<_, (Uuid, i64)>(
        r#"
        SELECT series.plan_id, count(*)::bigint
        FROM network_observations observation
        JOIN network_observation_series series
          ON series.id = observation.automatic_series_id
        WHERE observation.source = 'automatic'
        GROUP BY series.plan_id
        "#,
    )
    .fetch_all(&db.pool)
    .await
    .unwrap();
    assert_eq!(counts, vec![(retained.id, 1)]);
    let selected_automatic_shape: (i64, i64, i64) = sqlx::query_as(
        r#"
        SELECT
            (SELECT count(*)::bigint FROM network_observation_series WHERE plan_id = $1),
            (SELECT count(*)::bigint
             FROM network_observation_rollups rollup
             JOIN network_observation_series series ON series.id = rollup.series_id
             WHERE series.plan_id = $1),
            (SELECT count(*)::bigint
             FROM network_observation_latest latest
             JOIN network_observation_series series ON series.id = latest.series_id
             WHERE series.plan_id = $1)
        "#,
    )
    .bind(selected.id)
    .fetch_one(&db.pool)
    .await
    .unwrap();
    assert_eq!(selected_automatic_shape, (0, 0, 0));
    let retained_automatic_shape: (i64, i64, i64) = sqlx::query_as(
        r#"
        SELECT
            (SELECT count(*)::bigint FROM network_observation_series WHERE plan_id = $1),
            (SELECT count(*)::bigint
             FROM network_observation_rollups rollup
             JOIN network_observation_series series ON series.id = rollup.series_id
             WHERE series.plan_id = $1),
            (SELECT count(*)::bigint
             FROM network_observation_latest latest
             JOIN network_observation_series series ON series.id = latest.series_id
             WHERE series.plan_id = $1)
        "#,
    )
    .bind(retained.id)
    .fetch_one(&db.pool)
    .await
    .unwrap();
    assert_eq!(retained_automatic_shape, (1, 0, 1));
    let audit = sqlx::query(
        r#"
        SELECT target, metadata
        FROM audit_logs
        WHERE action = 'network.tunnel_plan_evidence_cleared'
        "#,
    )
    .fetch_one(&db.pool)
    .await
    .unwrap();
    assert_eq!(
        audit.try_get::<String, _>("target").unwrap(),
        format!("tunnel_plan:{}", selected.id)
    );
    let metadata = audit.try_get::<serde_json::Value, _>("metadata").unwrap();
    assert_eq!(metadata["cleared_observation_count"], 4);
    assert_eq!(metadata["plans"][0]["reviewed_revision"], selected.revision);
    assert_eq!(
        sqlx::query_scalar::<_, i64>("SELECT revision FROM tunnel_plans WHERE id = $1")
            .bind(selected.id)
            .fetch_one(&db.pool)
            .await
            .unwrap(),
        selected.revision
    );

    db.cleanup().await;
}

#[tokio::test]
async fn postgres_job_approval_decisions_preserve_the_frozen_dispatch_fence() {
    let Some(db) = PgReliabilityTestDb::maybe_new().await else {
        return;
    };
    let client_id = "approval-fence-client";
    insert_client(&db.pool, client_id, Some(Uuid::new_v4())).await;
    let (operator, headers) = postgres_operator_session(&db.repo, "approval-admin").await;
    let mut state = postgres_app_state(&db);
    state.gateway = GatewayDispatchClient::new_with_timeouts(
        Some("http://127.0.0.1:9".to_string()),
        Some("approval-test-token-at-least-32".to_string()),
        GatewayClientTimeouts::default(),
    )
    .with_test_privilege_auto_approve();

    let approved_job_id = Uuid::new_v4();
    let (status, Json(pending)) = crate::routes_jobs::create_job_approval(
        State(state.clone()),
        headers.clone(),
        Json(CreateJobApprovalRequest {
            approval_id: Some(Uuid::new_v4()),
            job: postgres_approval_job_request(approved_job_id, client_id),
            reason: Some("reviewed destructive restart".to_string()),
            risk: None,
        }),
    )
    .await
    .unwrap();
    assert_eq!(status, StatusCode::CREATED);
    assert_eq!(pending.status, "pending");
    assert_eq!(pending.risk, "destructive");
    assert_eq!(pending.target_client_ids, vec![client_id.to_string()]);
    let (_, frozen_request) = db
        .repo
        .get_job_approval_request(pending.id)
        .await
        .unwrap()
        .unwrap();
    assert!(frozen_request.privilege_assertion.is_none());
    assert_eq!(frozen_request.max_timeout_secs, Some(60));

    let Json(approved) = crate::routes_jobs::approve_job_approval(
        State(state.clone()),
        headers.clone(),
        axum::extract::Path(pending.id),
        Json(DecideJobApprovalRequest {
            confirmed: true,
            reason: Some("approved after review".to_string()),
        }),
    )
    .await
    .unwrap();
    assert_eq!(approved.approval.status, "approved");
    assert_eq!(
        approved.job.as_ref().map(|job| job.job_id),
        Some(approved_job_id)
    );
    assert!(db.repo.get_job(approved_job_id).await.unwrap().is_some());

    let Json(replayed) = crate::routes_jobs::approve_job_approval(
        State(state.clone()),
        headers.clone(),
        axum::extract::Path(pending.id),
        Json(DecideJobApprovalRequest {
            confirmed: true,
            reason: Some("must not replace the first decision".to_string()),
        }),
    )
    .await
    .unwrap();
    assert_eq!(replayed.approval.decision_by, approved.approval.decision_by);
    assert_eq!(
        replayed.approval.decision_reason,
        approved.approval.decision_reason
    );
    assert_eq!(
        sqlx::query_scalar::<_, i64>(
            "SELECT count(*) FROM audit_logs WHERE action='job.approval_approved' AND target=$1",
        )
        .bind(format!("job_approval:{}", pending.id))
        .fetch_one(&db.pool)
        .await
        .unwrap(),
        1
    );

    let rejected_job_id = Uuid::new_v4();
    let (_, Json(reject_pending)) = crate::routes_jobs::create_job_approval(
        State(state.clone()),
        headers.clone(),
        Json(CreateJobApprovalRequest {
            approval_id: None,
            job: postgres_approval_job_request(rejected_job_id, client_id),
            reason: None,
            risk: Some("maintenance".to_string()),
        }),
    )
    .await
    .unwrap();
    let missing_reason = crate::routes_jobs::reject_job_approval(
        State(state.clone()),
        headers.clone(),
        axum::extract::Path(reject_pending.id),
        Json(DecideJobApprovalRequest {
            confirmed: true,
            reason: Some("   ".to_string()),
        }),
    )
    .await
    .unwrap_err();
    assert_eq!(
        missing_reason.code,
        "job_approval_rejection_reason_required"
    );
    let Json(rejected) = crate::routes_jobs::reject_job_approval(
        State(state.clone()),
        headers.clone(),
        axum::extract::Path(reject_pending.id),
        Json(DecideJobApprovalRequest {
            confirmed: true,
            reason: Some("maintenance window closed".to_string()),
        }),
    )
    .await
    .unwrap();
    assert_eq!(rejected.approval.status, "rejected");
    assert!(rejected.job.is_none());
    assert!(db.repo.get_job(rejected_job_id).await.unwrap().is_none());
    let late_approval = crate::routes_jobs::approve_job_approval(
        State(state.clone()),
        headers.clone(),
        axum::extract::Path(reject_pending.id),
        Json(DecideJobApprovalRequest {
            confirmed: true,
            reason: Some("late approval".to_string()),
        }),
    )
    .await
    .unwrap_err();
    assert_eq!(late_approval.code, "job_approval_not_pending");

    let interrupted_job_id = Uuid::new_v4();
    let (_, Json(interrupted_approval)) = crate::routes_jobs::create_job_approval(
        State(state.clone()),
        headers.clone(),
        Json(CreateJobApprovalRequest {
            approval_id: Some(Uuid::new_v4()),
            job: postgres_approval_job_request(interrupted_job_id, client_id),
            reason: Some("simulate a committed decision before dispatch persistence".to_string()),
            risk: None,
        }),
    )
    .await
    .unwrap();
    db.repo
        .decide_job_approval(
            interrupted_approval.id,
            "approved",
            &operator,
            Some("decision committed before the job write"),
        )
        .await
        .unwrap();
    assert!(db.repo.get_job(interrupted_job_id).await.unwrap().is_none());
    let Json(recovered) = crate::routes_jobs::approve_job_approval(
        State(state.clone()),
        headers.clone(),
        axum::extract::Path(interrupted_approval.id),
        Json(DecideJobApprovalRequest {
            confirmed: true,
            reason: Some("retry after interruption".to_string()),
        }),
    )
    .await
    .unwrap();
    assert_eq!(
        recovered.job.as_ref().map(|job| job.job_id),
        Some(interrupted_job_id)
    );
    assert!(db.repo.get_job(interrupted_job_id).await.unwrap().is_some());
    assert_eq!(
        sqlx::query_scalar::<_, i64>(
            "SELECT count(*) FROM audit_logs WHERE action='job.approval_approved' AND target=$1",
        )
        .bind(format!("job_approval:{}", interrupted_approval.id))
        .fetch_one(&db.pool)
        .await
        .unwrap(),
        1
    );

    let binding_job_id = Uuid::new_v4();
    let (_, Json(binding_approval)) = crate::routes_jobs::create_job_approval(
        State(state),
        headers,
        Json(CreateJobApprovalRequest {
            approval_id: Some(Uuid::new_v4()),
            job: postgres_approval_job_request(binding_job_id, client_id),
            reason: Some("claim fence".to_string()),
            risk: None,
        }),
    )
    .await
    .unwrap();
    let (_, binding_request) = db
        .repo
        .get_job_approval_request(binding_approval.id)
        .await
        .unwrap()
        .unwrap();
    db.repo
        .record_dispatching_job_with_precompleted(
            binding_job_id,
            &binding_request,
            &binding_approval.payload_hash,
            "different-request-fingerprint",
            &operator,
            &binding_approval.target_client_ids,
            &[],
            Some(binding_approval.id),
        )
        .await
        .unwrap();
    db.repo
        .decide_job_approval(
            binding_approval.id,
            "approved",
            &operator,
            Some("only the frozen fingerprint is approved"),
        )
        .await
        .unwrap();
    assert!(db
        .repo
        .claim_due_job_targets(32, 30, 60)
        .await
        .unwrap()
        .iter()
        .all(|claim| claim.job_id != binding_job_id));

    db.cleanup().await;
}

#[tokio::test]
async fn postgres_update_release_registry_and_strict_dispatch_share_one_hash_authority() {
    let Some(db) = PgReliabilityTestDb::maybe_new().await else {
        return;
    };
    let client_id = "release-policy-client";
    let process_incarnation_id = Uuid::new_v4();
    insert_client(&db.pool, client_id, Some(process_incarnation_id)).await;
    let (operator, headers) = postgres_operator_session(&db.repo, "release-admin").await;
    let artifact_hash = "12".repeat(32);
    let rollback_hash = "34".repeat(32);
    let request = postgres_external_release_request(
        "vpsman-agent",
        "5.0.0",
        "STABLE",
        &artifact_hash,
        Some(&rollback_hash),
    );
    let mut state = postgres_app_state(&db);
    state.update_release_policy = UpdateReleasePolicy::new(vec!["stable".to_string()]).unwrap();
    crate::routes_update_releases::validate_agent_update_release_request(&state, &request).unwrap();
    let release = db
        .repo
        .record_agent_update_release(&request, &operator)
        .await
        .unwrap();
    assert_eq!(release.channel, "stable");
    assert_eq!(release.artifact_sha256_hex, artifact_hash);
    assert_eq!(
        release.rollback_artifact_sha256_hex.as_deref(),
        Some(rollback_hash.as_str())
    );
    assert!(db
        .repo
        .agent_update_release_exists_for_artifact(&artifact_hash.to_ascii_uppercase())
        .await
        .unwrap());
    assert!(db
        .repo
        .agent_update_release_exists_for_rollback_artifact(&rollback_hash)
        .await
        .unwrap());
    let serialized = serde_json::to_string(&release).unwrap();
    assert!(!serialized.contains("updates.example"));
    let audit_metadata: Value = sqlx::query_scalar(
        "SELECT metadata FROM audit_logs WHERE action='agent_update.release_recorded' AND target=$1",
    )
    .bind(format!("agent_update_release:{}", release.id))
    .fetch_one(&db.pool)
    .await
    .unwrap();
    assert_eq!(audit_metadata["artifact_url_stored"], false);
    assert_eq!(audit_metadata["rollback_artifact_url_stored"], false);
    assert!(!audit_metadata.to_string().contains("updates.example"));

    sqlx::query(
        r#"
        INSERT INTO agent_update_releases (
            id, actor_id, name, version, channel, status,
            artifact_sha256_hex, artifact_url_sha256_hex, created_at
        )
        SELECT
            ('00000000-0000-0000-0001-' || lpad(to_hex(ordinal), 12, '0'))::uuid,
            $1, 'unrelated-' || ordinal, '1.0.' || ordinal, 'stable',
            'published_external', repeat('ab', 32), repeat('cd', 32),
            now() + make_interval(secs => ordinal)
        FROM generate_series(1, 201) ordinal
        "#,
    )
    .bind(operator.operator.id)
    .execute(&db.pool)
    .await
    .unwrap();
    assert!(!db
        .repo
        .list_agent_update_releases(200)
        .await
        .unwrap()
        .iter()
        .any(|candidate| candidate.id == release.id));
    assert_eq!(
        db.repo
            .latest_agent_update_release("vpsman-agent", "StAbLe")
            .await
            .unwrap()
            .map(|candidate| candidate.id),
        Some(release.id)
    );

    let disallowed = postgres_external_release_request(
        "vpsman-agent",
        "5.0.1",
        "nightly",
        &"56".repeat(32),
        None,
    );
    assert_eq!(
        crate::routes_update_releases::validate_agent_update_release_request(&state, &disallowed)
            .unwrap_err()
            .code,
        "agent_update_release_channel_not_allowed"
    );
    let mut unconfirmed = postgres_external_release_request(
        "vpsman-agent",
        "5.0.2",
        "stable",
        &"9a".repeat(32),
        None,
    );
    unconfirmed.confirmed = false;
    assert_eq!(
        crate::routes_update_releases::validate_agent_update_release_request(&state, &unconfirmed)
            .unwrap_err()
            .code,
        "agent_update_release_confirmation_required"
    );

    state.require_registered_agent_updates = true;
    state.gateway = GatewayDispatchClient::new_with_timeouts(
        Some("http://127.0.0.1:9".to_string()),
        Some("release-policy-test-token-at-least-32".to_string()),
        GatewayClientTimeouts::default(),
    )
    .with_test_privilege_auto_approve();
    let missing_hash = "78".repeat(32);
    let missing_job = postgres_agent_update_job_request(client_id, &missing_hash);
    let (missing_status, Json(missing)) =
        crate::routes_jobs::create_job(State(state.clone()), headers.clone(), Json(missing_job))
            .await
            .unwrap();
    assert_eq!(missing_status, StatusCode::CONFLICT);
    assert_eq!(missing.status, "failed");
    assert_eq!(
        missing.error.as_deref(),
        Some("agent_update_release_missing")
    );

    let allowed_job = postgres_agent_update_job_request(client_id, &artifact_hash);
    let (allowed_status, Json(allowed)) =
        crate::routes_jobs::create_job(State(state.clone()), headers, Json(allowed_job))
            .await
            .unwrap();
    assert_eq!(allowed_status, StatusCode::ACCEPTED);
    assert_eq!(allowed.status, "queued");

    let verification_job_id = Uuid::new_v4();
    insert_job_target_with_operation(
        &db.pool,
        verification_job_id,
        client_id,
        JobCommand::AgentUpdateCheck {
            version_url: Some("https://updates.example/version.json".to_string()),
            activate: true,
            restart_agent: true,
        },
        "agent_update_check",
        None,
        "running",
        true,
        Some(process_incarnation_id),
        300,
        false,
    )
    .await;
    let gateway_session_id = Uuid::new_v4();
    start_test_gateway_session(
        &db.repo,
        "release-policy-gateway",
        client_id,
        gateway_session_id,
    )
    .await;
    let verification_event = |sha256_hex: &str| GatewayAgentUpdateVerificationIngest {
        gateway_id: "release-policy-gateway".to_string(),
        gateway_session_id,
        process_incarnation_id,
        client_id: client_id.to_string(),
        request: AgentUpdateVerificationRequest {
            job_id: verification_job_id,
            version_url: "https://updates.example/version.json".to_string(),
            artifact_url: "https://updates.example/vpsman-agent".to_string(),
            asset_name: "vpsman-agent-linux-x86_64-musl".to_string(),
            sha256_hex: sha256_hex.to_string(),
        },
    };
    let accepted = crate::routes_ingest::verify_agent_update_artifact(
        State(state.clone()),
        internal_gateway_headers(),
        Json(verification_event(&artifact_hash)),
    )
    .await
    .unwrap()
    .0;
    assert!(accepted.approved);
    assert_eq!(
        accepted.message,
        "registered agent update artifact accepted"
    );
    let missing = crate::routes_ingest::verify_agent_update_artifact(
        State(state.clone()),
        internal_gateway_headers(),
        Json(verification_event(&missing_hash)),
    )
    .await
    .unwrap()
    .0;
    assert!(!missing.approved);
    assert_eq!(missing.message, "registered agent update artifact missing");

    sqlx::query(
        "UPDATE job_targets SET status='completed', completed_at=now() WHERE job_id=$1 AND client_id=$2",
    )
    .bind(verification_job_id)
    .bind(client_id)
    .execute(&db.pool)
    .await
    .unwrap();
    let inactive_target = crate::routes_ingest::verify_agent_update_artifact(
        State(state),
        internal_gateway_headers(),
        Json(verification_event(&artifact_hash)),
    )
    .await
    .unwrap()
    .0;
    assert!(!inactive_target.approved);
    assert_eq!(
        inactive_target.message,
        "agent_update_check_target_not_active"
    );

    db.cleanup().await;
}

#[tokio::test]
async fn postgres_rollout_reconciler_isolates_missing_current_batch_assignment() {
    let Some(db) = PgReliabilityTestDb::maybe_new().await else {
        return;
    };
    let operator = postgres_network_operator(&db.repo).await;
    let rollout_policy = |canary: &str| JobRolloutPolicy {
        canary_client_ids: vec![canary.to_string()],
        batch_size: 1,
        max_failures: 0,
        pause_after_canary: false,
        batch_delay_secs: 0,
    };
    for client_id in [
        "broken-a",
        "broken-b",
        "broken-c",
        "healthy-a",
        "healthy-b",
        "healthy-c",
    ] {
        insert_client(&db.pool, client_id, Some(Uuid::new_v4())).await;
    }

    let malformed_job_id = Uuid::new_v4();
    let mut malformed_request = crate::tests::operation_job_request(
        JobCommand::AgentUpdateCheck {
            version_url: None,
            activate: false,
            restart_agent: false,
        },
        &["broken-a", "broken-b", "broken-c"],
    );
    malformed_request.rollout = Some(rollout_policy("broken-a"));
    db.repo
        .record_dispatching_job(
            malformed_job_id,
            &malformed_request,
            "malformed-command-hash",
            "malformed-request-fingerprint",
            &operator,
            &malformed_request.target_client_ids,
        )
        .await
        .unwrap();

    let healthy_job_id = Uuid::new_v4();
    let mut healthy_request = crate::tests::operation_job_request(
        JobCommand::AgentUpdateCheck {
            version_url: None,
            activate: false,
            restart_agent: false,
        },
        &["healthy-a", "healthy-b", "healthy-c"],
    );
    healthy_request.rollout = Some(rollout_policy("healthy-a"));
    db.repo
        .record_dispatching_job(
            healthy_job_id,
            &healthy_request,
            "healthy-command-hash",
            "healthy-request-fingerprint",
            &operator,
            &healthy_request.target_client_ids,
        )
        .await
        .unwrap();

    sqlx::query(
        "UPDATE job_rollouts SET current_batch = 1, updated_at = to_timestamp(1) WHERE job_id = $1",
    )
    .bind(malformed_job_id)
    .execute(&db.pool)
    .await
    .unwrap();
    sqlx::query("DELETE FROM job_rollout_targets WHERE job_id = $1 AND batch_index = 1")
        .bind(malformed_job_id)
        .execute(&db.pool)
        .await
        .unwrap();
    sqlx::query("UPDATE job_rollouts SET updated_at = to_timestamp(2) WHERE job_id = $1")
        .bind(healthy_job_id)
        .execute(&db.pool)
        .await
        .unwrap();
    sqlx::query(
        r#"
        UPDATE job_targets
        SET status = 'completed', exit_code = 0, completed_at = now()
        WHERE job_id = $1 AND client_id = 'healthy-a'
        "#,
    )
    .bind(healthy_job_id)
    .execute(&db.pool)
    .await
    .unwrap();

    assert_eq!(db.repo.reconcile_job_rollouts(1).await.unwrap(), 1);
    let malformed = sqlx::query_as::<_, (String, Option<String>)>(
        "SELECT status, pause_reason FROM job_rollouts WHERE job_id = $1",
    )
    .bind(malformed_job_id)
    .fetch_one(&db.pool)
    .await
    .unwrap();
    assert_eq!(
        malformed,
        (
            "paused".to_string(),
            Some("current_batch_assignment_missing".to_string())
        )
    );
    assert_eq!(
        sqlx::query_scalar::<_, i32>("SELECT current_batch FROM job_rollouts WHERE job_id = $1",)
            .bind(healthy_job_id)
            .fetch_one(&db.pool)
            .await
            .unwrap(),
        0
    );

    assert_eq!(db.repo.reconcile_job_rollouts(1).await.unwrap(), 1);
    let healthy = sqlx::query_as::<_, (String, i32, Option<String>)>(
        "SELECT status, current_batch, pause_reason FROM job_rollouts WHERE job_id = $1",
    )
    .bind(healthy_job_id)
    .fetch_one(&db.pool)
    .await
    .unwrap();
    assert_eq!(healthy, ("running".to_string(), 1, None));

    db.cleanup().await;
}

#[tokio::test]
async fn postgres_rollout_mutation_responses_are_the_locked_writer_state() {
    let Some(db) = PgReliabilityTestDb::maybe_new().await else {
        return;
    };
    let operator = postgres_network_operator(&db.repo).await;
    for client_id in ["rollout-response-a", "rollout-response-b"] {
        insert_client(&db.pool, client_id, Some(Uuid::new_v4())).await;
    }
    let job_id = Uuid::new_v4();
    let mut request = crate::tests::operation_job_request(
        JobCommand::AgentUpdateCheck {
            version_url: None,
            activate: false,
            restart_agent: false,
        },
        &["rollout-response-a", "rollout-response-b"],
    );
    request.rollout = Some(JobRolloutPolicy {
        canary_client_ids: vec!["rollout-response-a".to_string()],
        batch_size: 1,
        max_failures: 0,
        pause_after_canary: false,
        batch_delay_secs: 0,
    });
    db.repo
        .record_dispatching_job(
            job_id,
            &request,
            "rollout-response-command-hash",
            "rollout-response-fingerprint",
            &operator,
            &request.target_client_ids,
        )
        .await
        .unwrap();

    let paused = db
        .repo
        .pause_job_rollout(job_id, &operator, Some("response pause"))
        .await
        .unwrap();
    let persisted_paused = sqlx::query_as::<_, (String, Option<String>, String)>(
        "SELECT status, pause_reason, updated_at::text FROM job_rollouts WHERE job_id = $1",
    )
    .bind(job_id)
    .fetch_one(&db.pool)
    .await
    .unwrap();
    assert_eq!(paused.status, persisted_paused.0);
    assert_eq!(paused.pause_reason, persisted_paused.1);
    assert_eq!(paused.updated_at, persisted_paused.2);

    let resumed = db
        .repo
        .resume_job_rollout(job_id, &operator, Some("response resume"))
        .await
        .unwrap();
    let persisted_resumed = sqlx::query_as::<_, (String, Option<String>, String)>(
        "SELECT status, pause_reason, updated_at::text FROM job_rollouts WHERE job_id = $1",
    )
    .bind(job_id)
    .fetch_one(&db.pool)
    .await
    .unwrap();
    assert_eq!(resumed.status, persisted_resumed.0);
    assert_eq!(resumed.pause_reason, persisted_resumed.1);
    assert_eq!(resumed.updated_at, persisted_resumed.2);

    for iteration in 0..8 {
        db.repo
            .resume_job_rollout(job_id, &operator, Some("race reset"))
            .await
            .unwrap();
        let pause_reason = format!("race pause {iteration}");
        let (paused, resumed) = tokio::time::timeout(Duration::from_secs(10), async {
            tokio::join!(
                db.repo
                    .pause_job_rollout(job_id, &operator, Some(&pause_reason)),
                db.repo
                    .resume_job_rollout(job_id, &operator, Some("race resume")),
            )
        })
        .await
        .expect("opposite rollout mutations should not deadlock");
        let paused = paused.unwrap();
        let resumed = resumed.unwrap();
        assert_eq!(paused.status, "paused");
        assert_eq!(paused.pause_reason.as_deref(), Some(pause_reason.as_str()));
        assert_eq!(resumed.status, "running");
        assert!(resumed.pause_reason.is_none());
    }

    db.cleanup().await;
}

#[tokio::test]
async fn postgres_rollout_releases_reviewed_batches_and_cancel_fences_unreleased_targets() {
    let Some(db) = PgReliabilityTestDb::maybe_new().await else {
        return;
    };
    let operator = postgres_network_operator(&db.repo).await;
    let staged_clients = [
        "rollout-stage-a",
        "rollout-stage-b",
        "rollout-stage-c",
        "rollout-stage-d",
    ];
    for client_id in staged_clients {
        insert_client(&db.pool, client_id, Some(Uuid::new_v4())).await;
    }
    let job_id = Uuid::new_v4();
    let mut request = crate::tests::operation_job_request(
        JobCommand::AgentUpdateCheck {
            version_url: None,
            activate: false,
            restart_agent: false,
        },
        &staged_clients,
    );
    request.rollout = Some(JobRolloutPolicy {
        canary_client_ids: vec![staged_clients[0].to_string()],
        batch_size: 2,
        max_failures: 0,
        pause_after_canary: true,
        batch_delay_secs: 0,
    });
    db.repo
        .record_dispatching_job(
            job_id,
            &request,
            "rollout-stage-command-hash",
            "rollout-stage-request-fingerprint",
            &operator,
            &request.target_client_ids,
        )
        .await
        .unwrap();

    let canary = db.repo.claim_due_job_targets(32, 30, 0).await.unwrap();
    assert_eq!(
        canary
            .iter()
            .filter(|claim| claim.job_id == job_id)
            .map(|claim| claim.client_id.as_str())
            .collect::<Vec<_>>(),
        vec![staged_clients[0]]
    );
    set_postgres_rollout_target_terminal(
        &db.pool,
        job_id,
        staged_clients[0],
        TARGET_STATUS_COMPLETED,
    )
    .await;
    assert_eq!(db.repo.reconcile_job_rollouts(32).await.unwrap(), 1);
    let after_canary = db.repo.get_job_rollout(job_id).await.unwrap().unwrap();
    assert_eq!(after_canary.status, "paused");
    assert_eq!(after_canary.pause_reason.as_deref(), Some("canary_review"));
    assert_eq!(after_canary.current_batch, 1);
    assert!(db
        .repo
        .claim_due_job_targets(32, 30, 0)
        .await
        .unwrap()
        .iter()
        .all(|claim| claim.job_id != job_id));

    db.repo
        .resume_job_rollout(job_id, &operator, Some("canary reviewed"))
        .await
        .unwrap();
    let first_batch = db.repo.claim_due_job_targets(32, 30, 0).await.unwrap();
    assert_eq!(
        first_batch
            .iter()
            .filter(|claim| claim.job_id == job_id)
            .map(|claim| claim.client_id.as_str())
            .collect::<Vec<_>>(),
        vec![staged_clients[1], staged_clients[2]]
    );
    set_postgres_rollout_target_terminal(&db.pool, job_id, staged_clients[1], TARGET_STATUS_FAILED)
        .await;
    set_postgres_rollout_target_terminal(
        &db.pool,
        job_id,
        staged_clients[2],
        TARGET_STATUS_COMPLETED,
    )
    .await;
    assert_eq!(db.repo.reconcile_job_rollouts(32).await.unwrap(), 1);
    let failure_pause = db.repo.get_job_rollout(job_id).await.unwrap().unwrap();
    assert_eq!(failure_pause.status, "paused");
    assert_eq!(
        failure_pause.pause_reason.as_deref(),
        Some("failure_threshold")
    );
    assert_eq!(failure_pause.current_batch, 2);

    db.repo
        .resume_job_rollout(job_id, &operator, Some("failure reviewed"))
        .await
        .unwrap();
    let final_batch = db.repo.claim_due_job_targets(32, 30, 0).await.unwrap();
    assert_eq!(
        final_batch
            .iter()
            .filter(|claim| claim.job_id == job_id)
            .map(|claim| claim.client_id.as_str())
            .collect::<Vec<_>>(),
        vec![staged_clients[3]]
    );
    set_postgres_rollout_target_terminal(
        &db.pool,
        job_id,
        staged_clients[3],
        TARGET_STATUS_COMPLETED,
    )
    .await;
    assert_eq!(db.repo.reconcile_job_rollouts(32).await.unwrap(), 1);
    let completed = db.repo.get_job_rollout(job_id).await.unwrap().unwrap();
    assert_eq!(completed.status, "completed");
    assert!(completed.completed_at.is_some());

    let cancel_clients = ["rollout-cancel-a", "rollout-cancel-b", "rollout-cancel-c"];
    for client_id in cancel_clients {
        insert_client(&db.pool, client_id, Some(Uuid::new_v4())).await;
    }
    let cancel_job_id = Uuid::new_v4();
    let mut cancel_request = crate::tests::operation_job_request(
        JobCommand::AgentUpdateCheck {
            version_url: None,
            activate: false,
            restart_agent: false,
        },
        &cancel_clients,
    );
    cancel_request.rollout = Some(JobRolloutPolicy {
        canary_client_ids: vec![cancel_clients[0].to_string()],
        batch_size: 1,
        max_failures: 0,
        pause_after_canary: true,
        batch_delay_secs: 0,
    });
    db.repo
        .record_dispatching_job(
            cancel_job_id,
            &cancel_request,
            "rollout-cancel-command-hash",
            "rollout-cancel-request-fingerprint",
            &operator,
            &cancel_request.target_client_ids,
        )
        .await
        .unwrap();
    assert_eq!(
        db.repo
            .claim_due_job_targets(32, 30, 0)
            .await
            .unwrap()
            .into_iter()
            .filter(|claim| claim.job_id == cancel_job_id)
            .count(),
        1
    );
    let canceled = db
        .repo
        .request_job_cancel(cancel_job_id, &operator, Some("stop reviewed rollout"))
        .await
        .unwrap();
    assert_eq!(canceled.pending_canceled, 2);
    assert_eq!(canceled.cancel_targets, vec![cancel_clients[0].to_string()]);
    let aborted = db
        .repo
        .get_job_rollout(cancel_job_id)
        .await
        .unwrap()
        .unwrap();
    assert_eq!(aborted.status, "aborted");
    assert_eq!(
        aborted.pause_reason.as_deref(),
        Some("stop reviewed rollout")
    );
    assert!(db
        .repo
        .claim_due_job_targets(32, 30, 0)
        .await
        .unwrap()
        .iter()
        .all(|claim| claim.job_id != cancel_job_id));

    db.cleanup().await;
}

