#[tokio::test]
async fn postgres_canonical_traffic_history_combines_exact_imports_live_and_rollups() {
    let Some(db) = PgReliabilityTestDb::maybe_new().await else {
        return;
    };
    let client_id = "raw-traffic-import-history";
    insert_client(&db.pool, client_id, None).await;
    sqlx::query(
        r#"
        INSERT INTO vps_rule_values (client_id, key, value_raw, value_json)
        VALUES
            (
                $1,
                'traffic.selectors',
                'eth0,eth1',
                '{"mode":"exact","selectors":[
                    {"source":"host","interface":"eth0","direction":"total","canonical":"eth0"},
                    {"source":"host","interface":"eth1","direction":"total","canonical":"eth1"}
                ]}'::jsonb
            ),
            ($1, 'traffic.reset_day', '-1', '{"day":-1,"hour":0}'::jsonb)
        "#,
    )
    .bind(client_id)
    .execute(&db.pool)
    .await
    .unwrap();

    let hour_start = ((crate::unix_now() / 3_600) * 3_600).saturating_sub(7_200);
    let base = hour_start + 600;
    sqlx::query(
        r#"
        INSERT INTO traffic_counter_samples (
            client_id, source_kind, interface, observed_at,
            rx_bytes, tx_bytes, rx_counter_epoch, tx_counter_epoch,
            sample_source, inbound_promoted
        ) VALUES
            ($1, 'host', 'eth0', to_timestamp(($2 - 60)::double precision),
                0, 0, 0, 0, 'vnstat_import:test', FALSE),
            ($1, 'host', 'eth0', to_timestamp($2::double precision),
                10, 20, 0, 0, 'vnstat_import:test', FALSE),
            ($1, 'host', 'eth0', to_timestamp(($2 + 60)::double precision),
                25, 50, 0, 0, 'vnstat_import:test', FALSE),
            ($1, 'host', 'eth0', to_timestamp(($2 + 180)::double precision),
                500, 700, 1, 1, 'agent_networks', FALSE),
            ($1, 'host', 'eth0', to_timestamp(($2 + 240)::double precision),
                550, 760, 1, 1, 'agent_networks', FALSE),
            ($1, 'host', 'eth1', to_timestamp($2::double precision),
                0, 0, 0, 0, 'agent_networks', FALSE),
            ($1, 'host', 'eth1', to_timestamp(($2 + 60)::double precision),
                1000, 2000, 0, 0, 'vnstat_import:test', TRUE)
        "#,
    )
    .bind(client_id)
    .bind(base as i64)
    .execute(&db.pool)
    .await
    .unwrap();
    sqlx::query(
        r#"
        INSERT INTO traffic_counter_rollups (
            client_id, source_kind, interface, origin_kind,
            bucket_secs, bucket_start, rx_bytes, tx_bytes,
            rx_valid_count, tx_valid_count, any_valid_count,
            rx_reset_count, tx_reset_count, any_reset_count,
            first_observed_at, latest_observed_at
        ) VALUES (
            $1, 'host', 'eth1', 'vnstat_import', 3600,
            to_timestamp($2::double precision), 1000, 2000,
            1, 1, 1, 0, 0, 0,
            to_timestamp(($3 + 60)::double precision),
            to_timestamp(($3 + 60)::double precision)
        )
        "#,
    )
    .bind(client_id)
    .bind(hour_start as i64)
    .bind(base as i64)
    .execute(&db.pool)
    .await
    .unwrap();

    let history = db
        .repo
        .list_traffic_history(client_id, base, base + 300, 300)
        .await
        .unwrap();
    assert_eq!(
        history.iter().map(|point| point.sample_count).sum::<i32>(),
        4
    );
    assert_eq!(
        history
            .iter()
            .filter_map(|point| point.rx_bytes)
            .sum::<i64>(),
        1_075
    );
    assert_eq!(
        history
            .iter()
            .filter_map(|point| point.tx_bytes)
            .sum::<i64>(),
        2_110
    );
    assert!(history.iter().any(|point| point.bucket_secs == 300));
    assert!(history.iter().any(|point| point.bucket_secs == 3_600));

    db.cleanup().await;
}

#[tokio::test]
async fn postgres_system_metric_sampler_records_one_observation_per_metric_bucket() {
    let Some(db) = PgReliabilityTestDb::maybe_new().await else {
        return;
    };
    let metric = "test.system.latest.association";
    let bucket_start = (crate::unix_now() / 60 * 60).saturating_sub(120);

    let newest = [crate::repository_system_dashboard::SystemMetricSample {
        metric,
        value: 40.0,
    }];
    db.repo
        .record_system_metric_samples(bucket_start + 40, &newest)
        .await
        .unwrap();
    let older = [crate::repository_system_dashboard::SystemMetricSample {
        metric,
        value: 20.0,
    }];
    db.repo
        .record_system_metric_samples(bucket_start + 20, &older)
        .await
        .unwrap();

    let row: (i32, f64, f64, f64, i64) = sqlx::query_as(
        r#"
        SELECT sample_count, value_sum, max_value, latest_value,
               extract(epoch FROM latest_observed_at)::bigint
        FROM system_metric_rollups
        WHERE metric = $1 AND bucket_secs = 60
          AND bucket_start = to_timestamp($2::double precision)
        "#,
    )
    .bind(metric)
    .bind(bucket_start as f64)
    .fetch_one(&db.pool)
    .await
    .unwrap();
    assert_eq!(row, (1, 40.0, 40.0, 40.0, (bucket_start + 40) as i64));

    let equal_time = [crate::repository_system_dashboard::SystemMetricSample {
        metric,
        value: 44.0,
    }];
    db.repo
        .record_system_metric_samples(bucket_start + 40, &equal_time)
        .await
        .unwrap();
    let rows: Vec<(i32, i32, f64, f64, f64, i64)> = sqlx::query_as(
        r#"
        SELECT bucket_secs, sample_count, value_sum, max_value, latest_value,
               extract(epoch FROM latest_observed_at)::bigint
        FROM system_metric_rollups
        WHERE metric = $1
        ORDER BY bucket_secs
        "#,
    )
    .bind(metric)
    .fetch_all(&db.pool)
    .await
    .unwrap();
    assert_eq!(
        rows,
        vec![(60, 1, 40.0, 40.0, 40.0, (bucket_start + 40) as i64)]
    );

    let destination_start = bucket_start / 300 * 300;
    let due_events: (i64, i64, bool) = sqlx::query_as(
        r#"
        SELECT
            count(*)::bigint,
            count(DISTINCT event_id)::bigint,
            bool_and(
                source_bucket_secs = 60
                AND destination_bucket_secs = 300
                AND due_at = to_timestamp($1::double precision)
                    + interval '2 days 5 minutes'
            )
        FROM telemetry_history_due_events
        WHERE domain = 'system_metric_rollups'
          AND destination_start = to_timestamp($1::double precision)
        "#,
    )
    .bind(destination_start as f64)
    .fetch_one(&db.pool)
    .await
    .unwrap();
    assert_eq!(due_events, (1, 1, true));

    db.cleanup().await;
}

