#[tokio::test]
async fn filter_limit_regression_postgres_rules_and_policies() {
    let Some(db) = PgReliabilityTestDb::maybe_new().await else {
        return;
    };
    let target_client_id = "zzz-filter-target";
    insert_client(&db.pool, target_client_id, None).await;
    sqlx::query("UPDATE policy_groups SET enabled = FALSE")
        .execute(&db.pool)
        .await
        .unwrap();
    sqlx::query(
        r#"
        INSERT INTO clients (
            id,
            display_name,
            public_key,
            status,
            internal_build_number,
            capabilities
        )
        SELECT
            'aaa-filter-' || lpad(value::text, 3, '0'),
            'AAA Filter ' || lpad(value::text, 3, '0'),
            decode(lpad(to_hex(value), 64, '0'), 'hex'),
            'online',
            1,
            '{}'::jsonb
        FROM generate_series(1, 21) AS series(value)
        "#,
    )
    .execute(&db.pool)
    .await
    .unwrap();
    sqlx::query(
        r#"
        INSERT INTO vps_rule_values (client_id, key, value_raw, value_json)
        SELECT client.id, rule.key, rule.value_raw, rule.value_json
        FROM visible_clients client
        CROSS JOIN (
            VALUES
                ('traffic.reset_day', '1 00:00', '{"day":1,"hour":0}'::jsonb),
                ('traffic.quota.total', '1GB', '{"bytes":1000000000}'::jsonb),
                ('traffic.quota.rx', '1GB', '{"bytes":1000000000}'::jsonb),
                ('traffic.quota.tx', '1GB', '{"bytes":1000000000}'::jsonb),
                (
                    'traffic.selectors',
                    'eth0',
                    '{"mode":"exact","selectors":[{"source":"host","interface":"eth0","direction":"total","canonical":"eth0"}]}'::jsonb
                )
        ) AS rule(key, value_raw, value_json)
        WHERE client.id LIKE 'aaa-filter-%'
        "#,
    )
    .execute(&db.pool)
    .await
    .unwrap();
    sqlx::query(
        r#"
        INSERT INTO vps_rule_values (client_id, key, value_raw, value_json)
        VALUES
            ($1, 'traffic.reset_day', '1 00:00', '{"day":1,"hour":0}'::jsonb),
            ($1, 'traffic.quota.total', '1GB', '{"bytes":1000000000}'::jsonb),
            ($1, 'traffic.quota.rx', '1GB', '{"bytes":1000000000}'::jsonb),
            ($1, 'traffic.quota.tx', '1GB', '{"bytes":1000000000}'::jsonb),
            (
                $1,
                'traffic.selectors',
                'eth0',
                '{"mode":"exact","selectors":[{"source":"host","interface":"eth0","direction":"total","canonical":"eth0"}]}'::jsonb
            )
        "#,
    )
    .bind(target_client_id)
    .execute(&db.pool)
    .await
    .unwrap();

    let effective = db.repo.effective_vps_rules(target_client_id).await.unwrap();
    assert_eq!(effective.len(), 5);
    assert!(effective
        .iter()
        .all(|rule| rule.client_id == target_client_id));

    let client_filtered = db
        .repo
        .list_vps_rules(&VpsRuleQuery {
            limit: Some(2),
            client_id: Some(target_client_id.to_string()),
            selector_expression: None,
            key: None,
            state: None,
        })
        .await
        .unwrap();
    assert_eq!(client_filtered.len(), 2);
    assert!(client_filtered
        .iter()
        .all(|rule| rule.client_id == target_client_id));

    let selector_filtered = db
        .repo
        .list_vps_rules(&VpsRuleQuery {
            limit: Some(2),
            client_id: None,
            selector_expression: Some(format!("id:{target_client_id}")),
            key: None,
            state: Some("ok".to_string()),
        })
        .await
        .unwrap();
    assert_eq!(selector_filtered.len(), 2);
    assert!(selector_filtered
        .iter()
        .all(|rule| rule.client_id == target_client_id));

    let invalid_billing = db
        .repo
        .dry_run_vps_rules(&VpsRulesDryRunRequest {
            operation: "upsert".to_string(),
            selector_expression: format!("id:{target_client_id}"),
            values: BTreeMap::from([("billing.price".to_string(), "10 USD/week".to_string())]),
            keys: Vec::new(),
        })
        .await
        .unwrap();
    assert_eq!(invalid_billing.matched_vps_count, 1);
    assert_eq!(invalid_billing.changed_row_count, 0);
    assert_eq!(invalid_billing.invalid_row_count, 1);
    assert_eq!(invalid_billing.changes[0].action, "invalid");
    assert_eq!(
        invalid_billing.changes[0].validation_errors,
        ["billing_plan_period_invalid"]
    );
    assert_eq!(
        sqlx::query_scalar::<_, i64>(
            "SELECT count(*) FROM vps_rule_values WHERE client_id=$1 AND key='billing.price'",
        )
        .bind(target_client_id)
        .fetch_one(&db.pool)
        .await
        .unwrap(),
        0,
        "a dry-run validation result must never persist the rejected rule"
    );

    let matching_policy_id = Uuid::new_v4();
    sqlx::query(
        r#"
        INSERT INTO policy_groups (id, name, enabled, selector_expression)
        VALUES
            ($1, 'aaa-filter-policy-1', TRUE, 'id:not-present'),
            ($2, 'aaa-filter-policy-2', TRUE, 'id:not-present'),
            ($3, 'zzz-filter-policy', TRUE, $4)
        "#,
    )
    .bind(Uuid::new_v4())
    .bind(Uuid::new_v4())
    .bind(matching_policy_id)
    .bind(format!("id:{target_client_id}"))
    .execute(&db.pool)
    .await
    .unwrap();

    let client_policies = db
        .repo
        .list_fleet_alert_policies(1, Some(true), None, Some(target_client_id), true)
        .await
        .unwrap();
    assert_eq!(client_policies.len(), 1);
    assert_eq!(client_policies[0].id, matching_policy_id);

    let selector_policies = db
        .repo
        .list_fleet_alert_policies(
            1,
            Some(true),
            Some(&format!("id:{target_client_id}")),
            None,
            true,
        )
        .await
        .unwrap();
    assert_eq!(selector_policies.len(), 1);
    assert_eq!(selector_policies[0].id, matching_policy_id);

    let rule_selector_policy_id = Uuid::new_v4();
    sqlx::query(
        r#"
        INSERT INTO policy_groups (id, name, enabled, selector_expression)
        VALUES ($1, 'rule-selector-policy', TRUE, 'vps.rules:traffic.reset_day >= 1')
        "#,
    )
    .bind(rule_selector_policy_id)
    .execute(&db.pool)
    .await
    .unwrap();
    for error in [
        db.repo
            .list_fleet_alert_policies(20, None, None, None, false)
            .await
            .unwrap_err(),
        db.repo
            .get_fleet_alert_policy(rule_selector_policy_id, false)
            .await
            .unwrap_err(),
    ] {
        assert!(error
            .to_string()
            .contains("vps_rule_selector_scope_required"));
    }

    db.cleanup().await;
}

async fn query_monthly_traffic_usage(
    pool: &PgPool,
    client_ids: Vec<String>,
    cycle_start_unix: i64,
    now_unix: i64,
) -> Vec<(String, i64, i64, i64, i64, i64)> {
    let row_count = client_ids.len();
    sqlx::query(MONTHLY_TRAFFIC_COUNTER_USAGE_SQL)
        .bind(client_ids)
        .bind(vec!["host".to_string(); row_count])
        .bind(vec!["eth0".to_string(); row_count])
        .bind(vec![cycle_start_unix; row_count])
        .bind(now_unix)
        .fetch_all(pool)
        .await
        .unwrap()
        .into_iter()
        .map(|row| {
            (
                row.get("client_id"),
                row.get("cycle_rx"),
                row.get("cycle_tx"),
                row.get("latest_rx"),
                row.get("latest_tx"),
                row.get("rx_counter_epochs_seen"),
            )
        })
        .collect()
}

