#[tokio::test]
async fn postgres_vnstat_import_locks_client_before_traffic_advisory() {
    let Some(db) = PgReliabilityTestDb::maybe_new().await else {
        return;
    };
    let client_id = "traffic-import-client-lock-order";
    let live_unix = Utc::now().timestamp().div_euclid(60) * 60;
    let start_unix = live_unix - 600;
    insert_client(&db.pool, client_id, None).await;
    sqlx::query(
        r#"
        INSERT INTO traffic_counter_samples (
            client_id, source_kind, interface, observed_at,
            rx_bytes, tx_bytes, rx_counter_epoch, tx_counter_epoch, sample_source
        ) VALUES (
            $1, 'host', 'eth0', to_timestamp($2::double precision),
            10, 20, 0, 0, 'interface_counters'
        )
        "#,
    )
    .bind(client_id)
    .bind(live_unix as f64)
    .execute(&db.pool)
    .await
    .unwrap();
    let result = NetworkTrafficImportResult {
        r#type: "network_traffic_import_vnstat".to_string(),
        status: "collected".to_string(),
        requested_start_unix: u64::try_from(start_unix).unwrap(),
        collected_until_unix: u64::try_from(live_unix).unwrap(),
        interfaces: vec!["eth0".to_string()],
        sources: vec![NetworkTrafficImportSource {
            interface: "eth0".to_string(),
            database_created_unix: Some(u64::try_from(start_unix).unwrap()),
            retained_start_unix: u64::try_from(start_unix).unwrap(),
            source_updated_unix: Some(u64::try_from(live_unix).unwrap()),
        }],
        batch_count: 1,
        bucket_count: 1,
        message: String::new(),
    };
    let buckets = vec![NetworkTrafficImportBucket {
        interface: "eth0".to_string(),
        start_unix: u64::try_from(start_unix).unwrap(),
        duration_secs: 600,
        rx_bytes: 100,
        tx_bytes: 50,
    }];

    let mut row_first = db.pool.begin().await.unwrap();
    sqlx::query("SELECT id FROM clients WHERE id = $1 FOR UPDATE")
        .bind(client_id)
        .execute(&mut *row_first)
        .await
        .unwrap();
    let import_repo = db.repo.clone();
    let import_task = tokio::spawn(async move {
        import_repo
            .import_vnstat_traffic_history(
                Uuid::new_v4(),
                client_id,
                &["eth0".to_string()],
                u64::try_from(start_unix).unwrap(),
                &result,
                &buckets,
                u64::try_from(live_unix + 60).unwrap(),
            )
            .await
    });

    tokio::time::timeout(Duration::from_secs(5), async {
        loop {
            let waiting: bool = sqlx::query_scalar(
                r#"
                SELECT EXISTS (
                    SELECT 1
                    FROM pg_stat_activity
                    WHERE datname = current_database()
                      AND pid <> pg_backend_pid()
                      AND state = 'active'
                      AND wait_event_type = 'Lock'
                      AND query = 'SELECT id FROM clients WHERE id = $1 FOR UPDATE'
                )
                "#,
            )
            .fetch_one(&db.pool)
            .await
            .unwrap();
            if waiting {
                break;
            }
            tokio::time::sleep(Duration::from_millis(20)).await;
        }
    })
    .await
    .expect("vnStat import did not wait on the canonical client row first");

    tokio::time::timeout(
        Duration::from_secs(2),
        sqlx::query("SELECT pg_advisory_xact_lock(hashtextextended($1, 0))")
            .bind(format!("traffic-counters:{client_id}"))
            .execute(&mut *row_first),
    )
    .await
    .expect("vnStat import acquired the advisory before its client row")
    .unwrap();
    row_first.commit().await.unwrap();
    tokio::time::timeout(Duration::from_secs(10), import_task)
        .await
        .expect("ordered import did not resume after the row-first writer committed")
        .unwrap()
        .unwrap();

    db.cleanup().await;
}

async fn assert_traffic_rollup_summaries_match_base(pool: &PgPool, client_id: &str) {
    let mismatches: i64 = sqlx::query_scalar(
        r#"
        WITH expected_tiers AS (
            SELECT
                client_id,
                source_kind,
                interface,
                origin_kind,
                bucket_secs,
                min(bucket_start) AS first_bucket_start,
                max(bucket_start) AS latest_bucket_start,
                max(bucket_start) + make_interval(secs => bucket_secs)
                    AS last_bucket_end,
                sum(rx_bytes)::bigint AS rx_bytes,
                sum(tx_bytes)::bigint AS tx_bytes,
                sum(rx_reset_count)::bigint AS rx_reset_count,
                sum(tx_reset_count)::bigint AS tx_reset_count,
                count(*)::bigint AS rollup_row_count
            FROM traffic_counter_rollups
            WHERE client_id = $1
            GROUP BY
                client_id, source_kind, interface, origin_kind, bucket_secs
        ), tier_mismatches AS (
            SELECT 1
            FROM expected_tiers expected
            FULL JOIN traffic_counter_rollup_tier_summaries actual
              ON actual.client_id = expected.client_id
             AND actual.source_kind = expected.source_kind
             AND actual.interface = expected.interface
             AND actual.origin_kind = expected.origin_kind
             AND actual.bucket_secs = expected.bucket_secs
            WHERE COALESCE(expected.client_id, actual.client_id) = $1
              AND (
                    expected.client_id IS NULL
                    OR actual.client_id IS NULL
                    OR actual.first_bucket_start
                        IS DISTINCT FROM expected.first_bucket_start
                    OR actual.latest_bucket_start
                        IS DISTINCT FROM expected.latest_bucket_start
                    OR actual.last_bucket_end
                        IS DISTINCT FROM expected.last_bucket_end
                    OR actual.rx_bytes IS DISTINCT FROM expected.rx_bytes
                    OR actual.tx_bytes IS DISTINCT FROM expected.tx_bytes
                    OR actual.rx_reset_count
                        IS DISTINCT FROM expected.rx_reset_count
                    OR actual.tx_reset_count
                        IS DISTINCT FROM expected.tx_reset_count
                    OR actual.rollup_row_count
                        IS DISTINCT FROM expected.rollup_row_count
                    OR actual.materialized_revision IS DISTINCT FROM (
                        SELECT stream.materialized_revision
                        FROM traffic_counter_rollup_summary_streams stream
                        WHERE stream.client_id = actual.client_id
                          AND stream.source_kind = actual.source_kind
                          AND stream.interface = actual.interface
                    )
              )
        ), expected_streams AS (
            SELECT
                client_id,
                source_kind,
                interface,
                count(*)::bigint AS rollup_row_count,
                count(DISTINCT (origin_kind, bucket_secs))::integer AS tier_count
            FROM traffic_counter_rollups
            WHERE client_id = $1
            GROUP BY client_id, source_kind, interface
        ), stream_mismatches AS (
            SELECT 1
            FROM expected_streams expected
            FULL JOIN traffic_counter_rollup_summary_streams actual
              ON actual.client_id = expected.client_id
             AND actual.source_kind = expected.source_kind
             AND actual.interface = expected.interface
            WHERE COALESCE(expected.client_id, actual.client_id) = $1
              AND (
                    actual.client_id IS NULL
                    OR actual.source_revision <> actual.materialized_revision
                    OR actual.rollup_row_count
                        IS DISTINCT FROM COALESCE(expected.rollup_row_count, 0)
                    OR actual.tier_count
                        IS DISTINCT FROM COALESCE(expected.tier_count, 0)
              )
        )
        SELECT
            (SELECT count(*) FROM tier_mismatches)
            + (SELECT count(*) FROM stream_mismatches)
        "#,
    )
    .bind(client_id)
    .fetch_one(pool)
    .await
    .unwrap();
    assert_eq!(
        mismatches, 0,
        "traffic rollup summary diverged from base rows"
    );
}

async fn assert_traffic_hourly_totals_match_ledger(pool: &PgPool, client_id: &str) {
    let mismatches: i64 = sqlx::query_scalar(
        r#"
        WITH expected AS (
            SELECT
                client_id,
                source_kind,
                interface,
                coalesce(sum(rx_bytes), 0)::bigint AS rx_bytes,
                coalesce(sum(tx_bytes), 0)::bigint AS tx_bytes,
                coalesce(sum(rx_reset_count), 0)::bigint AS rx_reset_count,
                coalesce(sum(tx_reset_count), 0)::bigint AS tx_reset_count,
                count(*)::bigint AS row_count
            FROM traffic_counter_hourly_usage
            WHERE client_id = $1
            GROUP BY client_id, source_kind, interface
        )
        SELECT count(*)
        FROM traffic_counter_streams stream
        LEFT JOIN expected
          ON expected.client_id = stream.client_id
         AND expected.source_kind = stream.source_kind
         AND expected.interface = stream.interface
        WHERE stream.client_id = $1
          AND (
                stream.usage_rx_bytes <> coalesce(expected.rx_bytes, 0)
                OR stream.usage_tx_bytes <> coalesce(expected.tx_bytes, 0)
                OR stream.usage_rx_reset_count
                    <> coalesce(expected.rx_reset_count, 0)
                OR stream.usage_tx_reset_count
                    <> coalesce(expected.tx_reset_count, 0)
                OR stream.usage_row_count <> coalesce(expected.row_count, 0)
          )
        "#,
    )
    .bind(client_id)
    .fetch_one(pool)
    .await
    .unwrap();
    assert_eq!(
        mismatches, 0,
        "hourly cumulative totals diverged from ledger"
    );
}

#[tokio::test]
async fn postgres_steady_state_traffic_summaries_are_transactional_and_exact() {
    let Some(db) = PgReliabilityTestDb::maybe_new().await else {
        return;
    };
    let client_id = "traffic-summary-steady-state";
    insert_client(&db.pool, client_id, None).await;
    sqlx::query(
        r#"
        INSERT INTO traffic_counter_samples (
            client_id, source_kind, interface, observed_at,
            rx_bytes, tx_bytes, rx_counter_epoch, tx_counter_epoch,
            sample_source, inbound_promoted
        ) VALUES
            ($1, 'host', 'eth0', '2020-01-04 00:00:00+00',
                100, 200, 0, 0, 'agent_networks', TRUE),
            ($1, 'host', 'eth0', '2020-01-04 00:01:00+00',
                130, 250, 0, 0, 'agent_networks', FALSE),
            ($1, 'host', 'eth0', '2020-01-04 01:00:00+00',
                10, 20, 1, 1, 'agent_networks', FALSE)
        "#,
    )
    .bind(client_id)
    .execute(&db.pool)
    .await
    .unwrap();
    sqlx::query(
        r#"
        INSERT INTO traffic_counter_rollups (
            client_id, source_kind, interface, origin_kind,
            bucket_secs, bucket_start, rx_bytes, tx_bytes,
            rx_valid_count, tx_valid_count, any_valid_count,
            rx_reset_count, tx_reset_count, any_reset_count,
            first_observed_at, latest_observed_at
        ) VALUES
            ($1, 'host', 'eth0', 'live', 86400, '2020-01-01 00:00:00+00',
                100, 200, 1, 1, 1, 0, 0, 0,
                '2020-01-01 00:00:00+00', '2020-01-01 23:59:00+00'),
            ($1, 'host', 'eth0', 'live', 21600, '2020-01-02 00:00:00+00',
                30, 40, 1, 1, 1, 1, 0, 1,
                '2020-01-02 00:00:00+00', '2020-01-02 05:59:00+00'),
            ($1, 'host', 'eth0', 'vnstat_import', 3600,
                '2020-01-03 00:00:00+00',
                50, 60, 1, 1, 1, 0, 1, 1,
                '2020-01-03 00:00:00+00', '2020-01-03 00:59:00+00')
        "#,
    )
    .bind(client_id)
    .execute(&db.pool)
    .await
    .unwrap();
    assert_eq!(
        sqlx::query_as::<_, (bool, bool, bool, bool)>(
            r#"
            SELECT
                to_regclass('public.telemetry_projection_heads') IS NOT NULL,
                to_regclass('public.telemetry_dashboard_projection_heads') IS NOT NULL,
                to_regclass('public.telemetry_counter_facts') IS NULL,
                EXISTS (
                    SELECT 1
                    FROM pg_constraint
                    WHERE conrelid = 'public.webhook_events'::regclass
                      AND conname = 'webhook_events_no_full_telemetry_outbox'
                      AND convalidated
                )
            "#,
        )
        .fetch_one(&db.pool)
        .await
        .unwrap(),
        (true, true, true, true),
        "the baseline schema and scan-free write constraint must be installed"
    );
    assert_eq!(
        sqlx::query_as::<_, (bool, bool)>(
            r#"
            SELECT
                to_regclass('public.traffic_counter_samples_pkey') IS NOT NULL,
                to_regclass('public.traffic_counter_samples_lookup_idx') IS NULL
            "#,
        )
        .fetch_one(&db.pool)
        .await
        .unwrap(),
        (true, true),
        "the baseline must retain the primary-key lookup and omit its duplicate"
    );
    let installed_contract: (bool, bool, bool, bool, i64) = sqlx::query_as(
        r#"
        SELECT
            to_regclass('public.traffic_counter_rollup_summary_streams') IS NOT NULL,
            to_regclass('public.traffic_counter_rollup_tier_summaries') IS NOT NULL,
            to_regclass('public.traffic_counter_promoted_boundaries') IS NOT NULL,
            to_regclass('public.traffic_counter_samples_promoted_stream_idx') IS NULL,
            count(*) FILTER (
                WHERE tgname IN (
                    'traffic_counter_rollup_summaries_after_insert',
                    'traffic_counter_rollup_summaries_after_update',
                    'traffic_counter_rollup_summaries_after_delete'
                )
                  AND NOT tgisinternal
                  AND (tgtype & 1) = 0
            )::bigint
        FROM pg_trigger
        "#,
    )
    .fetch_one(&db.pool)
    .await
    .unwrap();
    assert_eq!(installed_contract, (true, true, true, true, 3));
    assert_eq!(
        sqlx::query_as::<_, (i64, bool, bool)>(
            r#"
            SELECT
                (
                    SELECT count(*)
                    FROM traffic_counter_promoted_boundaries boundary
                    WHERE boundary.client_id = stream.client_id
                      AND boundary.source_kind = stream.source_kind
                      AND boundary.interface = stream.interface
                )::bigint,
                stream.promoted_boundary_safe,
                stream.first_exact_observed_at =
                    '2020-01-04 00:01:00+00'::timestamptz
            FROM traffic_counter_streams stream
            WHERE stream.client_id = $1
              AND stream.source_kind = 'host'
              AND stream.interface = 'eth0'
            "#,
        )
        .bind(client_id)
        .fetch_one(&db.pool)
        .await
        .unwrap(),
        (1, true, true),
        "the steady-state trigger must register the sole-earliest promoted boundary exactly"
    );

    let hourly_totals: (i64, i64, i64, i64, i64, i64, i64, i64, i64, i64) = sqlx::query_as(
        r#"
            SELECT
                stream.usage_rx_bytes,
                stream.usage_tx_bytes,
                stream.usage_rx_reset_count,
                stream.usage_tx_reset_count,
                stream.usage_row_count,
                coalesce(sum(usage.rx_bytes), 0)::bigint,
                coalesce(sum(usage.tx_bytes), 0)::bigint,
                coalesce(sum(usage.rx_reset_count), 0)::bigint,
                coalesce(sum(usage.tx_reset_count), 0)::bigint,
                count(usage.bucket_start)::bigint
            FROM traffic_counter_streams stream
            LEFT JOIN traffic_counter_hourly_usage usage
              ON usage.client_id = stream.client_id
             AND usage.source_kind = stream.source_kind
             AND usage.interface = stream.interface
            WHERE stream.client_id = $1
              AND stream.source_kind = 'host'
              AND stream.interface = 'eth0'
            GROUP BY
                stream.usage_rx_bytes,
                stream.usage_tx_bytes,
                stream.usage_rx_reset_count,
                stream.usage_tx_reset_count,
                stream.usage_row_count
            "#,
    )
    .bind(client_id)
    .fetch_one(&db.pool)
    .await
    .unwrap();
    assert_eq!(
        (
            hourly_totals.0,
            hourly_totals.1,
            hourly_totals.2,
            hourly_totals.3,
            hourly_totals.4,
        ),
        (
            hourly_totals.5,
            hourly_totals.6,
            hourly_totals.7,
            hourly_totals.8,
            hourly_totals.9,
        ),
        "steady-state hourly cumulative totals diverged from the exact ledger"
    );
    assert_traffic_hourly_totals_match_ledger(&db.pool, client_id).await;

    // Prove statement-trigger ordering for every hourly-ledger DML shape.
    // UPDATE must subtract OLD before adding NEW; DELETE and INSERT must move
    // the cumulative totals exactly once and restore the raw-derived ledger.
    sqlx::query(
        r#"
        UPDATE traffic_counter_hourly_usage
        SET
            rx_bytes = rx_bytes + 7,
            tx_bytes = tx_bytes + 11,
            rx_reset_count = rx_reset_count + 1,
            tx_reset_count = tx_reset_count + 1
        WHERE client_id = $1
          AND source_kind = 'host'
          AND interface = 'eth0'
          AND bucket_start = '2020-01-04 00:00:00+00'
        "#,
    )
    .bind(client_id)
    .execute(&db.pool)
    .await
    .unwrap();
    assert_traffic_hourly_totals_match_ledger(&db.pool, client_id).await;
    sqlx::query(
        r#"
        UPDATE traffic_counter_hourly_usage
        SET
            rx_bytes = rx_bytes - 7,
            tx_bytes = tx_bytes - 11,
            rx_reset_count = rx_reset_count - 1,
            tx_reset_count = tx_reset_count - 1
        WHERE client_id = $1
          AND source_kind = 'host'
          AND interface = 'eth0'
          AND bucket_start = '2020-01-04 00:00:00+00'
        "#,
    )
    .bind(client_id)
    .execute(&db.pool)
    .await
    .unwrap();
    assert_traffic_hourly_totals_match_ledger(&db.pool, client_id).await;
    sqlx::query(
        r#"
        DELETE FROM traffic_counter_hourly_usage
        WHERE client_id = $1
          AND source_kind = 'host'
          AND interface = 'eth0'
          AND bucket_start = '2020-01-04 00:00:00+00'
        "#,
    )
    .bind(client_id)
    .execute(&db.pool)
    .await
    .unwrap();
    assert_traffic_hourly_totals_match_ledger(&db.pool, client_id).await;
    sqlx::query(
        r#"
        INSERT INTO traffic_counter_hourly_usage (
            client_id, source_kind, interface, bucket_start,
            rx_bytes, tx_bytes, rx_reset_count, tx_reset_count,
            sample_count, first_observed_at, latest_observed_at
        ) VALUES (
            $1, 'host', 'eth0', '2020-01-04 00:00:00+00',
            30, 50, 0, 0, 2,
            '2020-01-04 00:00:00+00', '2020-01-04 00:01:00+00'
        )
        "#,
    )
    .bind(client_id)
    .execute(&db.pool)
    .await
    .unwrap();
    assert_traffic_hourly_totals_match_ledger(&db.pool, client_id).await;
    assert_hourly_traffic_ledger_matches_raw(&db.pool, client_id).await;
    assert_traffic_rollup_summaries_match_base(&db.pool, client_id).await;

    // Mixing one healthy stream with seven new streams proves that the
    // name-based caller resolves the partitioning wrapper: a global dirty
    // branch would rewrite this unrelated historical healthy hour.
    sqlx::query(
        r#"
        UPDATE traffic_counter_hourly_usage
        SET updated_at = '2000-01-01 00:00:00+00'
        WHERE client_id = $1
          AND source_kind = 'host'
          AND interface = 'eth0'
          AND bucket_start = '2020-01-04 00:00:00+00'
        "#,
    )
    .bind(client_id)
    .execute(&db.pool)
    .await
    .unwrap();
    sqlx::query(
        r#"
        INSERT INTO traffic_counter_samples (
            client_id, source_kind, interface, observed_at,
            rx_bytes, tx_bytes, rx_counter_epoch, tx_counter_epoch, sample_source
        )
        SELECT
            $1,
            'host',
            format('eth%s', interface_number),
            '2020-01-05 00:00:00+00',
            1000 + interface_number,
            2000 + interface_number,
            1,
            1,
            'agent_networks'
        FROM generate_series(0, 7) interface_number
        "#,
    )
    .bind(client_id)
    .execute(&db.pool)
    .await
    .unwrap();
    assert_eq!(
        sqlx::query_scalar::<_, i64>(
            r#"
            SELECT count(*)
            FROM traffic_counter_streams
            WHERE client_id = $1
              AND source_kind = 'host'
              AND source_revision = materialized_revision
            "#,
        )
        .bind(client_id)
        .fetch_one(&db.pool)
        .await
        .unwrap(),
        8
    );
    assert_eq!(
        sqlx::query_scalar::<_, i64>(
            r#"
            SELECT count(*)
            FROM traffic_counter_hourly_usage
            WHERE client_id = $1
              AND source_kind = 'host'
              AND interface = 'eth0'
              AND bucket_start = '2020-01-04 00:00:00+00'
              AND updated_at = '2000-01-01 00:00:00+00'
            "#,
        )
        .bind(client_id)
        .fetch_one(&db.pool)
        .await
        .unwrap(),
        1,
        "the INSERT trigger bypassed the partition wrapper"
    );

    // One deliberately dirty stream in the eight-stream transition table must
    // reject the whole raw mutation atomically. Only the explicit repair owner
    // may rebuild that stream; healthy streams remain untouched throughout.
    sqlx::query(
        r#"
        UPDATE traffic_counter_streams
        SET source_revision = source_revision + 1
        WHERE client_id = $1
          AND source_kind = 'host'
          AND interface = 'eth1'
        "#,
    )
    .bind(client_id)
    .execute(&db.pool)
    .await
    .unwrap();
    let rejected = sqlx::query(
        r#"
        UPDATE traffic_counter_samples
        SET rx_bytes = rx_bytes + 1, tx_bytes = tx_bytes + 1
        WHERE client_id = $1
          AND source_kind = 'host'
          AND observed_at = '2020-01-05 00:00:00+00'
        "#,
    )
    .bind(client_id)
    .execute(&db.pool)
    .await
    .unwrap_err();
    assert_eq!(
        rejected
            .as_database_error()
            .and_then(|error| error.code())
            .as_deref(),
        Some("PZ029")
    );
    sqlx::query(
        r#"
        SELECT refresh_traffic_counter_hourly_usage(
            ARRAY[$1]::text[], ARRAY['host']::text[], ARRAY['eth1']::text[],
            ARRAY['2020-01-05 00:00:00+00'::timestamptz], TRUE
        )
        "#,
    )
    .bind(client_id)
    .execute(&db.pool)
    .await
    .unwrap();
    sqlx::query(
        r#"
        UPDATE traffic_counter_samples
        SET rx_bytes = rx_bytes + 1, tx_bytes = tx_bytes + 1
        WHERE client_id = $1
          AND source_kind = 'host'
          AND observed_at = '2020-01-05 00:00:00+00'
        "#,
    )
    .bind(client_id)
    .execute(&db.pool)
    .await
    .unwrap();
    assert_eq!(
        sqlx::query_scalar::<_, i64>(
            r#"
            SELECT count(*)
            FROM traffic_counter_hourly_usage
            WHERE client_id = $1
              AND source_kind = 'host'
              AND interface = 'eth0'
              AND bucket_start = '2020-01-04 00:00:00+00'
              AND updated_at = '2000-01-01 00:00:00+00'
            "#,
        )
        .bind(client_id)
        .fetch_one(&db.pool)
        .await
        .unwrap(),
        1,
        "the UPDATE trigger bypassed the partition wrapper"
    );
    assert_hourly_traffic_ledger_matches_raw(&db.pool, client_id).await;
    assert_traffic_hourly_totals_match_ledger(&db.pool, client_id).await;

    // A missing marker with retained hourly rows is damaged authority. An
    // ordinary mutation fails closed; the explicit repair seeds exact totals
    // before delete/rebuild, so cumulative DELETE cannot underflow from zero.
    sqlx::query(
        r#"
        DELETE FROM traffic_counter_streams
        WHERE client_id = $1
          AND source_kind = 'host'
          AND interface = 'eth0'
        "#,
    )
    .bind(client_id)
    .execute(&db.pool)
    .await
    .unwrap();
    assert!(
        sqlx::query_scalar::<_, i64>(
            r#"
            SELECT count(*)
            FROM traffic_counter_hourly_usage
            WHERE client_id = $1
              AND source_kind = 'host'
              AND interface = 'eth0'
            "#,
        )
        .bind(client_id)
        .fetch_one(&db.pool)
        .await
        .unwrap()
            > 0
    );
    let rejected = sqlx::query(
        r#"
        UPDATE traffic_counter_samples
        SET tx_bytes = tx_bytes
        WHERE client_id = $1
          AND source_kind = 'host'
          AND interface = 'eth0'
          AND observed_at = '2020-01-05 00:00:00+00'
        "#,
    )
    .bind(client_id)
    .execute(&db.pool)
    .await
    .unwrap_err();
    assert_eq!(
        rejected
            .as_database_error()
            .and_then(|error| error.code())
            .as_deref(),
        Some("PZ029")
    );
    sqlx::query(
        r#"
        SELECT refresh_traffic_counter_hourly_usage(
            ARRAY[$1]::text[],
            ARRAY['host']::text[],
            ARRAY['eth0']::text[],
            ARRAY['2020-01-05 00:00:00+00'::timestamptz],
            TRUE
        )
        "#,
    )
    .bind(client_id)
    .execute(&db.pool)
    .await
    .expect("explicit whole-stream refresh must repair a missing marker");
    assert_hourly_traffic_ledger_matches_raw(&db.pool, client_id).await;
    assert_traffic_hourly_totals_match_ledger(&db.pool, client_id).await;
    assert!(
        sqlx::query_scalar::<_, bool>(
            r#"
            SELECT
                stream.source_revision = stream.materialized_revision
                AND stream.sample_edge_revision = stream.materialized_revision
                AND stream.promoted_boundary_safe
                AND stream.first_unpromoted_observed_at IS NOT NULL
                AND stream.first_exact_observed_at IS NOT NULL
                AND stream.last_exact_observed_at =
                    stream.latest_sample_observed_at
                AND active.source_revision = active.materialized_revision
                AND active.rx_bytes = expected.rx_bytes
                AND active.tx_bytes = expected.tx_bytes
                AND active.rx_reset_count = expected.rx_reset_count
                AND active.tx_reset_count = expected.tx_reset_count
            FROM traffic_counter_streams stream
            JOIN traffic_counter_active_cycle_usage active
              USING (client_id, source_kind, interface)
            CROSS JOIN LATERAL traffic_counter_completed_hour_usage(
                active.client_id,
                active.source_kind,
                active.interface,
                active.cycle_start,
                active.completed_through
            ) expected
            WHERE stream.client_id = $1
              AND stream.source_kind = 'host'
              AND stream.interface = 'eth0'
            "#,
        )
        .bind(client_id)
        .fetch_one(&db.pool)
        .await
        .unwrap(),
        "explicit reconstruction must publish every independent fence and exact active value"
    );

    sqlx::query(
        r#"
        UPDATE traffic_counter_rollups
        SET rx_bytes = rx_bytes + 7, tx_bytes = tx_bytes + 11
        WHERE client_id = $1 AND origin_kind = 'live' AND bucket_secs = 21600
        "#,
    )
    .bind(client_id)
    .execute(&db.pool)
    .await
    .unwrap();
    assert_traffic_rollup_summaries_match_base(&db.pool, client_id).await;

    sqlx::query(
        "DELETE FROM traffic_counter_rollups WHERE client_id = $1 AND origin_kind = 'vnstat_import'",
    )
    .bind(client_id)
    .execute(&db.pool)
    .await
    .unwrap();
    assert_traffic_rollup_summaries_match_base(&db.pool, client_id).await;
    sqlx::query(
        r#"
        INSERT INTO traffic_counter_rollups (
            client_id, source_kind, interface, origin_kind,
            bucket_secs, bucket_start, rx_bytes, tx_bytes,
            rx_valid_count, tx_valid_count, any_valid_count,
            rx_reset_count, tx_reset_count, any_reset_count,
            first_observed_at, latest_observed_at
        ) VALUES (
            $1, 'host', 'eth0', 'vnstat_import', 3600,
            '2020-01-03 01:00:00+00', 70, 80,
            1, 1, 1, 1, 1, 1,
            '2020-01-03 01:00:00+00', '2020-01-03 01:59:00+00'
        )
        "#,
    )
    .bind(client_id)
    .execute(&db.pool)
    .await
    .unwrap();
    assert_traffic_rollup_summaries_match_base(&db.pool, client_id).await;

    sqlx::query(
        r#"
        DELETE FROM traffic_counter_rollups
        WHERE client_id = $1 AND origin_kind = 'live' AND bucket_secs = 86400
        "#,
    )
    .bind(client_id)
    .execute(&db.pool)
    .await
    .unwrap();
    assert_traffic_rollup_summaries_match_base(&db.pool, client_id).await;

    db.cleanup().await;
}

#[tokio::test]
async fn postgres_fresh_schema_has_operational_alert_lifecycle_invariants() {
    let Some(db) = PgReliabilityTestDb::maybe_new().await else {
        return;
    };

    assert_eq!(
        sqlx::query_as::<_, (bool, bool, bool)>(
            r#"
            SELECT
                to_regclass('public.operational_alert_episodes') IS NULL,
                to_regclass('public.alert_episodes') IS NOT NULL,
                to_regclass('public.operational_alert_lifecycle_meta') IS NULL
            "#,
        )
        .fetch_one(&db.pool)
        .await
        .unwrap(),
        (true, true, true)
    );
    let columns = sqlx::query_scalar::<_, String>(
        r#"
        SELECT table_name || '.' || column_name
        FROM information_schema.columns
        WHERE table_schema = 'public'
          AND (table_name, column_name) IN (
            ('clients', 'operational_alert_status_at'),
            ('clients', 'operational_alert_tunnel_boundary_at'),
            ('telemetry_tunnels', 'telemetry_topology_identity_hash'),
            ('telemetry_tunnels', 'telemetry_runtime_evidence_identity_hash'),
            ('tunnel_plans', 'operational_alert_runtime_boundary_at'),
            ('jobs', 'alert_terminal_at'),
            ('job_targets', 'capability_alert_at'),
            ('backup_requests', 'terminal_at')
          )
        ORDER BY table_name, column_name
        "#,
    )
    .fetch_all(&db.pool)
    .await
    .unwrap();
    assert_eq!(
        columns.len(),
        8,
        "all lifecycle evidence columns must exist"
    );

    for trigger in [
        "clients_operational_alert_boundaries_insert_trigger",
        "clients_operational_alert_boundaries_update_trigger",
        "gateway_sessions_operational_alert_boundary_trigger",
        "tunnel_plans_operational_alert_boundary_trigger",
    ] {
        assert!(
            sqlx::query_scalar::<_, bool>(
                "SELECT EXISTS (SELECT 1 FROM pg_trigger WHERE tgname = $1 AND NOT tgisinternal)",
            )
            .bind(trigger)
            .fetch_one(&db.pool)
            .await
            .unwrap(),
            "missing lifecycle provenance trigger {trigger}"
        );
    }

    for index in [
        "alert_episodes_identity_idx",
        "alert_episodes_one_current_idx",
        "alert_episodes_trigger_evidence_idx",
        "alert_episodes_last_evidence_idx",
        "alert_policy_evaluation_states_due_idx",
        "alert_lifecycle_events_pkey",
    ] {
        assert!(
            sqlx::query_scalar::<_, bool>("SELECT to_regclass($1) IS NOT NULL")
                .bind(index)
                .fetch_one(&db.pool)
                .await
                .unwrap(),
            "missing lifecycle index {index}"
        );
    }
    assert_eq!(
        sqlx::query_as::<_, (bool, bool)>(
            r#"
            SELECT
                to_regclass('public.operational_alert_episodes_one_current_idx') IS NULL,
                to_regclass('public.operational_alert_episodes_event_source_once_idx') IS NULL
            "#,
        )
        .fetch_one(&db.pool)
        .await
        .unwrap(),
        (true, true)
    );
    for constraint in [
        "alert_episodes_policy_provenance_check",
        "alert_episodes_rule_record_kind_check",
        "alert_episodes_lifecycle_check",
    ] {
        assert!(
            sqlx::query_scalar::<_, bool>(
                r#"
                SELECT EXISTS (
                    SELECT 1
                    FROM pg_constraint
                    WHERE conrelid = 'alert_episodes'::regclass
                      AND conname = $1
                )
                "#,
            )
            .bind(constraint)
            .fetch_one(&db.pool)
            .await
            .unwrap(),
            "missing unified lifecycle constraint {constraint}"
        );
    }

    let operator = postgres_network_operator(&db.repo).await;
    let invalid = sqlx::query(
        r#"
        INSERT INTO alert_episodes (
            id, public_id, producer_kind, natural_key, record_kind,
            trigger_generation, trigger_severity, trigger_category,
            severity, category, target_kind, target_id, title, detail,
            source_status, evidence, lifecycle_state, triggered_at,
            last_confirmed_at, resolved_at, resolution_reason,
            resolution_note, resolution_actor_id,
            policy_group_id, policy_rule_id, policy_rule_version,
            policy_rule_kind, policy_group_name, policy_rule_name,
            policy_rule_system_seed_key
        ) VALUES (
            $1, 'invalid-condition-resolution', 'agent.access', 'invalid', 'condition',
            1, 'critical', 'agent_status', 'critical', 'agent_status',
            'agent', 'invalid', 'invalid', 'invalid', 'offline', '{}'::jsonb,
            'resolved', now(), now(), now(), 'operator_resolved', 'invalid', $2,
            'c1000000-0000-4000-8000-000000000001',
            'd1000000-0000-4000-8000-000000000004', 1,
            'state', 'System operational evidence policies',
            'Agent access revoked', 'agent.access_revoked'
        )
        "#,
    )
    .bind(Uuid::new_v4())
    .bind(operator.operator.id)
    .execute(&db.pool)
    .await
    .unwrap_err();
    assert_eq!(
        invalid
            .as_database_error()
            .and_then(|database_error| database_error.constraint()),
        Some("alert_episodes_lifecycle_check"),
        "condition episodes cannot be operator-resolved"
    );

    db.cleanup().await;
}

#[tokio::test]
async fn postgres_gateway_session_lifecycle_keeps_the_newest_session_and_connection_identity() {
    let Some(db) = PgReliabilityTestDb::maybe_new().await else {
        return;
    };
    let client_id = "gateway-session-fence-client";
    let process_incarnation_id = Uuid::new_v4();
    insert_client(&db.pool, client_id, Some(process_incarnation_id)).await;
    sqlx::query("UPDATE clients SET status='offline' WHERE id=$1")
        .bind(client_id)
        .execute(&db.pool)
        .await
        .unwrap();
    let older = Uuid::new_v4();
    let newer = Uuid::new_v4();
    let event = |session_id, remote_ip: &str| GatewaySessionLifecycleIngest {
        gateway_id: "gateway-session-fence".to_string(),
        client_id: client_id.to_string(),
        session_id,
        noise_public_key_hex: Some("ab".repeat(32)),
        remote_ip: Some(remote_ip.to_string()),
        agent_version: Some("test".to_string()),
        reason: None,
    };
    db.repo
        .record_gateway_session_started(&event(older, "198.51.100.10"))
        .await
        .unwrap();
    db.repo
        .record_gateway_session_started(&event(newer, "2001:db8::20"))
        .await
        .unwrap();
    assert_eq!(
        sqlx::query_as::<_, (Uuid, String)>(
            "SELECT id,status FROM gateway_sessions WHERE client_id=$1 ORDER BY id",
        )
        .bind(client_id)
        .fetch_all(&db.pool)
        .await
        .unwrap()
        .into_iter()
        .collect::<std::collections::HashMap<_, _>>(),
        std::collections::HashMap::from([
            (older, "expired".to_string()),
            (newer, "active".to_string()),
        ])
    );
    assert!(db
        .repo
        .active_gateway_session_matches(
            "gateway-session-fence",
            client_id,
            newer,
            process_incarnation_id,
        )
        .await
        .unwrap());
    assert!(!db
        .repo
        .active_gateway_session_matches(
            "gateway-session-fence",
            client_id,
            older,
            process_incarnation_id,
        )
        .await
        .unwrap());
    assert!(!db
        .repo
        .active_gateway_session_matches("gateway-session-fence", client_id, newer, Uuid::new_v4(),)
        .await
        .unwrap());

    let mut newer_end = event(newer, "2001:db8::20");
    newer_end.reason = Some("connection closed".to_string());
    db.repo
        .record_gateway_session_ended(&newer_end)
        .await
        .unwrap();
    let mut delayed_older_end = event(older, "198.51.100.10");
    delayed_older_end.reason = Some("replaced".to_string());
    db.repo
        .record_gateway_session_ended(&delayed_older_end)
        .await
        .unwrap();
    assert_eq!(
        sqlx::query_as::<_, (String, Option<String>, Option<String>)>(
            "SELECT status,host(registration_ip),host(last_ip) FROM clients WHERE id=$1",
        )
        .bind(client_id)
        .fetch_one(&db.pool)
        .await
        .unwrap(),
        (
            "disconnected".to_string(),
            Some("198.51.100.10".to_string()),
            Some("2001:db8::20".to_string()),
        )
    );

    db.cleanup().await;
}

#[tokio::test]
async fn postgres_gateway_session_boundary_advances_only_for_real_session_transitions() {
    let Some(db) = PgReliabilityTestDb::maybe_new().await else {
        return;
    };
    let client_id = "gateway-alert-boundary";
    insert_client(&db.pool, client_id, None).await;
    sqlx::query(
        "UPDATE clients SET operational_alert_tunnel_boundary_at = '2020-01-01T00:00:00Z' WHERE id = $1",
    )
    .bind(client_id)
    .execute(&db.pool)
    .await
    .unwrap();
    let session_id = Uuid::new_v4();
    sqlx::query(
        r#"
        INSERT INTO gateway_sessions (id, gateway_id, client_id, status)
        VALUES ($1, 'gateway-a', $2, 'active')
        "#,
    )
    .bind(session_id)
    .bind(client_id)
    .execute(&db.pool)
    .await
    .unwrap();
    let first_boundary: String = sqlx::query_scalar(
        "SELECT operational_alert_tunnel_boundary_at::text FROM clients WHERE id = $1",
    )
    .bind(client_id)
    .fetch_one(&db.pool)
    .await
    .unwrap();
    assert_ne!(first_boundary, "2020-01-01 00:00:00+00");

    sqlx::query("UPDATE gateway_sessions SET status = 'active' WHERE id = $1")
        .bind(session_id)
        .execute(&db.pool)
        .await
        .unwrap();
    assert_eq!(
        sqlx::query_scalar::<_, String>(
            "SELECT operational_alert_tunnel_boundary_at::text FROM clients WHERE id = $1",
        )
        .bind(client_id)
        .fetch_one(&db.pool)
        .await
        .unwrap(),
        first_boundary,
        "an idempotent replay of the same active session must preserve the boundary"
    );

    sqlx::query("UPDATE gateway_sessions SET status = 'ended' WHERE id = $1")
        .bind(session_id)
        .execute(&db.pool)
        .await
        .unwrap();
    sqlx::query("UPDATE gateway_sessions SET status = 'active' WHERE id = $1")
        .bind(session_id)
        .execute(&db.pool)
        .await
        .unwrap();
    let reactivated_boundary: String = sqlx::query_scalar(
        "SELECT operational_alert_tunnel_boundary_at::text FROM clients WHERE id = $1",
    )
    .bind(client_id)
    .fetch_one(&db.pool)
    .await
    .unwrap();
    assert_ne!(reactivated_boundary, first_boundary);

    db.cleanup().await;
}

