async fn receive_job_finished(
    rx: &mut broadcast::Receiver<WsEvent>,
    job_id: Uuid,
) -> Option<String> {
    for _ in 0..6 {
        let Ok(Ok(event)) = tokio::time::timeout(Duration::from_secs(1), rx.recv()).await else {
            continue;
        };
        if let WsEvent::JobFinished {
            job_id: event_job_id,
            status,
        } = event
        {
            if event_job_id == job_id {
                return Some(status);
            }
        }
    }
    None
}

