#[tokio::test]
async fn postgres_bootstrap_rolls_back_when_success_evidence_cannot_be_recorded() {
    let Some(db) = PgReliabilityTestDb::maybe_new().await else {
        return;
    };
    install_rejected_audit_action_trigger(&db.pool).await;
    set_rejected_audit_action(&db.pool, "operator_auth.login_success").await;
    let request = BootstrapOperatorRequest {
        username: "admin".to_string(),
        password: "admin-password-123".to_string(),
    };
    assert!(db
        .repo
        .bootstrap_operator_with_auth_event(
            &request,
            "203.0.113.40",
            Some("bootstrap-atomicity-test"),
        )
        .await
        .is_err());
    let rolled_back = sqlx::query_as::<_, (i64, i64, i64)>(
        r#"
        SELECT (SELECT count(*) FROM operators),
               (SELECT count(*) FROM operator_sessions),
               (SELECT count(*) FROM audit_logs)
        "#,
    )
    .fetch_one(&db.pool)
    .await
    .unwrap();
    assert_eq!(rolled_back, (0, 0, 0));

    sqlx::query("DELETE FROM rejected_test_audit_actions")
        .execute(&db.pool)
        .await
        .unwrap();
    let auth = db
        .repo
        .bootstrap_operator_with_auth_event(
            &request,
            "203.0.113.40",
            Some("bootstrap-atomicity-test"),
        )
        .await
        .unwrap();
    let evidence = sqlx::query_as::<_, (Uuid, String, String, String)>(
        r#"
        SELECT actor_id,
               metadata->>'operator_session_id',
               metadata->>'remote_ip',
               metadata->>'user_agent'
        FROM audit_logs
        WHERE action = 'operator_auth.login_success'
        "#,
    )
    .fetch_one(&db.pool)
    .await
    .unwrap();
    assert_eq!(evidence.0, auth.operator.id);
    assert_eq!(evidence.1, auth.session_id.to_string());
    assert_eq!(evidence.2, "203.0.113.40");
    assert_eq!(evidence.3, "bootstrap-atomicity-test");
    assert_eq!(
        sqlx::query_scalar::<_, i64>("SELECT count(*) FROM operator_sessions")
            .fetch_one(&db.pool)
            .await
            .unwrap(),
        1
    );

    db.cleanup().await;
}

#[tokio::test]
async fn postgres_refresh_rotation_rolls_back_when_replacement_insert_fails() {
    let Some(db) = PgReliabilityTestDb::maybe_new().await else {
        return;
    };
    let auth = db
        .repo
        .bootstrap_operator(&BootstrapOperatorRequest {
            username: "refresh-atomicity-admin".to_string(),
            password: "admin-password-123".to_string(),
        })
        .await
        .unwrap();
    sqlx::query(
        r#"
        CREATE FUNCTION reject_test_operator_session_insert()
        RETURNS trigger
        LANGUAGE plpgsql
        AS $$
        BEGIN
            RAISE EXCEPTION 'forced operator session insertion failure';
        END;
        $$
        "#,
    )
    .execute(&db.pool)
    .await
    .unwrap();
    sqlx::query(
        r#"
        CREATE TRIGGER reject_test_operator_session_insert
        BEFORE INSERT ON operator_sessions
        FOR EACH ROW
        EXECUTE FUNCTION reject_test_operator_session_insert()
        "#,
    )
    .execute(&db.pool)
    .await
    .unwrap();

    let error = db
        .repo
        .refresh_operator_session(&auth.refresh_token)
        .await
        .unwrap_err();
    assert!(error
        .to_string()
        .contains("forced operator session insertion failure"));
    let rolled_back = sqlx::query_as::<_, (bool, i64)>(
        r#"
        SELECT
            COALESCE((
                SELECT revoked_at IS NULL
                FROM operator_sessions
                WHERE id = $1
            ), FALSE),
            (SELECT count(*) FROM operator_sessions)
        "#,
    )
    .bind(auth.session_id)
    .fetch_one(&db.pool)
    .await
    .unwrap();
    assert_eq!(rolled_back, (true, 1));

    sqlx::query("DROP TRIGGER reject_test_operator_session_insert ON operator_sessions")
        .execute(&db.pool)
        .await
        .unwrap();
    sqlx::query("DROP FUNCTION reject_test_operator_session_insert()")
        .execute(&db.pool)
        .await
        .unwrap();
    let replacement = db
        .repo
        .refresh_operator_session(&auth.refresh_token)
        .await
        .unwrap()
        .expect("the rolled-back refresh token should remain retryable");
    assert_ne!(replacement.session_id, auth.session_id);
    let rotated = sqlx::query_as::<_, (bool, bool, i64)>(
        r#"
        SELECT
            COALESCE((
                SELECT revoked_at IS NOT NULL
                FROM operator_sessions
                WHERE id = $1
            ), FALSE),
            COALESCE((
                SELECT revoked_at IS NULL
                FROM operator_sessions
                WHERE id = $2
            ), FALSE),
            (SELECT count(*) FROM operator_sessions)
        "#,
    )
    .bind(auth.session_id)
    .bind(replacement.session_id)
    .fetch_one(&db.pool)
    .await
    .unwrap();
    assert_eq!(rotated, (true, true, 2));
    assert_eq!(
        db.repo
            .authenticate_access_token(&replacement.access_token)
            .await
            .unwrap()
            .map(|context| context.operator.id),
        Some(auth.operator.id)
    );
    assert!(db
        .repo
        .refresh_operator_session(&auth.refresh_token)
        .await
        .unwrap()
        .is_none());

    db.cleanup().await;
}

#[tokio::test]
async fn postgres_refresh_rotation_precedes_operator_session_revocation_mutations() {
    async fn wait_for_ungranted_lock(pool: &PgPool, locktype: &str) {
        tokio::time::timeout(Duration::from_secs(10), async {
            loop {
                let waiting = sqlx::query_scalar::<_, bool>(
                    r#"
                    SELECT EXISTS (
                        SELECT 1
                        FROM pg_locks locks
                        JOIN pg_stat_activity activity ON activity.pid = locks.pid
                        WHERE activity.datname = current_database()
                          AND locks.locktype = $1
                          AND NOT locks.granted
                    )
                    "#,
                )
                .bind(locktype)
                .fetch_one(pool)
                .await
                .unwrap();
                if waiting {
                    break;
                }
                tokio::time::sleep(Duration::from_millis(10)).await;
            }
        })
        .await
        .unwrap_or_else(|_| panic!("timed out waiting for an ungranted {locktype} lock"));
    }

    #[derive(Clone, Copy)]
    enum RevokingMutation {
        PasswordReset,
        TotpClear,
        Disable,
    }

    let Some(db) = PgReliabilityTestDb::maybe_new().await else {
        return;
    };
    let auth = db
        .repo
        .bootstrap_operator(&BootstrapOperatorRequest {
            username: "refresh-order-admin".to_string(),
            password: "admin-password-123".to_string(),
        })
        .await
        .unwrap();
    let actor = AuthContext {
        operator: auth.operator.clone(),
        session_id: Some(auth.session_id),
    };
    let target = db
        .repo
        .create_operator(
            &CreateOperatorRequest {
                username: "refresh-order-target".to_string(),
                password: "target-password-123".to_string(),
                role: "viewer".to_string(),
                scopes: Vec::new(),
                session_refresh_ttl_secs: None,
                confirmed: true,
                admin_risk_acknowledged: false,
                privilege_assertion: None,
            },
            &actor,
        )
        .await
        .unwrap();

    let gate_key = ((Uuid::new_v4().as_u128() & i64::MAX as u128) as i64).max(1);
    let gate_function = format!(
        r#"
        CREATE FUNCTION gate_test_refresh_session_revoke()
        RETURNS trigger LANGUAGE plpgsql AS $$
        BEGIN
            IF OLD.revoked_at IS NULL AND NEW.revoked_at IS NOT NULL THEN
                PERFORM pg_advisory_xact_lock({gate_key});
            END IF;
            RETURN NEW;
        END;
        $$
        "#,
    );
    sqlx::query(&gate_function).execute(&db.pool).await.unwrap();
    sqlx::query(
        r#"
        CREATE TRIGGER gate_test_refresh_session_revoke
        BEFORE UPDATE ON operator_sessions
        FOR EACH ROW EXECUTE FUNCTION gate_test_refresh_session_revoke()
        "#,
    )
    .execute(&db.pool)
    .await
    .unwrap();

    for mutation in [
        RevokingMutation::PasswordReset,
        RevokingMutation::TotpClear,
        RevokingMutation::Disable,
    ] {
        let original = db.repo.issue_session(target.clone()).await.unwrap();
        let mut gate = db.pool.begin().await.unwrap();
        sqlx::query("SELECT pg_advisory_xact_lock($1)")
            .bind(gate_key)
            .execute(&mut *gate)
            .await
            .unwrap();

        let refresh_repo = db.repo.clone();
        let refresh_token = original.refresh_token.clone();
        let refresh_task =
            tokio::spawn(
                async move { refresh_repo.refresh_operator_session(&refresh_token).await },
            );
        wait_for_ungranted_lock(&db.pool, "advisory").await;

        let mutation_repo = db.repo.clone();
        let mutation_actor = actor.clone();
        let target_id = target.id;
        let mutation_task = match mutation {
            RevokingMutation::PasswordReset => tokio::spawn(async move {
                mutation_repo
                    .reset_operator_password(
                        target_id,
                        "replacement-target-password-123",
                        false,
                        &mutation_actor,
                    )
                    .await
                    .map(|operator| operator.is_some())
            }),
            RevokingMutation::TotpClear => tokio::spawn(async move {
                mutation_repo
                    .clear_operator_totps(&[target_id], false, &mutation_actor)
                    .await
                    .map(|outcomes| {
                        matches!(
                            outcomes.as_slice(),
                            [crate::repository_auth::AccessBatchMutationOutcome::Applied { .. }]
                        )
                    })
            }),
            RevokingMutation::Disable => tokio::spawn(async move {
                mutation_repo
                    .set_operator_statuses(&[target_id], "disabled", false, &mutation_actor)
                    .await
                    .map(|outcomes| {
                        matches!(
                            outcomes.as_slice(),
                            [crate::repository_auth::AccessBatchMutationOutcome::Applied { .. }]
                        )
                    })
            }),
        };
        wait_for_ungranted_lock(&db.pool, "transactionid").await;
        gate.commit().await.unwrap();

        let replacement = tokio::time::timeout(Duration::from_secs(10), refresh_task)
            .await
            .expect("refresh rotation should complete after the gate opens")
            .expect("refresh task should not panic")
            .unwrap()
            .expect("refresh should win the forced ordering");
        assert!(tokio::time::timeout(Duration::from_secs(10), mutation_task)
            .await
            .expect("operator mutation should complete after refresh")
            .expect("operator mutation task should not panic")
            .unwrap());
        assert!(
            sqlx::query_scalar::<_, bool>(
                "SELECT revoked_at IS NOT NULL FROM operator_sessions WHERE id = $1",
            )
            .bind(replacement.session_id)
            .fetch_one(&db.pool)
            .await
            .unwrap(),
            "the later operator mutation must revoke the refresh replacement"
        );
        assert_eq!(
            sqlx::query_scalar::<_, i64>(
                "SELECT count(*) FROM operator_sessions WHERE operator_id = $1 AND revoked_at IS NULL",
            )
            .bind(target.id)
            .fetch_one(&db.pool)
            .await
            .unwrap(),
            0
        );
    }

    sqlx::query("DROP TRIGGER gate_test_refresh_session_revoke ON operator_sessions")
        .execute(&db.pool)
        .await
        .unwrap();
    sqlx::query("DROP FUNCTION gate_test_refresh_session_revoke()")
        .execute(&db.pool)
        .await
        .unwrap();
    db.cleanup().await;
}

#[tokio::test]
async fn postgres_session_revoke_response_is_the_persisted_transaction_snapshot() {
    let Some(db) = PgReliabilityTestDb::maybe_new().await else {
        return;
    };
    let auth = db
        .repo
        .bootstrap_operator(&BootstrapOperatorRequest {
            username: "session-revoke-admin".to_string(),
            password: "admin-password-123".to_string(),
        })
        .await
        .unwrap();
    let target = db.repo.issue_session(auth.operator.clone()).await.unwrap();
    let actor = AuthContext {
        operator: auth.operator.clone(),
        session_id: Some(auth.session_id),
    };

    let mut outcomes = db
        .repo
        .revoke_operator_sessions(&[target.session_id], true, &actor)
        .await
        .unwrap();
    let crate::repository_auth::AccessBatchMutationOutcome::Applied {
        result: revoked, ..
    } = outcomes.pop().expect("target session outcome should exist")
    else {
        panic!("target session should exist")
    };
    let persisted =
        sqlx::query_as::<_, (Uuid, String, String, String, String, String, Option<String>)>(
            r#"
        SELECT
            s.operator_id,
            o.username,
            o.role,
            s.created_at::text,
            s.expires_at::text,
            s.refresh_expires_at::text,
            s.revoked_at::text
        FROM operator_sessions s
        JOIN operators o ON o.id = s.operator_id
        WHERE s.id = $1
        "#,
        )
        .bind(target.session_id)
        .fetch_one(&db.pool)
        .await
        .unwrap();
    assert_eq!(revoked.id, target.session_id);
    assert_eq!(revoked.operator_id, persisted.0);
    assert_eq!(revoked.operator_username, persisted.1);
    assert_eq!(revoked.operator_role, persisted.2);
    assert!(!revoked.current);
    assert_eq!(revoked.created_at, persisted.3);
    assert_eq!(revoked.expires_at, persisted.4);
    assert_eq!(revoked.refresh_expires_at, persisted.5);
    assert!(revoked.revoked);
    assert_eq!(revoked.revoked_at, persisted.6);

    db.cleanup().await;
}

#[tokio::test]
async fn postgres_operator_mutations_recheck_admin_risk_under_repository_locks() {
    let Some(db) = PgReliabilityTestDb::maybe_new().await else {
        return;
    };
    let auth = db
        .repo
        .bootstrap_operator(&BootstrapOperatorRequest {
            username: "admin-risk-lock-owner".to_string(),
            password: "admin-password-123".to_string(),
        })
        .await
        .unwrap();
    let actor = AuthContext {
        operator: auth.operator.clone(),
        session_id: Some(auth.session_id),
    };
    let target = db
        .repo
        .create_operator(
            &CreateOperatorRequest {
                username: "admin-risk-stale-snapshot".to_string(),
                password: "target-password-123".to_string(),
                role: "viewer".to_string(),
                scopes: Vec::new(),
                session_refresh_ttl_secs: None,
                confirmed: true,
                admin_risk_acknowledged: false,
                privilege_assertion: None,
            },
            &actor,
        )
        .await
        .unwrap();
    let target_session = db.repo.issue_session(target.clone()).await.unwrap();
    sqlx::query(
        r#"
        UPDATE operators
        SET role = 'admin',
            totp_enabled = true,
            totp_secret_ciphertext_hex = '00',
            totp_secret_nonce_hex = '000000000000000000000000',
            totp_secret_salt_hex = '00000000000000000000000000000000',
            totp_last_accepted_step = 1
        WHERE id = $1
        "#,
    )
    .bind(target.id)
    .execute(&db.pool)
    .await
    .unwrap();
    let password_hash_before: String =
        sqlx::query_scalar("SELECT password_hash FROM operators WHERE id = $1")
            .bind(target.id)
            .fetch_one(&db.pool)
            .await
            .unwrap();

    let update_error = db
        .repo
        .update_operator(
            target.id,
            &UpdateOperatorRequest {
                role: "viewer".to_string(),
                scopes: Vec::new(),
                session_refresh_ttl_secs: target.session_refresh_ttl_secs,
                confirmed: true,
                admin_risk_acknowledged: false,
                privilege_assertion: None,
            },
            &actor,
        )
        .await
        .expect_err("a stale viewer preflight must not authorize changing a locked admin");
    assert_eq!(
        update_error.to_string(),
        "admin_risk_acknowledgement_required"
    );

    let password_error = db
        .repo
        .reset_operator_password(target.id, "replacement-password-123", false, &actor)
        .await
        .expect_err("a stale viewer preflight must not authorize resetting a locked admin");
    assert_eq!(
        password_error.to_string(),
        "admin_risk_acknowledgement_required"
    );
    let status_outcomes = db
        .repo
        .set_operator_statuses(&[target.id], "disabled", false, &actor)
        .await
        .unwrap();
    assert!(matches!(
        status_outcomes.as_slice(),
        [crate::repository_auth::AccessBatchMutationOutcome::Rejected {
            target_id,
            code: "admin_risk_acknowledgement_required"
        }] if *target_id == target.id
    ));
    let missing_operator = Uuid::new_v4();
    let totp_outcomes = db
        .repo
        .clear_operator_totps(&[missing_operator, target.id], false, &actor)
        .await
        .unwrap();
    assert_eq!(totp_outcomes.len(), 2);
    assert!(matches!(
        &totp_outcomes[0],
        crate::repository_auth::AccessBatchMutationOutcome::Rejected {
            target_id,
            code: "operator_not_found"
        } if *target_id == missing_operator
    ));
    assert!(matches!(
        &totp_outcomes[1],
        crate::repository_auth::AccessBatchMutationOutcome::Rejected {
            target_id,
            code: "admin_risk_acknowledgement_required"
        } if *target_id == target.id
    ));
    let session_outcomes = db
        .repo
        .revoke_operator_sessions(&[target_session.session_id], false, &actor)
        .await
        .unwrap();
    assert!(matches!(
        session_outcomes.as_slice(),
        [crate::repository_auth::AccessBatchMutationOutcome::Rejected {
            target_id,
            code: "admin_risk_acknowledgement_required"
        }] if *target_id == target_session.session_id
    ));

    let persisted = sqlx::query_as::<_, (String, String, String, bool)>(
        "SELECT role, status, password_hash, totp_enabled FROM operators WHERE id = $1",
    )
    .bind(target.id)
    .fetch_one(&db.pool)
    .await
    .unwrap();
    assert_eq!(persisted.0, "admin");
    assert_eq!(persisted.1, "active");
    assert_eq!(persisted.2, password_hash_before);
    assert!(persisted.3);
    assert!(!sqlx::query_scalar::<_, bool>(
        "SELECT revoked_at IS NOT NULL FROM operator_sessions WHERE id = $1",
    )
    .bind(target_session.session_id)
    .fetch_one(&db.pool)
    .await
    .unwrap());

    let requested_admin = db
        .repo
        .create_operator(
            &CreateOperatorRequest {
                username: "admin-risk-requested-role".to_string(),
                password: "target-password-123".to_string(),
                role: "viewer".to_string(),
                scopes: Vec::new(),
                session_refresh_ttl_secs: None,
                confirmed: true,
                admin_risk_acknowledged: false,
                privilege_assertion: None,
            },
            &actor,
        )
        .await
        .unwrap();
    let requested_error = db
        .repo
        .update_operator(
            requested_admin.id,
            &UpdateOperatorRequest {
                role: "admin".to_string(),
                scopes: Vec::new(),
                session_refresh_ttl_secs: requested_admin.session_refresh_ttl_secs,
                confirmed: true,
                admin_risk_acknowledged: false,
                privilege_assertion: None,
            },
            &actor,
        )
        .await
        .expect_err("the repository must enforce acknowledgement for a requested admin role");
    assert_eq!(
        requested_error.to_string(),
        "admin_risk_acknowledgement_required"
    );
    assert_eq!(
        sqlx::query_scalar::<_, String>("SELECT role FROM operators WHERE id = $1")
            .bind(requested_admin.id)
            .fetch_one(&db.pool)
            .await
            .unwrap(),
        "viewer"
    );

    sqlx::query(
        r#"
        UPDATE operators
        SET totp_enabled = true,
            totp_secret_ciphertext_hex = '00',
            totp_secret_nonce_hex = '000000000000000000000000',
            totp_secret_salt_hex = '00000000000000000000000000000000',
            totp_last_accepted_step = 1
        WHERE id = $1
        "#,
    )
    .bind(requested_admin.id)
    .execute(&db.pool)
    .await
    .unwrap();
    let mixed_outcomes = db
        .repo
        .clear_operator_totps(&[target.id, requested_admin.id], false, &actor)
        .await
        .unwrap();
    assert!(matches!(
        &mixed_outcomes[0],
        crate::repository_auth::AccessBatchMutationOutcome::Rejected {
            target_id,
            code: "admin_risk_acknowledgement_required"
        } if *target_id == target.id
    ));
    assert!(matches!(
        &mixed_outcomes[1],
        crate::repository_auth::AccessBatchMutationOutcome::Applied { target_id, .. }
            if *target_id == requested_admin.id
    ));

    db.cleanup().await;
}

#[tokio::test]
async fn postgres_access_batch_owners_preserve_order_partial_invariants_and_audits() {
    let Some(db) = PgReliabilityTestDb::maybe_new().await else {
        return;
    };
    let auth = db
        .repo
        .bootstrap_operator(&BootstrapOperatorRequest {
            username: "access-batch-admin".to_string(),
            password: "admin-password-123".to_string(),
        })
        .await
        .unwrap();
    let actor = AuthContext {
        operator: auth.operator.clone(),
        session_id: Some(auth.session_id),
    };
    let second_admin = db
        .repo
        .create_operator(
            &CreateOperatorRequest {
                username: "access-batch-second-admin".to_string(),
                password: "second-admin-password-123".to_string(),
                role: "admin".to_string(),
                scopes: Vec::new(),
                session_refresh_ttl_secs: None,
                confirmed: true,
                admin_risk_acknowledged: true,
                privilege_assertion: None,
            },
            &actor,
        )
        .await
        .unwrap();
    let viewer = db
        .repo
        .create_operator(
            &CreateOperatorRequest {
                username: "access-batch-viewer".to_string(),
                password: "viewer-password-123".to_string(),
                role: "viewer".to_string(),
                scopes: Vec::new(),
                session_refresh_ttl_secs: None,
                confirmed: true,
                admin_risk_acknowledged: false,
                privilege_assertion: None,
            },
            &actor,
        )
        .await
        .unwrap();
    let second_admin_session = db.repo.issue_session(second_admin.clone()).await.unwrap();
    let viewer_session = db.repo.issue_session(viewer.clone()).await.unwrap();
    let missing_operator = Uuid::new_v4();
    let requested_statuses = vec![
        missing_operator,
        viewer.id,
        second_admin.id,
        actor.operator.id,
    ];
    let status_outcomes = db
        .repo
        .set_operator_statuses(&requested_statuses, "disabled", true, &actor)
        .await
        .unwrap();
    assert_eq!(status_outcomes.len(), requested_statuses.len());
    for (outcome, expected) in status_outcomes.iter().zip(&requested_statuses) {
        let target_id = match outcome {
            crate::repository_auth::AccessBatchMutationOutcome::Applied { target_id, .. }
            | crate::repository_auth::AccessBatchMutationOutcome::Rejected { target_id, .. } => {
                target_id
            }
        };
        assert_eq!(*target_id, *expected);
    }
    assert!(matches!(
        status_outcomes[0],
        crate::repository_auth::AccessBatchMutationOutcome::Rejected {
            code: "operator_not_found",
            ..
        }
    ));
    assert!(matches!(
        status_outcomes[1],
        crate::repository_auth::AccessBatchMutationOutcome::Applied { .. }
    ));
    assert!(matches!(
        status_outcomes[2],
        crate::repository_auth::AccessBatchMutationOutcome::Applied { .. }
    ));
    assert!(matches!(
        status_outcomes[3],
        crate::repository_auth::AccessBatchMutationOutcome::Rejected {
            code: "last_active_admin_required",
            ..
        }
    ));
    assert_eq!(
        sqlx::query_scalar::<_, i64>(
            "SELECT count(*) FROM operators WHERE status='active' AND role='admin'",
        )
        .fetch_one(&db.pool)
        .await
        .unwrap(),
        1
    );
    for session_id in [second_admin_session.session_id, viewer_session.session_id] {
        assert!(sqlx::query_scalar::<_, bool>(
            "SELECT revoked_at IS NOT NULL FROM operator_sessions WHERE id=$1",
        )
        .bind(session_id)
        .fetch_one(&db.pool)
        .await
        .unwrap());
    }
    assert_eq!(
        sqlx::query_scalar::<_, i64>(
            "SELECT count(*) FROM audit_logs WHERE action='operator.disabled'",
        )
        .fetch_one(&db.pool)
        .await
        .unwrap(),
        2
    );

    let totp_target = db
        .repo
        .create_operator(
            &CreateOperatorRequest {
                username: "access-batch-totp".to_string(),
                password: "totp-target-password-123".to_string(),
                role: "viewer".to_string(),
                scopes: Vec::new(),
                session_refresh_ttl_secs: None,
                confirmed: true,
                admin_risk_acknowledged: false,
                privilege_assertion: None,
            },
            &actor,
        )
        .await
        .unwrap();
    sqlx::query(
        r#"
        UPDATE operators
        SET totp_enabled=true,
            totp_secret_ciphertext_hex='00',
            totp_secret_nonce_hex='000000000000000000000000',
            totp_secret_salt_hex='00000000000000000000000000000000',
            totp_last_accepted_step=1
        WHERE id=$1
        "#,
    )
    .bind(totp_target.id)
    .execute(&db.pool)
    .await
    .unwrap();
    let totp_session = db.repo.issue_session(totp_target.clone()).await.unwrap();
    let missing_totp = Uuid::new_v4();
    let totp_outcomes = db
        .repo
        .clear_operator_totps(&[missing_totp, totp_target.id], false, &actor)
        .await
        .unwrap();
    assert!(matches!(
        totp_outcomes[0],
        crate::repository_auth::AccessBatchMutationOutcome::Rejected {
            target_id,
            code: "operator_not_found"
        } if target_id == missing_totp
    ));
    assert!(matches!(
        totp_outcomes[1],
        crate::repository_auth::AccessBatchMutationOutcome::Applied {
            target_id,
            ..
        } if target_id == totp_target.id
    ));
    let totp_state = sqlx::query_as::<_, (bool, bool, bool)>(
        r#"
        SELECT
            totp_enabled,
            totp_secret_ciphertext_hex IS NULL,
            totp_last_accepted_step IS NULL
        FROM operators
        WHERE id=$1
        "#,
    )
    .bind(totp_target.id)
    .fetch_one(&db.pool)
    .await
    .unwrap();
    assert_eq!(totp_state, (false, true, true));
    assert!(sqlx::query_scalar::<_, bool>(
        "SELECT revoked_at IS NOT NULL FROM operator_sessions WHERE id=$1",
    )
    .bind(totp_session.session_id)
    .fetch_one(&db.pool)
    .await
    .unwrap());
    assert_eq!(
        sqlx::query_scalar::<_, i64>(
            "SELECT count(*) FROM audit_logs WHERE action='operator.totp_cleared' AND target=$1",
        )
        .bind(format!("operator:{}", totp_target.id))
        .fetch_one(&db.pool)
        .await
        .unwrap(),
        1
    );

    let other_session = db.repo.issue_session(actor.operator.clone()).await.unwrap();
    let missing_session = Uuid::new_v4();
    let session_ids = vec![missing_session, auth.session_id, other_session.session_id];
    let session_outcomes = db
        .repo
        .revoke_operator_sessions(&session_ids, true, &actor)
        .await
        .unwrap();
    assert!(matches!(
        session_outcomes[0],
        crate::repository_auth::AccessBatchMutationOutcome::Rejected {
            target_id,
            code: "operator_session_not_found"
        } if target_id == missing_session
    ));
    let crate::repository_auth::AccessBatchMutationOutcome::Applied {
        result: current_result,
        ..
    } = &session_outcomes[1]
    else {
        panic!("current session should retain the existing API revocation semantic")
    };
    assert!(current_result.current);
    let crate::repository_auth::AccessBatchMutationOutcome::Applied {
        result: other_result,
        ..
    } = &session_outcomes[2]
    else {
        panic!("non-current session should be revoked")
    };
    assert!(!other_result.current);
    assert_eq!(
        sqlx::query_scalar::<_, i64>(
            "SELECT count(*) FROM audit_logs WHERE action='operator_session.revoked' AND target=ANY($1)",
        )
        .bind(vec![
            format!("operator-session:{}", auth.session_id),
            format!("operator-session:{}", other_session.session_id),
        ])
        .fetch_one(&db.pool)
        .await
        .unwrap(),
        2
    );

    db.cleanup().await;
}

#[tokio::test]
async fn postgres_access_batch_routes_expose_ordered_contract_and_singleton_delegation() {
    let Some(db) = PgReliabilityTestDb::maybe_new().await else {
        return;
    };
    let auth = db
        .repo
        .bootstrap_operator(&BootstrapOperatorRequest {
            username: "access-route-admin".to_string(),
            password: "access-route-password-123".to_string(),
        })
        .await
        .unwrap();
    let actor = AuthContext {
        operator: auth.operator.clone(),
        session_id: Some(auth.session_id),
    };
    let target = db
        .repo
        .create_operator(
            &CreateOperatorRequest {
                username: "access-route-target".to_string(),
                password: "access-route-target-password-123".to_string(),
                role: "viewer".to_string(),
                scopes: Vec::new(),
                session_refresh_ttl_secs: None,
                confirmed: true,
                admin_risk_acknowledged: false,
                privilege_assertion: None,
            },
            &actor,
        )
        .await
        .unwrap();
    let missing = Uuid::new_v4();
    let mut state = postgres_app_state(&db);
    state.gateway = GatewayDispatchClient::default().with_test_privilege_auto_approve();
    let router = crate::routes::build_router(state);
    let assertion = || {
        json!({
            "nonce_hex": "00",
            "issued_unix": 0,
            "expires_unix": 0,
            "assertion_hex": "00"
        })
    };
    let request = |uri: &str, body: Value| {
        Request::builder()
            .method("POST")
            .uri(uri)
            .header(AUTHORIZATION, format!("Bearer {}", auth.access_token))
            .header(CONTENT_TYPE, "application/json")
            .body(Body::from(body.to_string()))
            .unwrap()
    };

    let status_response = router
        .clone()
        .oneshot(request(
            "/api/v1/operators/statuses",
            json!({
                "status": "disabled",
                "items": [
                    {"operator_id": missing, "privilege_assertion": assertion()},
                    {"operator_id": target.id, "privilege_assertion": assertion()}
                ],
                "confirmed": true,
                "admin_risk_acknowledged": false
            }),
        ))
        .await
        .unwrap();
    assert_eq!(status_response.status(), StatusCode::OK);
    let status_body: Value = serde_json::from_slice(
        &to_bytes(status_response.into_body(), usize::MAX)
            .await
            .unwrap(),
    )
    .unwrap();
    let outcomes = status_body["outcomes"].as_array().unwrap();
    assert_eq!(outcomes.len(), 2);
    assert_eq!(outcomes[0]["operator_id"], missing.to_string());
    assert_eq!(outcomes[0]["error_code"], "operator_not_found");
    assert_eq!(outcomes[1]["operator_id"], target.id.to_string());
    assert_eq!(outcomes[1]["status"], "succeeded");

    let singleton = router
        .clone()
        .oneshot(request(
            &format!("/api/v1/operators/{}/enable", target.id),
            json!({
                "confirmed": true,
                "admin_risk_acknowledged": false,
                "privilege_assertion": assertion()
            }),
        ))
        .await
        .unwrap();
    assert_eq!(singleton.status(), StatusCode::OK);
    let singleton: Value =
        serde_json::from_slice(&to_bytes(singleton.into_body(), usize::MAX).await.unwrap())
            .unwrap();
    assert_eq!(singleton["id"], target.id.to_string());
    assert_eq!(singleton["status"], "active");

    let totp_response = router
        .clone()
        .oneshot(request(
            "/api/v1/operators/totp-clears",
            json!({
                "items": [
                    {"operator_id": target.id, "privilege_assertion": assertion()}
                ],
                "confirmed": true,
                "admin_risk_acknowledged": false
            }),
        ))
        .await
        .unwrap();
    assert_eq!(totp_response.status(), StatusCode::OK);

    let target_session = db.repo.issue_session(target).await.unwrap();
    let session_response = router
        .oneshot(request(
            "/api/v1/operator-sessions/revocations",
            json!({
                "items": [
                    {"session_id": target_session.session_id, "privilege_assertion": assertion()}
                ],
                "confirmed": true,
                "admin_risk_acknowledged": false
            }),
        ))
        .await
        .unwrap();
    assert_eq!(session_response.status(), StatusCode::OK);
    let session_body: Value = serde_json::from_slice(
        &to_bytes(session_response.into_body(), usize::MAX)
            .await
            .unwrap(),
    )
    .unwrap();
    assert_eq!(
        session_body["outcomes"][0]["session_id"],
        target_session.session_id.to_string()
    );
    assert_eq!(session_body["outcomes"][0]["status"], "succeeded");

    db.cleanup().await;
}

#[tokio::test]
async fn postgres_login_rolls_back_session_and_totp_step_with_success_evidence() {
    let Some(db) = PgReliabilityTestDb::maybe_new().await else {
        return;
    };
    let password = "admin-password-123";
    let auth = db
        .repo
        .bootstrap_operator(&BootstrapOperatorRequest {
            username: "admin".to_string(),
            password: password.to_string(),
        })
        .await
        .unwrap();
    let throttle = crate::state::OperatorAuthThrottleConfig {
        username_failed_attempt_limit: 100,
        ip_failed_attempt_limit: 100,
        failed_attempt_window_secs: 300,
        lockout_secs: 60,
    };
    install_rejected_audit_action_trigger(&db.pool).await;
    set_rejected_audit_action(&db.pool, "operator_auth.login_success").await;
    let password_login = LoginRequest {
        username: "admin".to_string(),
        password: password.to_string(),
        totp_code: None,
    };
    assert!(db
        .repo
        .login_operator_with_throttle(
            &password_login,
            "203.0.113.41",
            Some("password-atomicity-test"),
            &throttle,
        )
        .await
        .is_err());
    assert_eq!(
        sqlx::query_scalar::<_, i64>("SELECT count(*) FROM operator_sessions")
            .fetch_one(&db.pool)
            .await
            .unwrap(),
        1
    );

    sqlx::query("DELETE FROM rejected_test_audit_actions")
        .execute(&db.pool)
        .await
        .unwrap();
    assert!(matches!(
        db.repo
            .login_operator_with_throttle(
                &password_login,
                "203.0.113.41",
                Some("password-atomicity-test"),
                &throttle,
            )
            .await
            .unwrap(),
        crate::repository_auth::OperatorLoginAttempt::Authenticated(_)
    ));

    let actor = AuthContext {
        operator: auth.operator,
        session_id: Some(auth.session_id),
    };
    let crate::model::TotpSetupOutcome::Created(_) =
        db.repo.setup_operator_totp(&actor, password).await.unwrap()
    else {
        panic!("expected TOTP setup");
    };
    let encrypted = db
        .repo
        .operator_by_username("admin")
        .await
        .unwrap()
        .unwrap()
        .encrypted_totp_secret()
        .unwrap();
    let secret = crate::auth_totp::decrypt_totp_secret(password, &encrypted).unwrap();
    let current_step = crate::unix_now() / crate::auth_totp::TOTP_PERIOD_SECS;
    let confirm_code = crate::auth_totp::totp_code_for_step(&secret, current_step);
    assert!(matches!(
        db.repo
            .confirm_operator_totp(&actor, password, &confirm_code)
            .await
            .unwrap(),
        crate::model::TotpUpdateOutcome::Updated(_)
    ));
    let login_step = current_step.saturating_add(1);
    let login_code = crate::auth_totp::totp_code_for_step(&secret, login_step);
    let totp_login = LoginRequest {
        username: "admin".to_string(),
        password: password.to_string(),
        totp_code: Some(login_code),
    };

    set_rejected_audit_action(&db.pool, "operator_auth.login_success").await;
    assert!(db
        .repo
        .login_operator_with_throttle(
            &totp_login,
            "203.0.113.42",
            Some("totp-atomicity-test"),
            &throttle,
        )
        .await
        .is_err());
    assert_eq!(
        sqlx::query_scalar::<_, i64>("SELECT count(*) FROM operator_sessions")
            .fetch_one(&db.pool)
            .await
            .unwrap(),
        2
    );
    assert_eq!(
        sqlx::query_scalar::<_, Option<i64>>(
            "SELECT totp_last_accepted_step FROM operators WHERE id = $1",
        )
        .bind(actor.operator.id)
        .fetch_one(&db.pool)
        .await
        .unwrap(),
        Some(current_step as i64)
    );

    sqlx::query("DELETE FROM rejected_test_audit_actions")
        .execute(&db.pool)
        .await
        .unwrap();
    assert!(matches!(
        db.repo
            .login_operator_with_throttle(
                &totp_login,
                "203.0.113.42",
                Some("totp-atomicity-test"),
                &throttle,
            )
            .await
            .unwrap(),
        crate::repository_auth::OperatorLoginAttempt::Authenticated(_)
    ));
    assert_eq!(
        sqlx::query_scalar::<_, i64>("SELECT count(*) FROM operator_sessions")
            .fetch_one(&db.pool)
            .await
            .unwrap(),
        3
    );
    assert_eq!(
        sqlx::query_scalar::<_, i64>(
            "SELECT count(*) FROM audit_logs WHERE action = 'operator_auth.login_success'",
        )
        .fetch_one(&db.pool)
        .await
        .unwrap(),
        2
    );

    db.cleanup().await;
}

#[tokio::test]
async fn postgres_password_login_rejects_concurrent_operator_credential_change() {
    let Some(db) = PgReliabilityTestDb::maybe_new().await else {
        return;
    };
    let password = "admin-password-123";
    let auth = db
        .repo
        .bootstrap_operator(&BootstrapOperatorRequest {
            username: "admin".to_string(),
            password: password.to_string(),
        })
        .await
        .unwrap();
    let replacement_hash = crate::hash_operator_password("replacement-password-456").unwrap();
    let mut credential_change = db.pool.begin().await.unwrap();
    sqlx::query("UPDATE operators SET password_hash = $2 WHERE id = $1")
        .bind(auth.operator.id)
        .bind(replacement_hash)
        .execute(&mut *credential_change)
        .await
        .unwrap();

    let login_repo = db.repo.clone();
    let login = tokio::spawn(async move {
        login_repo
            .login_operator_with_throttle(
                &LoginRequest {
                    username: "admin".to_string(),
                    password: password.to_string(),
                    totp_code: None,
                },
                "203.0.113.43",
                Some("credential-change-race-test"),
                &crate::state::OperatorAuthThrottleConfig {
                    username_failed_attempt_limit: 100,
                    ip_failed_attempt_limit: 100,
                    failed_attempt_window_secs: 300,
                    lockout_secs: 60,
                },
            )
            .await
    });

    tokio::time::timeout(Duration::from_secs(5), async {
        loop {
            let waiting: bool = sqlx::query_scalar(
                r#"
                SELECT EXISTS (
                    SELECT 1
                    FROM pg_stat_activity
                    WHERE datname = current_database()
                      AND pid <> pg_backend_pid()
                      AND wait_event_type = 'Lock'
                      AND query LIKE '%NOT totp_enabled%'
                )
                "#,
            )
            .fetch_one(&db.pool)
            .await
            .unwrap();
            if waiting {
                break;
            }
            tokio::time::sleep(Duration::from_millis(10)).await;
        }
    })
    .await
    .expect("password login did not reach the guarded operator row");

    credential_change.commit().await.unwrap();
    let attempt = tokio::time::timeout(Duration::from_secs(5), login)
        .await
        .expect("password login remained blocked")
        .unwrap()
        .unwrap();
    assert!(matches!(
        attempt,
        crate::repository_auth::OperatorLoginAttempt::InvalidCredentials
    ));
    assert_eq!(
        sqlx::query_scalar::<_, i64>("SELECT count(*) FROM operator_sessions")
            .fetch_one(&db.pool)
            .await
            .unwrap(),
        1
    );
    assert_eq!(
        sqlx::query_scalar::<_, String>(
            r#"
            SELECT metadata->>'reason'
            FROM audit_logs
            WHERE action = 'operator_auth.login_failure'
            ORDER BY created_at DESC
            LIMIT 1
            "#,
        )
        .fetch_one(&db.pool)
        .await
        .unwrap(),
        "operator_state_changed"
    );

    db.cleanup().await;
}

#[tokio::test]
async fn postgres_operator_login_throttle_persists_per_client_identity_bucket() {
    let Some(db) = PgReliabilityTestDb::maybe_new().await else {
        return;
    };
    let throttle = crate::state::OperatorAuthThrottleConfig {
        username_failed_attempt_limit: 2,
        ip_failed_attempt_limit: 100,
        failed_attempt_window_secs: 60,
        lockout_secs: 60,
    };
    let operator_id = db
        .repo
        .bootstrap_operator(&BootstrapOperatorRequest {
            username: "admin".to_string(),
            password: "admin-password-123".to_string(),
        })
        .await
        .unwrap()
        .operator
        .id;

    for _ in 0..2 {
        assert!(matches!(
            db.repo
                .login_operator_with_throttle(
                    &LoginRequest {
                        username: "admin".to_string(),
                        password: "wrong-password-123".to_string(),
                        totp_code: None,
                    },
                    "203.0.113.30",
                    None,
                    &throttle,
                )
                .await
                .unwrap(),
            crate::repository_auth::OperatorLoginAttempt::InvalidCredentials
        ));
    }
    let second_repo = Repository::Postgres(db.pool.clone());
    assert!(matches!(
        second_repo
            .login_operator_with_throttle(
                &LoginRequest {
                    username: "admin".to_string(),
                    password: "admin-password-123".to_string(),
                    totp_code: None,
                },
                "203.0.113.30",
                None,
                &throttle,
            )
            .await
            .unwrap(),
        crate::repository_auth::OperatorLoginAttempt::Throttled
    ));
    assert!(matches!(
        second_repo
            .login_operator_with_throttle(
                &LoginRequest {
                    username: "admin".to_string(),
                    password: "admin-password-123".to_string(),
                    totp_code: None,
                },
                "203.0.113.31",
                None,
                &throttle,
            )
            .await
            .unwrap(),
        crate::repository_auth::OperatorLoginAttempt::Authenticated(_)
    ));

    let row = sqlx::query(
        r#"
        SELECT failed_attempts,
               locked_until IS NOT NULL AND locked_until > now() AS locked,
               scope_key
        FROM operator_auth_throttle
        WHERE scope_kind = 'username_ip'
        "#,
    )
    .fetch_one(&db.pool)
    .await
    .unwrap();
    let failed_attempts: i64 = row.try_get("failed_attempts").unwrap();
    let locked: bool = row.try_get("locked").unwrap();
    let scope_key: String = row.try_get("scope_key").unwrap();
    assert_eq!(failed_attempts, 2);
    assert!(locked);
    assert_eq!(scope_key, "5:admin|203.0.113.30");
    let failed_login_audit = sqlx::query(
        r#"
        SELECT actor_id, target, metadata
        FROM audit_logs
        WHERE action = 'operator_auth.login_failure'
        ORDER BY created_at DESC, id DESC
        LIMIT 1
        "#,
    )
    .fetch_one(&db.pool)
    .await
    .unwrap();
    assert_eq!(
        failed_login_audit
            .try_get::<Option<Uuid>, _>("actor_id")
            .unwrap(),
        None
    );
    assert_eq!(
        failed_login_audit.try_get::<String, _>("target").unwrap(),
        "operator-login:admin"
    );
    let failed_login_metadata = failed_login_audit.try_get::<Value, _>("metadata").unwrap();
    assert_eq!(failed_login_metadata["attempted_username"], "admin");
    assert_eq!(failed_login_metadata["reason"], "bad_password");
    assert!(failed_login_metadata.get("operator_id").is_none());
    assert!(failed_login_metadata.get("operator_username").is_none());
    assert!(!failed_login_metadata
        .to_string()
        .contains(&operator_id.to_string()));
    let audit_count: i64 = sqlx::query_scalar("SELECT count(*) FROM audit_logs WHERE action = $1")
        .bind("operator_auth.lockout_created")
        .fetch_one(&db.pool)
        .await
        .unwrap();
    assert_eq!(audit_count, 1);
    db.cleanup().await;
}

#[tokio::test]
async fn postgres_repeated_totp_setup_reuses_pending_secret_without_enabling() {
    let Some(db) = PgReliabilityTestDb::maybe_new().await else {
        return;
    };
    let password = "admin-password-123";
    let auth = db
        .repo
        .bootstrap_operator(&BootstrapOperatorRequest {
            username: "admin".to_string(),
            password: password.to_string(),
        })
        .await
        .unwrap();
    let actor = AuthContext {
        operator: auth.operator,
        session_id: Some(Uuid::new_v4()),
    };
    let crate::model::TotpSetupOutcome::Created(first) =
        db.repo.setup_operator_totp(&actor, password).await.unwrap()
    else {
        panic!("expected initial TOTP setup");
    };
    let factor_before = sqlx::query_as::<
        _,
        (
            bool,
            Option<String>,
            Option<String>,
            Option<String>,
            Option<i64>,
        ),
    >(
        r#"
        SELECT totp_enabled,
               totp_secret_ciphertext_hex,
               totp_secret_nonce_hex,
               totp_secret_salt_hex,
               totp_last_accepted_step
        FROM operators
        WHERE id = $1
        "#,
    )
    .bind(actor.operator.id)
    .fetch_one(&db.pool)
    .await
    .unwrap();

    let crate::model::TotpSetupOutcome::Created(second) =
        db.repo.setup_operator_totp(&actor, password).await.unwrap()
    else {
        panic!("expected pending TOTP setup");
    };
    let factor_after = sqlx::query_as::<
        _,
        (
            bool,
            Option<String>,
            Option<String>,
            Option<String>,
            Option<i64>,
        ),
    >(
        r#"
        SELECT totp_enabled,
               totp_secret_ciphertext_hex,
               totp_secret_nonce_hex,
               totp_secret_salt_hex,
               totp_last_accepted_step
        FROM operators
        WHERE id = $1
        "#,
    )
    .bind(actor.operator.id)
    .fetch_one(&db.pool)
    .await
    .unwrap();

    assert_eq!(second.secret_base32, first.secret_base32);
    assert_eq!(second.otpauth_uri, first.otpauth_uri);
    assert_eq!(factor_after, factor_before);
    assert!(!factor_after.0);
    assert_eq!(factor_after.4, None);
    assert_eq!(
        sqlx::query_scalar::<_, i64>(
            "SELECT count(*) FROM audit_logs WHERE action = 'operator_totp.setup'",
        )
        .fetch_one(&db.pool)
        .await
        .unwrap(),
        1
    );

    db.cleanup().await;
}

