#[tokio::test]
async fn postgres_vnstat_final_output_classification_preserves_agent_failure_and_stream_contract() {
    let Some(db) = PgReliabilityTestDb::maybe_new().await else {
        return;
    };
    let client_id = "pg-vnstat-final-output-contract";
    let job_id = Uuid::new_v4();
    insert_client(&db.pool, client_id, Some(Uuid::new_v4())).await;
    insert_job_target_with_operation(
        &db.pool,
        job_id,
        client_id,
        JobCommand::NetworkTrafficImportVnstat {
            interfaces: vec!["eth0".to_string()],
            start_unix: 60,
        },
        "network_traffic_import_vnstat",
        None,
        "running",
        true,
        Some(Uuid::new_v4()),
        300,
        true,
    )
    .await;
    let state = postgres_app_state(&db);
    let wrong_stream = CommandOutput {
        job_id,
        stream: OutputStream::Stdout,
        data: br#"{"type":"network_traffic_import_vnstat","status":"collected"}"#.to_vec(),
        exit_code: Some(0),
        done: true,
    };
    assert_eq!(
        crate::job_traffic_import::apply_network_traffic_import_if_ready(
            &state,
            job_id,
            client_id,
            0,
            &wrong_stream,
            &[],
        )
        .await
        .unwrap(),
        crate::job_traffic_import::NetworkTrafficImportApply::Invalid(
            "network_traffic_import_invalid:final_output_invalid".to_string()
        )
    );

    let agent_failure = CommandOutput {
        job_id,
        stream: OutputStream::Stderr,
        data: b"vnstat executable not found".to_vec(),
        exit_code: Some(1),
        done: true,
    };
    assert_eq!(
        crate::job_traffic_import::apply_network_traffic_import_if_ready(
            &state,
            job_id,
            client_id,
            0,
            &agent_failure,
            &[],
        )
        .await
        .unwrap(),
        crate::job_traffic_import::NetworkTrafficImportApply::NotApplicable
    );
    assert_eq!(target_status(&db.pool, job_id, client_id).await, "running");

    db.cleanup().await;
}

#[tokio::test]
async fn postgres_vnstat_finalizer_terminalizes_the_invalid_stored_output_matrix() {
    let Some(db) = PgReliabilityTestDb::maybe_new().await else {
        return;
    };
    let cases = [
        (Uuid::new_v4(), "pg-vnstat-invalid-final-json"),
        (Uuid::new_v4(), "pg-vnstat-invalid-contiguous-batch"),
    ];
    for (job_id, client_id) in cases {
        insert_client(&db.pool, client_id, Some(Uuid::new_v4())).await;
        insert_job_target_with_operation(
            &db.pool,
            job_id,
            client_id,
            JobCommand::NetworkTrafficImportVnstat {
                interfaces: vec!["eth0".to_string()],
                start_unix: 60,
            },
            "network_traffic_import_vnstat",
            None,
            "running",
            true,
            Some(Uuid::new_v4()),
            300,
            false,
        )
        .await;
    }
    let persist = JobOutputPersistConfig {
        object_store: None,
        artifact_min_bytes: usize::MAX,
    };
    let invalid_final = CommandOutput {
        job_id: cases[0].0,
        stream: OutputStream::Status,
        data: b"{invalid-final-json".to_vec(),
        exit_code: Some(0),
        done: true,
    };
    db.repo
        .record_active_job_outputs_checked_with_config(
            cases[0].0,
            cases[0].1,
            &[invalid_final],
            persist,
        )
        .await
        .unwrap();

    let malformed_batch = CommandOutput {
        job_id: cases[1].0,
        stream: OutputStream::Status,
        data: b"{malformed-batch-json".to_vec(),
        exit_code: None,
        done: false,
    };
    let valid_final = CommandOutput {
        job_id: cases[1].0,
        stream: OutputStream::Status,
        data: serde_json::to_vec(&json!({
            "type": "network_traffic_import_vnstat",
            "status": "collected",
            "requested_start_unix": 60,
            "collected_until_unix": 120,
            "interfaces": ["eth0"],
            "sources": [{
                "interface": "eth0",
                "database_created_unix": null,
                "retained_start_unix": 60,
                "source_updated_unix": 120
            }],
            "batch_count": 1,
            "bucket_count": 0,
            "message": "collected"
        }))
        .unwrap(),
        exit_code: Some(0),
        done: true,
    };
    db.repo
        .record_active_job_outputs_checked_with_config(
            cases[1].0,
            cases[1].1,
            &[malformed_batch, valid_final],
            persist,
        )
        .await
        .unwrap();

    assert_eq!(
        crate::job_traffic_import::finalize_pending_network_traffic_imports(&postgres_app_state(
            &db
        ),)
        .await
        .unwrap(),
        2
    );
    for (job_id, client_id) in cases {
        assert_eq!(
            target_status(&db.pool, job_id, client_id).await,
            TARGET_STATUS_FAILED
        );
        assert_eq!(job_status(&db.pool, job_id).await, JOB_STATUS_FAILED);
        let message: String =
            sqlx::query_scalar("SELECT message FROM job_targets WHERE job_id=$1 AND client_id=$2")
                .bind(job_id)
                .bind(client_id)
                .fetch_one(&db.pool)
                .await
                .unwrap();
        assert!(message.starts_with("network_traffic_import_invalid:"));
    }
    assert_eq!(
        sqlx::query_scalar::<_, i64>(
            "SELECT count(*) FROM network_traffic_import_finalizations WHERE job_id=ANY($1)",
        )
        .bind(cases.map(|case| case.0).to_vec())
        .fetch_one(&db.pool)
        .await
        .unwrap(),
        0,
        "deterministic invalid output is terminal and its exact owner is acknowledged"
    );
    assert_eq!(
        sqlx::query_as::<_, (i64, i64)>(
            r#"
            SELECT
                (SELECT count(*) FROM traffic_counter_samples
                 WHERE client_id=ANY($1)),
                (SELECT count(*) FROM traffic_counter_rollups
                 WHERE client_id=ANY($1))
            "#,
        )
        .bind(cases.map(|case| case.1).to_vec())
        .fetch_one(&db.pool)
        .await
        .unwrap(),
        (0, 0),
        "invalid stored output cannot backfill traffic history"
    );
    assert_eq!(
        crate::job_traffic_import::finalize_pending_network_traffic_imports(&postgres_app_state(
            &db
        ),)
        .await
        .unwrap(),
        0,
        "terminal invalid output cannot remain forever pending"
    );
    db.cleanup().await;
}

#[tokio::test]
async fn postgres_vnstat_finalization_uses_a_durable_exact_work_owner() {
    let Some(db) = PgReliabilityTestDb::maybe_new().await else {
        return;
    };
    let protected_client = "pg-vnstat-finalize-protected";
    let gapped_client = "pg-vnstat-finalize-gapped";
    let protected_job = Uuid::new_v4();
    let gapped_job = Uuid::new_v4();
    for client_id in [protected_client, gapped_client] {
        insert_client(&db.pool, client_id, Some(Uuid::new_v4())).await;
    }
    for (job_id, client_id) in [
        (protected_job, protected_client),
        (gapped_job, gapped_client),
    ] {
        insert_job_target_with_operation(
            &db.pool,
            job_id,
            client_id,
            JobCommand::NetworkTrafficImportVnstat {
                interfaces: Vec::new(),
                start_unix: 60,
            },
            "network_traffic_import_vnstat",
            None,
            "running",
            true,
            Some(Uuid::new_v4()),
            1,
            true,
        )
        .await;
    }
    let chunk = CommandOutput {
        job_id: protected_job,
        stream: OutputStream::Status,
        data: br#"{"type":"network_traffic_import_vnstat_batch","batch_index":0,"buckets":[]}"#
            .to_vec(),
        exit_code: None,
        done: false,
    };
    let protected_final = CommandOutput {
        job_id: protected_job,
        stream: OutputStream::Status,
        data: br#"{"type":"network_traffic_import_vnstat","status":"collected"}"#.to_vec(),
        exit_code: Some(0),
        done: true,
    };
    db.repo
        .record_active_job_outputs_checked_with_config(
            protected_job,
            protected_client,
            &[chunk, protected_final],
            JobOutputPersistConfig {
                object_store: None,
                artifact_min_bytes: usize::MAX,
            },
        )
        .await
        .unwrap();
    let gapped_final = CommandOutput {
        job_id: gapped_job,
        stream: OutputStream::Status,
        data: br#"{"type":"network_traffic_import_vnstat","status":"collected"}"#.to_vec(),
        exit_code: Some(0),
        done: true,
    };
    db.repo
        .record_active_job_output_chunk_checked_with_config(
            gapped_job,
            gapped_client,
            1,
            &gapped_final,
            None,
            JobOutputPersistConfig {
                object_store: None,
                artifact_min_bytes: usize::MAX,
            },
        )
        .await
        .unwrap();

    let expired = db.repo.expire_control_timeout_targets(10).await.unwrap();
    assert_eq!(expired.len(), 1);
    assert_eq!(expired[0].job_id, gapped_job);
    assert_eq!(expired[0].status, TARGET_STATUS_CONTROL_TIMEOUT);
    assert_eq!(
        target_status(&db.pool, protected_job, protected_client).await,
        "running"
    );
    assert_eq!(
        target_status(&db.pool, gapped_job, gapped_client).await,
        TARGET_STATUS_CONTROL_TIMEOUT
    );
    let owner = db
        .repo
        .claim_network_traffic_import_finalization(30)
        .await
        .unwrap()
        .expect("contiguous output producer must enqueue exact finalization work");
    assert_eq!(owner.job_id, protected_job);
    assert_eq!(owner.client_id, protected_client);
    assert_eq!(owner.final_seq, 1);
    assert!(tokio::time::timeout(
        Duration::from_secs(1),
        db.repo.claim_network_traffic_import_finalization(30),
    )
    .await
    .expect("a competing consumer must skip the exact owned row")
    .unwrap()
    .is_none());
    sqlx::query(
        r#"
        UPDATE network_traffic_import_finalizations
        SET lease_until = now() - interval '1 second'
        WHERE job_id = $1 AND client_id = $2
        "#,
    )
    .bind(protected_job)
    .bind(protected_client)
    .execute(&db.pool)
    .await
    .unwrap();
    let replacement_owner = db
        .repo
        .claim_network_traffic_import_finalization(30)
        .await
        .unwrap()
        .expect("expired ownership must be recoverable without a held work lock");
    assert!(!owner.acknowledge().await.unwrap());
    assert!(replacement_owner
        .defer("vnStat server import retry pending", 30)
        .await
        .unwrap());
    assert!(db
        .repo
        .claim_network_traffic_import_finalization(30)
        .await
        .unwrap()
        .is_none());
    let retry_is_cooled: bool = sqlx::query_scalar(
        r#"
        SELECT next_attempt_at > now()
        FROM network_traffic_import_finalizations
        WHERE job_id = $1 AND client_id = $2
        "#,
    )
    .bind(protected_job)
    .bind(protected_client)
    .fetch_one(&db.pool)
    .await
    .unwrap();
    assert!(retry_is_cooled);
    db.cleanup().await;
}

#[tokio::test]
async fn postgres_gap_repair_finalizes_stored_done_output_in_the_chunk_transaction() {
    let Some(db) = PgReliabilityTestDb::maybe_new().await else {
        return;
    };
    let client_id = "pg-gap-finalization";
    let job_id = Uuid::new_v4();
    insert_client(&db.pool, client_id, Some(Uuid::new_v4())).await;
    insert_job_target_with_operation(
        &db.pool,
        job_id,
        client_id,
        JobCommand::Shell {
            argv: vec!["/bin/true".to_string()],
            pty: false,
        },
        "shell",
        None,
        "running",
        true,
        Some(Uuid::new_v4()),
        300,
        false,
    )
    .await;
    let persist = JobOutputPersistConfig {
        object_store: None,
        artifact_min_bytes: usize::MAX,
    };
    let final_output = CommandOutput {
        job_id,
        stream: OutputStream::Status,
        data: br#"{"type":"completed"}"#.to_vec(),
        exit_code: Some(0),
        done: true,
    };
    assert_eq!(
        db.repo
            .record_active_job_output_chunk_checked_with_config(
                job_id,
                client_id,
                1,
                &final_output,
                Some("2026-08-19T00:00:01Z".to_string()),
                persist,
            )
            .await
            .unwrap(),
        JobOutputWriteResult::Inserted
    );
    assert_eq!(target_status(&db.pool, job_id, client_id).await, "running");

    let prefix = CommandOutput {
        job_id,
        stream: OutputStream::Stdout,
        data: b"ready\n".to_vec(),
        exit_code: None,
        done: false,
    };
    let repaired = db
        .repo
        .record_active_job_output_chunk_and_finalize_if_ready_with_config(
            job_id,
            client_id,
            0,
            &prefix,
            Some("2026-08-19T00:00:00Z".to_string()),
            persist,
        )
        .await
        .unwrap();
    assert_eq!(repaired.write_result, JobOutputWriteResult::Inserted);
    assert_eq!(repaired.contiguous_final.unwrap().seq, 1);
    assert!(repaired.terminal_reconciliation_ready);
    assert_eq!(
        target_status(&db.pool, job_id, client_id).await,
        TARGET_STATUS_COMPLETED
    );
    assert_eq!(job_status(&db.pool, job_id).await, JOB_STATUS_COMPLETED);
    let (audit_count, event_count): (i64, i64) = sqlx::query_as(
        r#"
        SELECT
            (SELECT COUNT(*) FROM audit_logs
             WHERE action = 'job.target_result'
               AND metadata->>'job_id' = $1
               AND metadata->>'output_seq' = '1'),
            (SELECT COUNT(*) FROM job_terminal_events
             WHERE job_id = $2 AND client_id = $3 AND event_kind = 'target_terminalized')
        "#,
    )
    .bind(job_id.to_string())
    .bind(job_id)
    .bind(client_id)
    .fetch_one(&db.pool)
    .await
    .unwrap();
    assert_eq!((audit_count, event_count), (1, 1));

    let late = CommandOutput {
        job_id,
        stream: OutputStream::Stdout,
        data: b"late\n".to_vec(),
        exit_code: None,
        done: false,
    };
    let error = db
        .repo
        .record_active_job_output_chunk_and_finalize_if_ready_with_config(
            job_id, client_id, 2, &late, None, persist,
        )
        .await
        .unwrap_err();
    assert!(error.to_string().contains("job_target_not_active"));
    let output_count: i64 =
        sqlx::query_scalar("SELECT COUNT(*) FROM job_outputs WHERE job_id = $1 AND client_id = $2")
            .bind(job_id)
            .bind(client_id)
            .fetch_one(&db.pool)
            .await
            .unwrap();
    assert_eq!(output_count, 2);
    db.cleanup().await;
}

#[tokio::test]
async fn postgres_control_timeout_terminal_event_updates_schedule_and_webhooks() {
    let Some(db) = PgReliabilityTestDb::maybe_new().await else {
        return;
    };
    let client_id = "pg-client-scheduled-timeout";
    let job_id = Uuid::new_v4();
    insert_client(&db.pool, client_id, Some(Uuid::new_v4())).await;
    let operator = postgres_network_operator(&db.repo).await;
    let schedule = db
        .repo
        .create_schedule(
            postgres_shell_schedule_request("pg-timeout-schedule", client_id),
            &operator,
        )
        .await
        .unwrap();
    insert_job_target_with_operation(
        &db.pool,
        job_id,
        client_id,
        JobCommand::Shell {
            argv: vec![
                "/bin/sh".to_string(),
                "-lc".to_string(),
                "sleep 99".to_string(),
            ],
            pty: false,
        },
        "shell",
        Some(schedule.id),
        "running",
        true,
        Some(Uuid::new_v4()),
        1,
        true,
    )
    .await;

    let expired = db.repo.expire_control_timeout_targets(10).await.unwrap();
    assert_eq!(expired.len(), 1);
    assert_eq!(expired[0].status, TARGET_STATUS_CONTROL_TIMEOUT);
    let state = postgres_app_state(&db);
    assert!(
        crate::job_dispatcher::drain_job_terminal_workflow_for_test(&state)
            .await
            .unwrap()
            > 0
    );

    assert_eq!(
        job_status(&db.pool, job_id).await,
        JOB_STATUS_CONTROL_TIMEOUT
    );
    let (failure_count, last_job_status, last_job_id) =
        schedule_outcome_row(&db.pool, schedule.id).await;
    assert_eq!(failure_count, 1);
    assert_eq!(last_job_status, JOB_STATUS_CONTROL_TIMEOUT);
    assert_eq!(last_job_id, Some(job_id));
    assert!(
        webhook_event_exists(
            &db.pool,
            "job.status",
            &format!("job:{job_id}:status:{JOB_STATUS_CONTROL_TIMEOUT}")
        )
        .await
    );
    assert!(
        webhook_event_exists(
            &db.pool,
            "schedule.job_finished",
            &format!("schedule:{}:job:{job_id}:finished", schedule.id)
        )
        .await
    );
    assert!(
        webhook_event_exists(
            &db.pool,
            "schedule.failed",
            &format!("schedule:{}:job:{job_id}:failed", schedule.id)
        )
        .await
    );
    assert_eq!(processed_terminal_event_count(&db.pool, job_id).await, 2);
    db.cleanup().await;
}

#[tokio::test]
async fn postgres_terminal_event_retry_keeps_schedule_and_webhooks_idempotent() {
    let Some(db) = PgReliabilityTestDb::maybe_new().await else {
        return;
    };
    let client_id = "pg-client-terminal-event-retry";
    let job_id = Uuid::new_v4();
    insert_client(&db.pool, client_id, Some(Uuid::new_v4())).await;
    let operator = postgres_network_operator(&db.repo).await;
    let schedule = db
        .repo
        .create_schedule(
            postgres_shell_schedule_request("pg-terminal-event-retry", client_id),
            &operator,
        )
        .await
        .unwrap();
    insert_job_target_with_operation(
        &db.pool,
        job_id,
        client_id,
        JobCommand::Shell {
            argv: vec![
                "/bin/sh".to_string(),
                "-lc".to_string(),
                "sleep 99".to_string(),
            ],
            pty: false,
        },
        "shell",
        Some(schedule.id),
        "running",
        true,
        Some(Uuid::new_v4()),
        1,
        true,
    )
    .await;

    let expired = db.repo.expire_control_timeout_targets(10).await.unwrap();
    assert_eq!(expired.len(), 1);
    let state = postgres_app_state(&db);
    crate::job_dispatcher::drain_job_terminal_workflow_for_test(&state)
        .await
        .unwrap();

    let job_event_id = format!("job:{job_id}:status:{JOB_STATUS_CONTROL_TIMEOUT}");
    let schedule_finished_event_id = format!("schedule:{}:job:{job_id}:finished", schedule.id);
    let schedule_failed_event_id = format!("schedule:{}:job:{job_id}:failed", schedule.id);
    let (failure_count, last_job_status, last_job_id) =
        schedule_outcome_row(&db.pool, schedule.id).await;
    assert_eq!(failure_count, 1);
    assert_eq!(last_job_status, JOB_STATUS_CONTROL_TIMEOUT);
    assert_eq!(last_job_id, Some(job_id));
    assert_eq!(
        webhook_event_count(&db.pool, "job.status", &job_event_id).await,
        1
    );
    assert_eq!(
        webhook_event_count(
            &db.pool,
            "schedule.job_finished",
            &schedule_finished_event_id
        )
        .await,
        1
    );
    assert_eq!(
        webhook_event_count(&db.pool, "schedule.failed", &schedule_failed_event_id).await,
        1
    );

    sqlx::query(
        r#"
        UPDATE job_terminal_events
        SET
            processing_status = 'failed',
            processed_at = NULL,
            next_attempt_at = NULL,
            lease_id = NULL,
            lease_until = NULL,
            last_error = NULL
        WHERE job_id = $1
          AND event_kind = 'job_terminalized'
        "#,
    )
    .bind(job_id)
    .execute(&db.pool)
    .await
    .unwrap();
    crate::job_dispatcher::drain_job_terminal_workflow_for_test(&state)
        .await
        .unwrap();

    let (failure_count, last_job_status, last_job_id) =
        schedule_outcome_row(&db.pool, schedule.id).await;
    assert_eq!(failure_count, 1);
    assert_eq!(last_job_status, JOB_STATUS_CONTROL_TIMEOUT);
    assert_eq!(last_job_id, Some(job_id));
    assert_eq!(
        webhook_event_count(&db.pool, "job.status", &job_event_id).await,
        1
    );
    assert_eq!(
        webhook_event_count(
            &db.pool,
            "schedule.job_finished",
            &schedule_finished_event_id
        )
        .await,
        1
    );
    assert_eq!(
        webhook_event_count(&db.pool, "schedule.failed", &schedule_failed_event_id).await,
        1
    );
    assert_eq!(processed_terminal_event_count(&db.pool, job_id).await, 2);
    db.cleanup().await;
}

#[tokio::test]
async fn postgres_terminal_event_completion_is_fenced_by_the_exact_owner_token() {
    let Some(db) = PgReliabilityTestDb::maybe_new().await else {
        return;
    };
    let job_id = Uuid::new_v4();
    let event_id = Uuid::new_v4();
    let original_owner = Uuid::new_v4();
    let replacement_owner = Uuid::new_v4();
    sqlx::query(
        r#"
        INSERT INTO jobs (
            id, command_type, status, target_count, payload_hash,
            request_fingerprint, completed_at
        ) VALUES ($1, 'shell', 'completed', 0, repeat('a', 64), $2, now())
        "#,
    )
    .bind(job_id)
    .bind(format!("terminal-owner-{job_id}"))
    .execute(&db.pool)
    .await
    .unwrap();
    sqlx::query(
        r#"
        INSERT INTO job_terminal_events (
            id, event_kind, job_id, status, processing_status,
            lease_id, lease_until
        ) VALUES (
            $1, 'job_terminalized', $2, 'completed', 'processing',
            $3, now() + interval '60 seconds'
        )
        "#,
    )
    .bind(event_id)
    .bind(job_id)
    .bind(original_owner)
    .execute(&db.pool)
    .await
    .unwrap();

    assert!(!db
        .repo
        .mark_job_terminal_event_processed(event_id, replacement_owner)
        .await
        .unwrap());
    sqlx::query("UPDATE job_terminal_events SET lease_id = $2 WHERE id = $1")
        .bind(event_id)
        .bind(replacement_owner)
        .execute(&db.pool)
        .await
        .unwrap();
    assert!(!db
        .repo
        .mark_job_terminal_event_failed(event_id, original_owner, "stale owner")
        .await
        .unwrap());
    assert!(db
        .repo
        .mark_job_terminal_event_failed(event_id, replacement_owner, "retry")
        .await
        .unwrap());
    let row: (String, Option<Uuid>, Option<chrono::DateTime<Utc>>, String) = sqlx::query_as(
        r#"
        SELECT processing_status, lease_id, lease_until, last_error
        FROM job_terminal_events
        WHERE id = $1
        "#,
    )
    .bind(event_id)
    .fetch_one(&db.pool)
    .await
    .unwrap();
    assert_eq!(row, ("failed".to_string(), None, None, "retry".to_string()));
    db.cleanup().await;
}

